const CAT_4={"id":4,"n":"Повсякденне життя","sub":"Life Long Learning","e":"🏡","col":"c4","blocks":[{"n":"🏡 БЛОК 1: Побут, дім та самообслуговування","e":"","cards":[[302,"Оптимізація прибирання (Метод зон)","<div class=\"rule-note\">🏠 <b>Метод зон</b> — поділ оселі на зони і прибирання по одній зоні кожен день. Результат: квартира постійно достатньо чиста без великих «генеральних прибирань».</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Як ділити на зони</b><br>5 зон на 5 робочих днів: наприклад, Пн — кухня, Вт — ванна/туалет, Ср — вітальня, Чт — спальня, Пт — коридор/підсобні. Зони підбираються під твоє планування — головне послідовність. Суб/нед: лише підтримання, не глибоке прибирання.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Щоденні 15 хвилин</b><br>У зоні дня: швидко протерти, пропилососити, привести до ладу. Паралельно: «по дорозі» — проходячи повз, забирай речі не на місці. Раз на тиждень: весь цикл завершено, квартира чиста без одного великого зусилля.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Інструменти і порядок</b><br>Принцип «зверху вниз»: спочатку пил із полиць, потім підлога — не навпаки. Мікрофіброві серветки замість паперових — ефективніші і дешевші. Одне відро з базовим набором засобів — не бігай за кожним з іншої кімнати.</div></div><div class=\"final-note\">📌 Метод FlyLady (flyladay.net) — популярна система на цьому принципі. Головне: зона дня — не «ідеально», а «краще ніж було». Перфекціонізм у прибиранні вбиває регулярність.</div>"],[303,"Експрес-готування здорової їжі","<div class=\"rule-note\">🍳 <b>Швидке здорове готування</b> — не кулінарний курс, а 4–5 базових технік що дозволяють приготувати повноцінну їжу за 15–30 хвилин. Шлях до цього: batch cooking + прості рецепти з коротким списком інгредієнтів.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Batch cooking (готування наперед)</b><br>Раз на тиждень (1–1.5 год): зварити крупу/бобові, запекти порцію овочів, відварити яйця, підготувати основу для салатів. Зберігання: герметичні контейнери в холодильнику 3–4 дні. З готових напівфабрикатів — будь-який прийом їжі збирається за 5 хвилин.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>5 базових технік</b><br>Запікання в духовці (190°C, 20–25 хв): мінімум дій, максимум результату. Wok/сковорода на сильному вогні: овочі + білок, 7–10 хвилин. Яйця: варені, омлет, пашот — швидко і поживно. Смузі: заморожені овочі/фрукти + йогурт/молоко. Зернові: гречка/рис/кускус у термосі або мультиварці.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Швидкі здорові поєднання</b><br>Тарілка здорового харчування (ВООЗ): ½ — овочі, ¼ — зернові, ¼ — білок. Прості варіанти: відварений рис + консервований нут + свіжі овочі. Яйця + цільнозерновий хліб + авокадо. Гречка + куряча грудка + заморожені овочі на пару.</div></div><div class=\"final-note\">📌 Не потрібен складний рецепт щоб їсти здорово. 10–15 простих страв що тобі смакують і ти вмієш готувати — надійніше ніж 100 рецептів що ніколи не приготуєш. Список продуктів для швидкого здорового тижня: яйця, курятина, кефір, овочі (свіжі + заморожені), бобові, крупи.</div>"],[304,"Розбір гардероба (Метод «3 коробки»)","<div class=\"rule-note\">👕 <b>Метод 3 коробок</b> — швидка ревізія гардероба без паралічу аналізу. Три коробки: «Лишити», «Прибрати» (продати/подарувати/викинути), «Сумніваюсь». Простий алгоритм рішення для кожної речі.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Алгоритм розбору</b><br>Дістань всі речі однієї категорії (всі футболки, всі штани). Кожну річ — рішення за 10 секунд: носив за останній рік? підходить? подобається? «Так» на всі три — «Лишити». Хоча б одне «ні» — «Прибрати». Якщо не можеш вирішити — «Сумніваюсь».</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Категорія «Сумніваюсь»</b><br>Упакуй і поклади на 3 місяці. Якщо за цей час не витягнув — значить не потрібне. Правило Marie Kondo: «чи викликає радість» — суб'єктивно, але працює для емоційно прив'язаних речей.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Як позбутись речей</b><br>Продати: OLX, Vinted, місцеві групи у Facebook. Подарувати: фонди вживаного одягу (Remarket, Red Cross Україна). Викинути: лише дійсно зношене, не придатне для носіння. Правило входу: нова річ входить — стара виходить.</div></div><div class=\"final-note\">📌 Мета не «мінімалізм» — мета гардероб де все носиш. Сезонне зберігання: позасезонний одяг — в окремі пакети під ліжко або на антресолі. Розбір по категоріях, а не по місцях (не «шафа», а «всі светри» — звідусіль).</div>"],[305,"Читання та розшифровка маркувань","<div class=\"rule-note\">🏷️ <b>Маркування</b> на продуктах і речах містить важливу інформацію про безпеку, склад і догляд. Вміння читати його економить гроші і захищає здоров'я.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Маркування продуктів харчування</b><br>«Вжити до» (Use by): після цієї дати продукт небезпечний — не споживати. «Краще до» (Best before): після цієї дати смак/якість гірша, але безпечно. Склад: інгредієнти — від більшої частки до меншої. Якщо цукор у першій трійці — продукт з високим вмістом цукру.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Маркування одягу (символи догляду)</b><br>Таз з водою: прання (цифра = °C). Таз з рукою: лише ручне прання. Трикутник: відбілювання (закреслений — заборонено). Квадрат з колом всередині: сушіння в барабані. Праска: прасування (точки = температура). Коло: хімчистка.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Маркування хімії і побутових товарів</b><br>GHS-піктограми (ромби з символами): черепи — токсично, вогонь — займисто, оклик — подразник. E-числа в продуктах: не всі шкідливі — E300 це аскорбінова кислота (вітамін C). Перевіряй конкретний E-код, а не відкидай все підряд.</div></div><div class=\"final-note\">📌 Додаток для сканування: Yuka (продукти та косметика) — сканує штрих-код і показує оцінку складу. Open Food Facts — відкрита база даних продуктів. Перед купівлею нового засобу для дому — перевір сумісність з матеріалами поверхонь.</div>"],[306,"Базовий побутовий ремонт","<div class=\"rule-note\">🔧 <b>Базовий ремонт вдома</b> — 10–15 навичок що вирішують 80% дрібних побутових проблем без виклику майстра. Інструменти + вміння їх використовувати = незалежність і економія.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Базовий набір інструментів</b><br>Молоток, викрутки (хрест + шліц), пасатижі, рулетка, рівень (будівельний або додаток на телефоні), перфоратор або дриль, набір свердел, ізоляційна стрічка, монтажна пістолет і силікон. Якісні інструменти купуй раз — дешеві ламаються і збивають різьбу.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Найчастіші задачі</b><br>Повісити картину/полицю: визнач де балки (шукач балок або магніт), правильний дюбель під матеріал стіни (бетон/гіпсокартон/цегла). Герметизація кранів: ФУМ-стрічка або сантехнічний лляний льон. Усунення скрипу підлоги: саморіз у скрипуче місце. Заклеїти тріщину на стіні: шпаклівка + серпянка.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Електрика: лише безпечне</b><br>Перевірити розетку або вимикач (мультиметр або індикаторна викрутка). Замінити лампочку. Замінити розетку або вимикач (завжди відключай автомат на щитку). Всі роботи у розподільній коробці, зі щитком, з кабелями у стінах — електрик.</div></div><div class=\"final-note\">📌 YouTube — найкращий підручник для конкретних задач: «як замінити кран», «як повісити полицю на гіпсокартон» — є тисячі відео. Перед ремонтом: сфотографуй стан «до». Не знаєш — не чіпай газ і несучі конструкції.</div>"],[307,"Система догляду за рослинами","<div class=\"rule-note\">🌱 <b>Догляд за рослинами</b> — розуміння потреб конкретної рослини, а не загальні поради. Більшість кімнатних рослин гине від надмірного поливу, а не від браку.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Полив: головне правило</b><br>Більшість кімнатних рослин: полив коли верхній шар ґрунту (2–3 см) підсохнув. Суккуленти і кактуси: рідко — раз на 2–3 тижні, взимку ще рідше. Тропічні (монстера, потос): вологий ґрунт, але без застою. Перевірка: паличка або палець у ґрунт.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Світло і розміщення</b><br>Прямий сонячний промінь через скло: більшість кімнатних рослин не витримують без акліматизації. Яскраве непряме: більшість декоративних. Тінь: папороті, сансев'єрія, замiокулькас. Перевертай горщик раз на місяць: рослина росте рівномірно.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Просте розкладання по задачах</b><br>Щотижня: перевіряй ґрунт і поливай за потребою. Щомісяця: протирай листя від пилу (важливо для фотосинтезу), перевіряй на шкідники. Щороку навесні: пересадка якщо корені вийшли з дренажного отвору, підживлення рідким добривом (березень–вересень).</div></div><div class=\"final-note\">📌 Додаток Planta або Greg: нагадування про полив і догляд за конкретними рослинами. Для початківців: монстера, потос, сансев'єрія, замiокулькас — витривалі і прощають помилки.</div>"],[308,"Організація домашньої аптечки","<div class=\"rule-note\">💊 <b>Домашня аптечка</b> — не запас всіх ліків, а мінімальний набір для першої допомоги і типових ситуацій. Перевіряється двічі на рік: терміни придатності і поповнення.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Мінімальний склад аптечки</b><br>Перев'язка: бинти (вузький + широкий), лейкопластир різних розмірів, стерильні серветки. Антисептики: хлоргексидин 0.05%, перекис водню 3%. Знеболення/жар: парацетамол + ібупрофен (різні механізми). Антигістамін: лоратадин або цетиризин. Вугілля активоване. Термометр. Джгут еластичний.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Зберігання</b><br>Темне прохолодне місце (не ванна — вологість руйнує ліки). Недоступно для дітей. Ліки в оригінальній упаковці з інструкцією. Окрема секція для рецептурних ліків членів родини. Список того що є — на дверцях аптечки.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Перевірка двічі на рік</b><br>Перевіряй терміни — вийшов термін: утилізуй (не у смітник і не в каналізацію — здай в аптеку). Поповнюй витрачене одразу, не відкладай. Контакти: лікар, екстрена (103), токсикологічний центр (+38 044 465-83-33 Україна).</div></div><div class=\"final-note\">📌 Аптечка для авто — окрема, відповідно до вимог МВС України. Якщо є хронічно хворі — окрема секція з їхніми ліками плюс запас на 30 днів. Не зберігай ліки без упаковки — переплутаєш у стресі.</div>"],[309,"Пакування валізи (Метод капсули)","<div class=\"rule-note\">🧳 <b>Капсульне пакування</b> — мінімальний набір речей що поєднуються між собою у максимальну кількість образів. Мета: ручна поклажа замість зданого багажу, свобода пересування.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Принцип капсули</b><br>Нейтральна кольорова гама (3 кольори максимум): кожна річ поєднується з кожною. Базис: 2 низи + 3 верхи + 1 верхній одяг = 6+ варіантів образів. Взуття: 2 пари максимум (одна універсальна, одна тематична — спорт/вечірня).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Техніки пакування</b><br>Метод скручування (rolling): зменшує об'єм і зменшує зморшки. Пакувальні куби (packing cubes): групують речі категоріями, легко знайти. Важке внизу (ближче до коліщат), легке зверху. Взуття у пакети — не забруднюють одяг.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Список для перевірки</b><br>Документи: паспорт, страховка, бронювання (офлайн копії). Технології: зарядки, адаптер, павербанк (лише ручна поклажа). Гігієна: формат 100мл для ручної поклажі. Ліки: запас + рецепт якщо рецептурні. Завжди беру з собою: зарядник і нижня білизна — в ручну поклажу навіть якщо є багаж.</div></div><div class=\"final-note\">📌 Правило 1–2–3–4 для тижневої поїздки: 1 пара взуття, 2 низи, 3 верхи, 4 нижні білизни + туалетне приладдя. Влізе у 20л рюкзак. Лоукости: перевір максимальні розміри ручної поклажі — відрізняються у кожного авіаперевізника.</div>"],[310,"Ергономіка кухні","<div class=\"rule-note\">🍴 <b>Ергономіка кухні</b> — розміщення предметів так щоб мінімізувати зусилля і час готування. Принцип: все що використовуєш часто — під рукою; рідко — далі.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Зони кухні</b><br>Трикутник: холодильник → мийка → плита — основний маршрут. Зберігай поруч із зоною використання: ножі і дошки — біля зони нарізки, каструлі — біля плити, специї — над або поруч плити. Посуд — біля мийки або посудомийки.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Організація полиць і ящиків</b><br>Нижні ящики: важке (каструлі, сковорідки). Верхні полиці: рідко використовуване. На рівні очей: щоденне. Органайзери для ящиків: кришки від каструль — окремо вертикально. Контейнери однакового розміру в холодильнику — більше влізе.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Мінімальний набір для ефективної кухні</b><br>Ножі: 1 великий кухарський + 1 маленький — достатньо для 90% задач. Гострий ніж — безпечніший за тупий. Дошки: мінімум 2 (сире м'ясо окремо). Каструлі: 1 велика + 1 середня + сковорода + сотейник — базовий набір.</div></div><div class=\"final-note\">📌 Регулярна ревізія: що не використовував 6 місяців — прибрати або продати. Правило «кожна річ — своє місце»: після використання повертається туди звідки взяв. Це не педантизм — це швидка кухня.</div>"],[311,"Підтримка порядку «по дорозі»","<div class=\"rule-note\">🚶 <b>Підтримання порядку «по дорозі»</b> — мікродії під час звичних переміщень по оселі що запобігають накопиченню безладу. Не окремий час на прибирання — вбудований в рух.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Правило «порожніх рук не буває»</b><br>Ідеш з кімнати в кімнату — візьми щось що має бути там куди йдеш. Вставаючи з дивана — забери склянку на кухню. Йдеш у ванну — захопи рушник що висить не там. Маленькі дії постійно &gt; велике прибирання раз на місяць.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Правило «однієї хвилини»</b><br>Якщо задача займає менше хвилини — роби зараз: протри краплі на плиті, поклади чашку у посудомийку замість мийки, повісь куртку замість кидати на стілець. Відкладена дрібниця стає проблемою через накопичення.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Вечірній reset (10–15 хвилин)</b><br>Щовечора перед сном: кухня чиста, речі на своїх місцях, стільці задвинуті, подушки рівно. Ранок у впорядкованій оселі — інший психологічний стан. Не ідеально — достатньо добре.</div></div><div class=\"final-note\">📌 Системний підхід: кожна річ має постійне місце. Якщо постійно щось лежить «не там» — місце погано обране. Змін місце під реальну поведінку, а не навпаки.</div>"],[312,"Виведення плям першою допомогою","<div class=\"rule-note\">🧺 <b>Виведення плям</b> — ефективне у перші хвилини. Чим швидше — тим легше. Більшість плям що «не відмиваються» — це засохлі плями що не обробили вчасно.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Загальне правило першої допомоги</b><br>Дій одразу: промокни (не три!) надлишок чистою серветкою. Три — розмазуєш і заганяєш глибше у волокна. Холодна вода: краще для більшості свіжих плям. Гаряча — фіксує білкові плями (кров, молоко, яйце).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>По типу плями</b><br>Кров: одразу холодна вода + перекис водню (на бавовні). Вино/сік: сіль (вбирає) → холодна вода. Жир: рідкий засіб для посуду → витримати → промити. Ручка (кулькова): медичний спирт або рідина для зняття лаку (без ацетону). Трава: мило + холодна вода.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Аптечка від плям вдома</b><br>Рідкий засіб для посуду (жир). Перекис водню 3% (кров, органіка). Медичний спирт (чорнило, ручка). Гліцерин (висохлий жир, засохлі плями). Лимонна кислота або лимонний сік (іржа, дубильні речовини). Не змішуй засоби — реакція може пошкодити тканину.</div></div><div class=\"final-note\">📌 Завжди тестуй засіб на непомітному куточку тканини — особливо для делікатних матеріалів (шовк, вовна). Перед пранням з виведенням плями: перевір ярлик догляду.</div>"],[313,"Планування закупівель (Meal Prep)","<div class=\"rule-note\">🛒 <b>Meal Prep</b> — планування меню і закупівель на тиждень наперед. Результат: менше стресу «що їсти», менше харчових відходів, менше спонтанних і дорогих покупок.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Планування меню на тиждень</b><br>Визнач 3–5 вечерь (сніданки і обіди зазвичай простіші). Скоротувана база: 2–3 рецепти з тими самими інгредієнтами — менше закупівель, менше відходів. Принцип: плануй від того що є в холодильнику і потребує використання.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Список закупівель</b><br>Формат по зонах магазину: овочі/фрукти, молочне, м'ясо/риба, бакалія, заморожене — не бігаєш туди-сюди. Перевіряй що є вдома перед списком. Телефон як список: будь-який нотатник або Google Keep — спільний список з партнером/сім'єю.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Зменшення відходів</b><br>«Носова» зона холодильника (на рівні очей): продукти що треба використати першими — не ховай вглиб. FIFO: First In First Out — нове позаду, старе спереду. Стебла, листя, залишки овочів → суп або бульйон.</div></div><div class=\"final-note\">📌 Додатки: Bring!, AnyList — спільні списки закупівель. Правило: не ходи в магазин голодним і без списку — підвищує спонтанні покупки. Раз на місяць: «тиждень холодильника» — готуй лише з того що є, без нових закупівель крім базового.</div>"],[314,"Сезонна підготовка оселі","<div class=\"rule-note\">🍂 <b>Сезонна підготовка оселі</b> — двічі на рік (весна і осінь) профілактика і адаптація житла до сезону. Запобігає проблемам і готує до комфортного проживання.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Осіння підготовка (вересень–жовтень)</b><br>Перевір герметичність вікон (тест: папірець між рамою і вікном — якщо виймається легко — є протяг). Замінити або почистити фільтри опалення. Перевірити систему опалення до початку сезону. Переодягнути гардероб: літнє в зберігання, зимове дістати. Перевірити щітку для снігу і лопату.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Весняна підготовка (березень–квітень)</b><br>Генеральне прибирання після опалювального сезону. Мити вікна — найкраща видимість весь рік. Перевірити кондиціонер до літа (чистка фільтрів). Провітрити і прати зимовий текстиль перед зберіганням.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Контрольний список два рази на рік</b><br>Перевірити: аптечку (терміни), вогнегасник (тиск), димові сповіщувачі (батарейки), ліхтарики (батарейки). Замінити: батарейки в пультах і годинниках якщо потрібно. Задокументувати: сфотографувати стан оселі — корисно при оренді чи страхуванні.</div></div><div class=\"final-note\">📌 Малий бюджет для великого ефекту: герметик для вікон (100–200 грн) = зниження втрат тепла. Чистка радіаторів від пилу = ефективніший обігрів. Профілактика дешевша ніж ремонт.</div>"],[315,"Безпечне використання хімії","<div class=\"rule-note\">⚗️ <b>Безпечне використання побутової хімії</b> — знання що не можна змішувати і як зберігати. Небезпечні суміші утворюються у кожному домі якщо не знати базових правил.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Що НІКОЛИ не змішувати</b><br>Хлорвмісні засоби + аміак (окремо у туалетних і скляних засобах) → токсичні хлораміни. Хлор + оцет/кислоти → хлоровий газ. Перекис водню + оцет → перкислота (корозивна). Правило: один засіб — один раз, добре змий водою перед наступним.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Захист під час прибирання</b><br>Гумові рукавички: при роботі з агресивними засобами (засоби для прочищення труб, відбілювачі). Вентиляція: відкрите вікно або увімкнена витяжка при роботі з хлором і розчинниками. Не розпилюй у напрямку обличчя. При попаданні в очі: промий водою 15 хвилин, зверніться до лікаря.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Зберігання</b><br>Оригінальна упаковка з кришкою. Недоступно для дітей (верхні полиці або на замку). Не поруч з харчовими продуктами. Не поруч з джерелами тепла (горючі засоби). Утилізація: не виливай у каналізацію концентровані засоби — розведи водою або здай у пункти збору небезпечних відходів.</div></div><div class=\"final-note\">📌 Мінімалізм у хімії: 5–7 універсальних засобів покривають всі потреби краще ніж 20 вузькоспеціалізованих. Натуральні альтернативи для делікатних поверхонь: харчова сода + оцет (не змішуй одночасно — нейтралізують одне одного, використовуй по черзі).</div>"],[316,"Дії в аварійних ситуаціях","<div class=\"rule-note\">🚨 <b>Аварійні ситуації вдома</b> — знання дій наперед зменшує паніку і збитки. Перші хвилини вирішальні. Базові дії мають бути доведені до автоматизму.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Пожежа</b><br>Невелике займання (кошик для паперу): вогнегасник або ковдра для гасіння. Якщо вийшло з-під контролю: виходь негайно, не збирай речі, закрий двері (сповільнює поширення), телефон 101. Якщо дим у коридорі: пересувайся нижче (дим піднімається), закрий рот і ніс. Ніколи не використовуй ліфт.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Прорив труби / затоплення</b><br>Перекрий воду: вентиль під мийкою або загальний вентиль квартири (знай де він зараз). Відключи електрику в кімнаті де вода. Дзвони сусідам знизу якщо вода йде до них. ЖЕК або аварійна служба: зафіксуй час і збиток фото/відео для страхового випадку.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Витік газу</b><br>Не вмикай і не вимикай електрику (іскра може запалити). Відкрий вікна і двері. Перекрий газовий кран (жовтий кран на трубі — перпендикулярно = закрито). Виходь з квартири. Телефон 104 (газова аварійна) — з вулиці.</div></div><div class=\"final-note\">📌 Аварійний список на холодильнику або в телефоні: 101 (пожежа), 102 (поліція), 103 (швидка), 104 (газ), ЖЕК, аварійна сантехніка. Знай де: лічильники газу/води/електрики і як їх перекрити — до аварії, не під час.</div>"],[317,"Облаштування домашнього офісу","<div class=\"rule-note\">💻 <b>Домашній офіс</b> — робоче місце що підтримує продуктивність і не руйнує здоров'я. Три критерії: ергономіка, освітлення, відсутність відволікань.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Ергономіка робочого місця</b><br>Монітор: верхній край — на рівні очей або трохи нижче, відстань 50–70 см. Крісло: ноги повністю на підлозі, кут коліна 90°, поперек підтримується. Клавіатура: лікті під кутом 90°, зап'ястя не задранні вгору. Стоячий стіл або підставка для ноутбука — суттєво зменшують навантаження на шию.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Освітлення</b><br>Природне освітлення зліва або прямо (не з-за спини — відблиски на екрані). Настільна лампа: не направлена прямо в монітор. Колірна температура: вдень — нейтральна (4000K), ввечері — тепла (2700–3000K). Режим «нічного екрану» після 18:00 — зменшує вплив синього світла на сон.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Мінімізація відволікань</b><br>Визначене місце лише для роботи: не диван, не ліжко — мозок асоціює простір з режимом. Порядок на столі: лише те що потрібно зараз. Шумоізоляція: навушники з шумопоглинанням (ANC) або беруші — ефективний і дешевий варіант. Телефон лицем вниз або в іншій кімнаті під час фокус-часу.</div></div><div class=\"final-note\">📌 Мінімальний бюджет: підставка під ноутбук (300–500 грн) + зовнішня клавіатура + миша дають майже той самий ефект що і дорогий стіл. Пріоритет: крісло — на ньому не економ.</div>"],[318,"Правильний догляд за взуттям","<div class=\"rule-note\">👟 <b>Догляд за взуттям</b> — подовжує термін служби вдвічі і більше. 10 хвилин раз на тиждень замість покупки нового взуття раз на рік.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Щоденне і після носіння</b><br>Знімай взуття за допомогою ложки — не ламай задник. Провітрюй після носіння: 24 год перш ніж вдягти знову (гігієна і форма). Не залишай вологе взуття в поліетиленовому пакеті — гниє. Вставляй колодки або папір для збереження форми.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Чищення і захист за матеріалом</b><br>Шкіра гладка: щітка від бруду → крем для взуття під колір → полірувальна щітка. Раз на місяць: просочення захисним спреєм. Замша/нубук: спеціальна гумова щітка, лише суха. Крем і воду — не застосовуй. Текстиль/кросівки: пральна машина лише за маркуванням, або вручну м'якою щіткою.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Зберігання</b><br>Не в поліетилені — шкіра «задихається». Тканинні мішки або оригінальні коробки. Колодки або набиті газетою — зберігають форму при зберіганні. Ротація: 2–3 пари в регулярному використанні — кожна відпочиває 1–2 дні.</div></div><div class=\"final-note\">📌 Своєчасна підошва і набійки: 300–400 грн у шевця = ще 1–2 роки носіння. Мокре взуття: суши при кімнатній температурі, не на батареї — деформується і розшаровується.</div>"],[319,"Швидке прасування та відпарювання","<div class=\"rule-note\">👔 <b>Прасування і відпарювання</b> — з правильною технікою займає вдвічі менше часу. Відпарювач для більшості тканин — швидше і безпечніше ніж праска.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Температурний режим праски</b><br>Одна крапка (до 110°C): шовк, синтетика. Дві крапки (до 150°C): вовна. Три крапки (до 200°C): бавовна, льон. Прасуй від нижньої температури до вищої, щоб не перегріватись. З паром — тільки відповідні тканини (не шовк).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Техніки швидкого прасування</b><br>Прасуй поки злегка вологий — легше розгладжується. Сорочка: комір → манжети → рукави → спина → перед. Не кружляй праскою — прямі рухи від себе. Відпарювач: тримай вертикально, не торкайся тканини насадкою (для більшості тканин). Швидко: повісь одяг у ванній під час гарячого душу — волога пара прибирає легкі зморшки.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Запобігання зморшкам</b><br>Не залишай вологий одяг у пральній машині: одразу вішай або кидай у сушарку. Складай правильно: футболки методом KonMari (вертикально) — зморшок менше ніж у стосі. Вішай речі після носіння — зморшки від сидіння/стояння зникають від провітрювання.</div></div><div class=\"final-note\">📌 Відпарювач вертикальний (від 500 грн): для більшості речей краще ніж праска — швидше і немає ризику спалити. Пральна сітка при пранні делікатних речей — зменшує зморшки у прасуванні.</div>"],[320,"Сортування побутових відходів","<div class=\"rule-note\">♻️ <b>Сортування відходів</b> — розділення за категоріями для подальшої переробки. Знижує кількість сміття що потрапляє на полігони. В Україні інфраструктура переробки різна залежно від міста.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Базові категорії</b><br>Змішані (залишки): харчові відходи, забруднений папір, засохлі фарби. Папір/картон: чистий, сухий, без їжі. Скло: пляшки, банки (кришки окремо). Пластик: ПЕТ-пляшки (1), ПНД (2), ПП (5) — найчастіше приймають. Метал: бляшані консерви, фольга. Небезпечні: батарейки, ліки, лампочки — окремо.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Як дізнатись що приймають у твоєму місті</b><br>Сайт EcoMap (ecomap.org.ua) — карта пунктів прийому вторсировини в Україні. Контейнери біля будинку: читай маркування. Супермаркети: Silpo, Novus, АТБ — мають пункти прийому батарейок. Залізо/метал: пункти прийому металобрухту.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Мінімальний старт</b><br>Почни з одного: окрема коробка для батарейок — найпростіше. Додай ПЕТ-пляшки: стискай, займають мало місця. Не треба ідеальної системи з 10 контейнерів — один крок краще нуля. Харчові відходи: компостер на балконі або дачі, або відро у смітник (більшість міст ще не мають роздільного збору органіки).</div></div><div class=\"final-note\">📌 Правило «чистого і сухого»: більшість переробних заводів відхиляє забруднені матеріали. Прополосни пляшки перед викидом. Не сортуй те чого не знаєш — краще в загальне сміття ніж «брудна» переробка.</div>"],[321,"Побутовий мінімалізм","<div class=\"rule-note\">📦 <b>Побутовий мінімалізм</b> — не аскетизм і порожні кімнати. Це свідоме рішення тримати лише те що використовуєш і що приносить цінність. Менше речей = менше часу на обслуговування, прибирання і пошук.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Аудит речей: з чого починати</b><br>Не намагайся одразу весь дім. Одна зона за раз: ящик тумбочки, одна полиця, підстільний простір. Критерії збереження: використовував за останній рік? Якщо ні — прибрати. Дублікати: залиш один найкращий екземпляр.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Зупинити приплив нових речей</b><br>Правило 24–48 год: імпульсивну покупку відклади на добу — 90% бажань зникають. Правило «одне входить — одне виходить». Питання перед покупкою: де це буде зберігатись? Коли використаю? Чи вже є щось подібне?</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Цифровий мінімалізм паралельно</b><br>Непотрібні додатки, дублікати фото, підписки що не читаєш — займають увагу і ресурси так само як фізичні речі. Раз на рік: аудит підписок (email, стримінги, сервіси). Розвантажений телефон і комп'ютер = швидша робота і менше відволікань.</div></div><div class=\"final-note\">📌 Мінімалізм — не ціль, а інструмент. Мета: звільнити час і увагу для того що важливо. Не порівнюй своє «мало» з чужим — у кожного свій оптимальний рівень.</div>"]]},{"n":"💳 БЛОК 2: Фінанси, покупки та грамотне споживання","e":"","cards":[[322,"Бюджет за правилом 50/30/20","<div class=\"rule-note\">💰 <b>Правило 50/30/20</b> — простий фреймворк розподілу доходу після сплати податків. 50% — потреби, 30% — бажання, 20% — заощадження і борги. Не ідеальна система, але найпростіша точка старту.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>50% — Потреби (Needs)</b><br>Те без чого не обійтись: оренда/іпотека, комунальні, продукти, транспорт до роботи, мінімальний необхідний одяг, мінімальні страховки, мінімальні виплати по боргах. Якщо потреби перевищують 50% — переглянь найбільші статті (житло, транспорт).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>30% — Бажання (Wants)</b><br>Те що покращує якість життя але не обов'язкове: ресторани, розваги, стримінги, хобі, подорожі, нові речі понад необхідне. Не «погані витрати» — це усвідомлений вибір. Якщо вкладаєшся у 30% — все гаразд.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>20% — Заощадження і борги</b><br>Пріоритет: спочатку подушка безпеки (3 місячних витрати), потім погашення боргів з високими відсотками, потім довгострокові заощадження. Автоматичний переказ у день зарплати — найефективніший спосіб не витратити.</div></div><div class=\"final-note\">📌 Пропорція орієнтовна — адаптуй під реальність: в Україні з середньою зарплатою 50% на потреби може бути занадто мало. Головне: заощадження спочатку, бажання — з того що лишилось.</div>"],[323,"Аналіз складників продуктів","<div class=\"rule-note\">🔍 <b>Читання складу продуктів</b> — навичка що допомагає відрізнити маркетинг від реального вмісту. «Натуральний», «organic», «без цукру» — не завжди означає те що здається.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Загальні правила читання складу</b><br>Інгредієнти — від більшої частки до меншої. Якщо цукор у першій трійці — продукт з високим вмістом. Цукор ховається під назвами: мальтоза, декстроза, фруктозний сироп, концентрат соку, карамельний колір. «Без цукру» може містити підсолоджувачі (ксиліт, стевію, аспартам).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Жири і добавки</b><br>Трансжири (частково гідрогенізовані олії): уникати. Пальмова олія — не шкідлива у помірних кількостях (суперечлива репутація через екологію, а не здоров'я). E-числа: не всі шкідливі. E300 = вітамін C, E440 = пектин (яблучний). Перевіряй конкретний код а не всі підряд.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Маркетингові ловушки</b><br>«Мультизерновий» — не означає цільнозерновий: може бути рафінована борошно різних зернових. «Натуральний аромат» — хімічно ідентичний штучному, просто з природного джерела. «Знежирений» — часто містить більше цукру для компенсації смаку. «0 трансжирів» — може містити до 0.5г на порцію (лазівка в маркуванні).</div></div><div class=\"final-note\">📌 Додаток Yuka: скануй штрих-код — показує оцінку складу і що конкретно в ньому є. Open Food Facts — відкрита база. Правило: коротший склад з зрозумілими словами — зазвичай кращий вибір.</div>"],[324,"Захист від імпульсивних покупок","<div class=\"rule-note\">🛍️ <b>Імпульсивні покупки</b> — незаплановані придбання під впливом емоцій або маркетингу. За дослідженнями ритейлу, значна частка покупок непланована. Захист — система, а не сила волі.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Правила перед покупкою</b><br>Правило 24 год: хочу купити — чекаю добу. Для великих покупок — 48–72 год. Більшість бажань зникають. Питання: де зберігатиметься? Коли реально використаю? Чи вже є щось подібне? Якщо не відповідаєш легко — пауза.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Захист від маркетингових тригерів</b><br>«Лише сьогодні» і «залишилось 2 штуки»: штучне обмеження — стандартна техніка. Відпиши від розсилок магазинів — видаляй рекламні листи що читаєш. Видали збережені картки з онлайн-магазинів — тертя при оплаті = більше часу подумати. Не заходь на сайти магазинів «просто подивитись».</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Список бажань замість кошика</b><br>Веди список бажаних покупок (Notion, нотатки). Перед зарплатою: переглянь список — чи досі хочеш? Знижки відстежуй через Honey або Hotline — купуй коли ціна впала, не коли «знижка».</div></div><div class=\"final-note\">📌 Cashback і бонусні програми: добре якщо ти й так купуєш — не причина купувати більше. Бюджет на «спонтанне»: виділи невелику суму на місяць — витрачай без провини, але в межах.</div>"],[325,"Формування подушки безпеки","<div class=\"rule-note\">🛡️ <b>Подушка безпеки</b> — фінансовий резерв для непередбачених витрат. Мета: 3–6 місячних витрат на доступному рахунку. Захищає від потреби брати кредит при кожній несподіванці.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Скільки накопичити</b><br>Мінімум: 1 місяць витрат — перший крок. Оптимум: 3–6 місяців витрат — залежить від стабільності доходу. Нестабільний дохід (фриланс, бізнес): краще 6+ місяців. Де зберігати: депозит з можливістю дострокового зняття або накопичувальний рахунок — не готівка під матрацом.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Як накопичити швидше</b><br>Автоматичний переказ: у день зарплати — фіксована сума на окремий рахунок. «Заплати собі першому» перед іншими витратами. Навіть 500–1000 грн на місяць — за рік 6000–12000 грн. Поповнення «зайвими» грошима: повернення переплати, подарункові, премії.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Коли використовувати</b><br>Тільки справжні надзвичайні ситуації: хвороба, втрата роботи, термінова поломка. Не для запланованих великих витрат (відпустка, нова техніка) — це окреме накопичення. Після використання: відновлюй подушку — це постійний пріоритет.</div></div><div class=\"final-note\">📌 Окремий рахунок з психологічним бар'єром: не картка що завжди під рукою. Деякі банки дозволяють «заморозити» рахунок — не використовуєш без свідомого рішення. Подушка безпеки — основа, потім всі інші фінансові цілі.</div>"],[326,"Порівняння вартості за одиницю ваги","<div class=\"rule-note\">⚖️ <b>Ціна за одиницю</b> — реальна вартість товару при порівнянні різних упаковок. Більша упаковка не завжди дешевша за одиницю. Розрахунок займає 10 секунд і може суттєво зекономити.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Як рахувати</b><br>Формула: Ціна ÷ Кількість = Ціна за одиницю. Порівнюй в однакових одиницях: ціна за 100г, за 1л, за 1 шт. Приклад: 500г за 60 грн = 12 грн/100г. 1кг за 100 грн = 10 грн/100г. Кілограм вигідніший на 17%.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Коли більша упаковка НЕ вигідна</b><br>Якщо не встигнеш використати до терміну — реальна вартість вища через викинуте. Якщо займає непропорційно багато місця. Якщо якість знижується після відкриття (кава, горіхи). Вигода від розміру: лише якщо реально використаєш повністю.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>В магазині: де шукати ціну за одиницю</b><br>В Україні більшість мереж вказують ціну за 100г/1л на ціннику під товаром. Якщо не вказано — рахуй в калькуляторі телефону. Маркери акцій «вигідна ціна» — порівнюй з цінами у конкурентів, а не з попередньою ціною в тому ж магазині.</div></div><div class=\"final-note\">📌 Правило: фірмові товари vs власна марка магазину (private label) — різниця в ціні часто 20–40% при схожому складі. Перевіряй склад і ціну за 100г, а не лише впізнаваність бренду.</div>"],[327,"Аудит щомісячних передплат","<div class=\"rule-note\">📱 <b>Аудит передплат</b> — систематична перевірка всіх активних підписок і регулярних платежів. Більшість людей переплачують за підписки що не використовують — ефект «небачених» списань.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Як знайти всі передплати</b><br>Переглянь виписку картки за 2–3 місяці: регулярні суми від онлайн-сервісів. Google Play / App Store → Передплати — показує активні. Email: пошук «квитанція», «receipt», «subscription» — знайде підтвердження.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Оцінка кожної передплати</b><br>Питання до кожної: використовував активно за останній місяць? Платив би повну ціну якщо б не підписався раніше? Є безкоштовна альтернатива? Якщо ні хоч на одне — скасовуй або знижуй тариф.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Оптимізація</b><br>Сімейний план: Spotify, Netflix, iCloud — один на кількох людей суттєво дешевший. Річна передплата замість місячної: зазвичай 20–30% знижка. Ротація: підписуйся на один стримінг на квартал, потім міняй — замість трьох одночасно.</div></div><div class=\"final-note\">📌 Трекер підписок: Truebill (Bobby в Україні, або просто таблиця Google Sheets): список + дата списання + сума. Аудит раз на квартал — підписки накопичуються непомітно. Скасовуй без жалю: можна підписатись знову якщо буде потреба.</div>"],[328,"Повернення товарів за законом","<div class=\"rule-note\">⚖️ <b>Повернення товарів</b> — право споживача в Україні захищено Законом «Про захист прав споживачів». Більшість людей не знають своїх прав і приймають відмову продавця.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Повернення без причини (не харчових товарів)</b><br>Протягом 14 днів після покупки: можна повернути непродовольчий товар належної якості якщо не підійшов (колір, розмір, фасон). Умови: не використовувався, збережено товарний вигляд і упаковку. Продавець зобов'язаний прийняти або запропонувати обмін.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Повернення неякісного товару</b><br>Гарантійний строк: повернення або ремонт за рахунок продавця. Якщо ремонт понад 14 днів — право на заміну або повернення коштів. Чек не обов'язковий: достатньо будь-якого доказу покупки (виписка картки, свідок). Відмова продавця: письмова претензія → Держпродспоживслужба → суд.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Онлайн-покупки</b><br>Закон «Про захист прав споживачів» + правила платформи. Нова Пошта/Укрпошта: право огляду перед оплатою при накладеному платежі. Розбірки через PayPal, Apple Pay або банк: оскарження транзакції (chargeback) — ефективний механізм при відмові продавця.</div></div><div class=\"final-note\">📌 Товари що НЕ підлягають поверненню без причини: лікарські засоби, парфуми, білизна, ювелірні вироби та ін. — повний перелік у Постанові КМУ №172. Завжди зберігай чеки і листування до закінчення гарантії.</div>"],[329,"Безпечне використання кредиток","<div class=\"rule-note\">💳 <b>Кредитна картка</b> — зручний інструмент або боргова пастка — залежно від того як користуєшся. Правильне використання дає cashback і грейс-період безкоштовно. Неправильне — відсотки поглинають економію.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Грейс-період: як використовувати безкоштовно</b><br>Грейс-період (зазвичай 30–55 днів): якщо повністю погашаєш борг до кінця — не платиш відсотків. Правило: використовуй кредитку як дебетову — витрачай лише те що є на рахунку, погашай повністю кожного місяця. Мінімальний платіж — не мета, це пастка: відсотки нараховуються на весь борг.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Cashback і бонуси</b><br>Cashback 1–3% на всі покупки або підвищений на категорії (пальне, супермаркети, ресторани). Аеромилі: вигідні якщо реально літаєш — рахуй реальну вартість бонусу. Cashback виправданий лише якщо погашаєш повністю — інакше відсотки перекривають виграш.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Безпека кредитної картки</b><br>Ніколи не знімай готівку з кредитки — комісія + відсотки з першого дня. Встанови ліміт онлайн-транзакцій. Сповіщення про кожну операцію — одразу помітиш несанкціоноване списання. При втраті — блокуй одразу через додаток.</div></div><div class=\"final-note\">📌 Кредитна картка — не додатковий дохід. Якщо не можеш повністю погасити щомісяця — кредитка не для тебе зараз. Відсотки на кредитках в Україні: зазвичай від 36% до 80% і вище річних — одне з найдорожчих позичень.</div>"],[330,"Автоматизація заощаджень","<div class=\"rule-note\">🤖 <b>Автоматизація заощаджень</b> — налаштування автоматичних переказів що усувають потребу в силі волі. «Заплати собі першому» — найефективніший принцип особистих фінансів.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Як налаштувати</b><br>У день надходження зарплати: автоматичний переказ на накопичувальний рахунок. Розмір: починай з 5–10% — сума що не відчувається суттєво. Поступово збільшуй. Більшість банків (Monobank, ПриватБанк, ПУМБ): налаштування регулярних переказів у додатку.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Правило «кошики» у Monobank / ПриватБанку</b><br>Розподіл на цільові рахунки: «Подушка безпеки», «Відпустка», «Великі покупки». Автоматично поповнюються у день зарплати. Психологічний ефект: гроші «вже витрачені» на цілі — менше спокуси витратити.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Округлення і мікрозаощадження</b><br>Функція «округлення» у деяких банках: кожна покупка округляється до 10 грн, різниця йде на накопичення. Невідчутне, але накопичується. Правило «зайвого рубля»: наприкінці місяця залишок на картці — переказуй на накопичення.</div></div><div class=\"final-note\">📌 Не тримай всі накопичення на поточному рахунку — витрачається непомітно. Окремий рахунок без картки = менше спокуси. Депозит або ОВДП (облігації внутрішнього держборгу України) для середньострокових цілей — дають вищу доходність ніж поточні рахунки.</div>"],[331,"Покупки на вторичному ринку","<div class=\"rule-note\">🔄 <b>Вторинний ринок</b> — покупка вживаних товарів. Значна економія при правильному підході: техніка, одяг, меблі, книги — зазвичай 30–70% від нової ціни.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Де купувати в Україні</b><br>OLX: найбільший майданчик, всі категорії. Facebook Marketplace і групи: локальні пропозиції, часто можна торгуватись. Vinted: одяг і взуття. Rozetka «вживані товари», відповідні розділи маркетплейсів. Комісійні магазини: меблі, техніка.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Перевірка перед покупкою</b><br>Техніка: особиста зустріч і перевірка при передачі. Телефон: IMEI (набери *#06#) — перевіряй через imei.info (чи не вкрадений, кількість циклів АКБ для iPhone). Одяг: фото при денному світлі, реальні розміри. Великі суми: зустрічайся у публічних місцях.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Безпечна оплата</b><br>Не переказуй до отримання товару незнайомцю (крім перевірених майданчиків з гарантією). OLX: «Безпечна угода» — гроші зберігаються у системі до підтвердження отримання. Нова Пошта: оплата при отриманні (накладений платіж) для онлайн-продавців.</div></div><div class=\"final-note\">📌 Продавай теж: те що не використовуєш — джерело коштів на потрібне. Фотографуй при денному освітленні, пиши реальний опис — продається швидше. Розрахунок вартості «свого часу»: якщо купуєш нове, не треба витрачати час на пошук вживаного.</div>"],[332,"Податкові вирахування та пільги","<div class=\"rule-note\">🧾 <b>Податкові вирахування і пільги</b> — законні способи зменшити суму ПДФО. Більшість платників податків в Україні не використовують доступні механізми повернення.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Податкова знижка в Україні</b><br>Фізичні особи — платники ПДФО можуть подати декларацію і отримати повернення частини сплаченого ПДФО за: навчання в університеті, іпотечні відсотки, добровільне медичне страхування, пожертви благодійним організаціям (є ліміти). Подається щорічно до 1 травня за попередній рік.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>ФОП і єдиний податок</b><br>ФОП 1 групи: не платить ПДФО, лише ЄСВ і єдиний податок (фіксована сума). ФОП 2 групи: 20% від мінімальної зарплати. ФОП 3 групи: 5% від доходу. Вибір групи залежить від обсягу і виду діяльності. Консультація з бухгалтером при відкритті — не витрата, а економія.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Пільги на комунальні послуги</b><br>Субсидія: призначається при низькому доході через Портал Дія або ЦНАП. Пільги для окремих категорій (ветерани, пенсіонери, многодітні) — уточнюй актуальний перелік на сайті Мінсоцполітики. Щороку підтверджується або переоформляється.</div></div><div class=\"final-note\">📌 Декларація про майновий стан і доходи: подавай навіть якщо роботодавець утримує ПДФО — для отримання податкової знижки. Дія.gov.ua — подача в електронному вигляді. Строк: до 1 травня за попередній календарний рік.</div>"],[333,"Оптимізація витрат у подорожах","<div class=\"rule-note\">✈️ <b>Оптимізація витрат у подорожах</b> — не відмова від поїздок, а розумний підхід до бронювання і бюджету. Гнучкість у датах і типі житла дає найбільшу економію.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Авіаквитки: коли і як купувати</b><br>Оптимальне вікно: 6–8 тижнів до вильоту для коротких напрямків. Гнучкі дати: навіть +/-3 дні суттєво впливають на ціну. Пошукові сервіси: Google Flights (календар цін), Skyscanner (оповіщення про зниження). Лоукости: Ryanair, Wizz Air — ручна поклажа включена, зданий багаж коштує.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Житло: вибір між варіантами</b><br>Booking.com vs Airbnb: порівнюй для конкретного міста. Hostel: у 2–5 разів дешевше готелю, добрий нетворкінг. Апартаменти з кухнею: економія на харчуванні компенсує різницю в ціні. Розташування: 20 хвилин від центру транспортом часто дешевше ніж у центрі на 50%.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Харчування в подорожі</b><br>Сніданок в готелі: часто переоцінений — перевіряй чи включений і чи вартий доплати. Супермаркет замість туристичного ресторану: 60–70% економії на харчуванні. Обід замість вечері в ресторані: в більшості країн обідні меню дешевші ніж вечірні.</div></div><div class=\"final-note\">📌 Cashback картка в подорожі: Revolut або Wise — конвертація за міжбанківським курсом без комісій. Страховка подорожі: не пропускай — одна госпіталізація окупає тисячі поїздок. Порівнюй на Insurance.ua або напряму у страховиків.</div>"],[334,"Вибір техніки за критерієм цінність/ціна","<div class=\"rule-note\">📱 <b>Вибір техніки</b> — рішення що впливає на бюджет і досвід на роки. Мета: оптимальне співвідношення потреб і ціни, а не найдешевше або найдорожче.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Визначення реальних потреб</b><br>Список задач що виконуватиме пристрій: конкретно і чесно. «Запас на майбутнє» — часто виправдання переплати. Питання: які функції використовуватиму реально кожен день? Яку тривалість служби очікую? Чи є аналогічний пристрій дешевший що покриває 90% потреб?</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Надійні джерела порівняння</b><br>Україна: Hotline.ua (ціни), Rozetka (відгуки), DOU.ua Tech (технічні порівняння для IT). Міжнародні: Rtings.com (TV, монітори, навушники) — детальні виміри. Wirecutter (NYTimes) — незалежні рекомендації. YouTube-огляди: перевіряй що автор не є партнером виробника.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Коли брати флагман, коли середній клас</b><br>Флагман виправданий: фотограф купує камеру або телефон з кращою камерою, дизайнер — монітор з точною кольоропередачею. Середній клас достатній: офісна робота, базовий мультимедіа, звичайне використання. Попередня модель флагмана через рік після релізу: 30–40% знижка при незначній різниці в характеристиках.</div></div><div class=\"final-note\">📌 Гарантія і сервіс: в Україні сервісна мережа виробника або авторизований партнер — питання до покупки. Сірий імпорт: немає офіційної гарантії. Refurbished (відновлені): офіційно відновлені виробником — надійніше ніж вживані, дешевше ніж нові.</div>"],[335,"Етичний торг","<div class=\"rule-note\">🤝 <b>Торг</b> — нормальна частина ринкових відносин у багатьох контекстах. Не агресивний тиск, а переговори де обидві сторони шукають взаємовигідне рішення.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Де торгуватись доречно</b><br>Ринки, базари, приватні продавці. Вживані товари (OLX, авто, нерухомість). Великі покупки в магазинах (побутова техніка, меблі, електроніка) — особливо при оплаті готівкою. Послуги: ремонт, дизайн, консалтинг — при тривалому співробітництві.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Техніка переговорів</b><br>Дізнайся ринкову ціну: Hotline, OLX, конкуренти — знаєш мінімум. Перша пропозиція: нижче цільової щоб залишити простір. Мовчання після пропозиції — потужний інструмент. Не пояснюй надто: «Я можу 800» краще ніж «Дайте за 800 бо...»</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Коли зупинитись</b><br>Якщо ціна вже справедлива — агресивний торг шкодить відносинам. Дрібниці: не торгуйся до копійки — витрачаєш своїй час і псуєш враження. Правило: мінімальна економія 5–10% від суми = варто спробувати. Менше — зазвичай не варте зусиль.</div></div><div class=\"final-note\">📌 Альтернативне підсолоджування: «А якщо я куплю два?», «Якщо готівкою?», «Якщо заберу сьогодні?» — іноді дають знижку де ціна «фіксована». Поважай ціну невеликих приватних підприємців — їхня маржа набагато менша ніж у мережевих магазинів.</div>"],[336,"Планування великих покупок","<div class=\"rule-note\">🗓️ <b>Планування великих покупок</b> — холодильник, автомобіль, ноутбук, ремонт — рішення що впливає на бюджет роками. Незапланована велика покупка часто веде до кредиту і переплати.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Список і горизонт планування</b><br>Список великих покупок на рік: що потрібно, орієнтовна сума, бажана дата. Це дає час: накопичити, дочекатись розпродажу, дослідити варіанти. Пріоритет: що впливає на якість життя або продуктивність найбільше?</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Коли купувати: сезонні розпродажі</b><br>Техніка: листопад (Black Friday), січень (після Нового року). Одяг: кінець сезону — знижки до 50–70%. Автомобілі: кінець кварталу — дилери виконують план продажів. Нерухомість: осінь і зима — менше покупців, більше переговорної позиції.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Накопичення замість кредиту</b><br>Розрахунок: сума ÷ місяці = щомісячне накопичення. Відкладай на окремий рахунок. Відсотки по кредиту на побутову техніку: реально рахуй повну вартість покупки з відсотками — часто +20–30% до ціни. Виняток: безвідсоткова розстрочка від магазину (справді 0% без прихованих умов).</div></div><div class=\"final-note\">📌 Правило: якщо не готовий купити за готівку прямо зараз — ще не готовий купити взагалі. Великі покупки у кредит без крайньої необхідності = платиш за своє ж майбутнє більше.</div>"],[337,"Фінансова кібергігієна","<div class=\"rule-note\">🔐 <b>Фінансова кібергігієна</b> — захист банківських рахунків і особистих даних від шахраїв. Соціальна інженерія (маніпуляція) — основний метод: більшість жертв самі передають дані.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Правила яких ніколи не порушувати</b><br>Банк ніколи не питає CVV код, повний номер картки, PIN або OTP-код по телефону — ніколи. Якщо хтось просить — шахрай, клади слухавку. Не переходь за посиланнями з SMS або Viber від «банку» — вводь адресу вручну. Не встановлюй додатки «служби безпеки банку».</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Захист рахунків</b><br>Двофакторна автентифікація: увімкни для банківського додатку і email. Унікальні паролі для банків і email — не ті що скрізь. Менеджер паролів: Bitwarden (безкоштовний), 1Password — надійно зберігає унікальні паролі. Перевірка витоку: haveibeenpwned.com — дізнайся чи твій email в базах витоків.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Liміти і сповіщення</b><br>Встанови ліміти: добовий ліміт на списання, ліміт онлайн-покупок — зменшує збиток при компрометації. SMS або push про кожну операцію: підключи. Окрема картка для онлайн-покупок з мінімальним балансом — не тримай на ній більше ніж плануєш витратити.</div></div><div class=\"final-note\">📌 Фішинг сайти: перевіряй URL — одна змінена літера (замість monobank.ua → monob4nk.ua). Замок https: наявність не гарантує безпеку — шахраї теж купують сертифікати. При підозрі на злом: заблокуй картку в додатку і зателефонуй на офіційну гарячу лінію банку.</div>"],[338,"Опрацювання психології грошей","<div class=\"rule-note\">🧠 <b>Психологія грошей</b> — наші рішення щодо грошей рідко раціональні. Упередження (biases) впливають на фінансову поведінку більше ніж знання. Розуміння своїх патернів — перший крок.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Поширені психологічні пастки</b><br>Ефект «легких грошей»: більш схильні витрачати подаровані або знайдені гроші ніж зароблені. Mental accounting: «гроші на відпочинок» і «гроші на їжу» — фізично однакові, але поводимось по-різному. Anchoring: перша ціна що побачив — стає орієнтиром («знижка» від завищеної ціни).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Loss aversion і status quo</b><br>Страх втрати сильніший за радість від придбання — тому тримаємо збиткові інвестиції (продати = зафіксувати втрату). Status quo bias: схильність не змінювати поточний стан навіть якщо зміна вигідна. Аудит підписок і банків — боротьба з цим ефектом.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Практична протидія</b><br>Автоматизація: рішення про заощадження прийняте раз — не щомісяця. Правило 24 год: пауза перед покупкою — нейтралізує емоційні рішення. Відокремлення емоцій від грошей: «ця знижка закінчується» — не причина купити, якщо не планував.</div></div><div class=\"final-note\">📌 Книга: «Психологія грошей» Моргана Гаузела — прочитати варто: короткі есе про ірраціональну поведінку з грошима. Не підручник з інвестування — книга про мислення.</div>"],[339,"Щомісячний фінансовий рев'ю","<div class=\"rule-note\">📊 <b>Щомісячний фінансовий огляд</b> — 30 хвилин раз на місяць що дають повну картину фінансового стану і дозволяють коригувати курс вчасно.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Що переглядати щомісяця</b><br>Доходи vs витрати: зведення за місяць. Відповідність плану (50/30/20 або твоя система). Прогрес до цілей: подушка, накопичення, борги. Нові передплати або повторювані витрати що з'явились.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Інструменти для відстеження</b><br>Monobank / ПриватБанк: категоризація витрат у додатку — автоматична. Додатки: Monefy, Wallet (Budget Planner) — ручний ввід. Google Sheets: повний контроль і гнучкість. Вибирай те що реально будеш використовувати, не найскладніше.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Питання для огляду</b><br>Що витратив більше ніж планував і чому? Яку ціль виконав — відзнач. Що змінити на наступний місяць: одна конкретна дія. Чи є великі витрати що плануються — внести в бюджет заздалегідь.</div></div><div class=\"final-note\">📌 Регулярність важливіша за деталізацію: поверхневий огляд щомісяця краще ніж ідеальний раз на рік. Заплануй у календарі: останній день місяця — 30 хвилин фінансового огляду.</div>"],[340,"Вибір банківських продуктів","<div class=\"rule-note\">🏦 <b>Вибір банківських продуктів</b> — рахунки, картки, депозити — різні умови в різних банках при однакових потребах. Порівняння перед вибором дає реальну вигоду.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Поточний рахунок і картка</b><br>Критерії: cashback за твоїми категоріями витрат, безкоштовне зняття готівки (кількість і ліміт), мобільний додаток (якість і надійність), вартість обслуговування. Monobank і ПриватБанк: найпоширеніші в Україні, безкоштовне обслуговування.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Депозит</b><br>Порівнюй відсоткову ставку, термін, умови дострокового зняття (важливо для подушки безпеки). ФГВФО (Фонд гарантування вкладів) гарантує до 200 000 грн — розподіляй між кількома банками якщо більше. Ставки: порівнюй на Finance.ua або Minfin.com.ua.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>ОВДП (облігації внутрішнього держзайму)</b><br>Альтернатива депозиту: державні облігації України. Дохідність: зазвичай вища ніж депозит. Мінімальна сума: від 1000 грн. Доступ: через банки або брокерів. ПДФО: не оподатковуються (перевіряй актуальність пільги). Ризик: кредитний ризик держави.</div></div><div class=\"final-note\">📌 Не тримай всі гроші в одному банку — ризик. Регулярно переглядай умови: банки змінюють тарифи. Захист: ФГВФО покриває до 200 000 грн на вкладника в одному банку.</div>"],[341,"Навчання діточок фінансовій грамотності","<div class=\"rule-note\">👧 <b>Фінансова грамотність дітей</b> — звички з грошима формуються у дитинстві. Практика важливіша за теорію: реальні гроші і реальні рішення навчають краще ніж розмови.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>По вікових групах</b><br>3–6 років: монети і банкноти — назви, що можна купити. Концепція «заплатив — отримав». 7–10 років: кишенькові гроші з обміркованими правилами витрат. Копілка для цілей. 11–14 років: рахунок у банку, картка з лімітом. Планування витрат на місяць. 15+: бюджет на особисті потреби, заробіток, відповідальність.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Кишенькові гроші: як організувати</b><br>Регулярно (не за запитом) — формує звичку планування. Не прив'язуй до домашніх обов'язків — це плутає «зарплату» і «участь у сім'ї». Не відбирай як покарання — гроші не інструмент маніпуляції. Нехай помиляється: витратив все в перший день — учиться чекати до наступного тижня.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Практичні уроки</b><br>Магазин разом: «порівняй ціни, яке вигідніше за 100г?» Ціль і накопичення: «хочеш X? Скільки треба відкладати?» Рахунок в ресторані: «давай разом перевіримо чи правильно порахували». Дорога дорога: «авто чи транспорт — порахуємо різницю?»</div></div><div class=\"final-note\">📌 Книги для дітей про гроші: «Багатий тато, бідний тато для підлітків» (Кіосакі). Ігри: Cashflow, Монополія — гарні симулятори фінансових рішень. Головне: не навчати «заробляти» — навчати «управляти тим що маєш».</div>"]]},{"n":"🩺 БЛОК 3: Здоров'я, тіло, сон та енергія","e":"","cards":[[342,"Гігієна сну","<div class=\"rule-note\">😴 <b>Гігієна сну</b> — набір звичок що покращують якість і тривалість сну. Дорослим потрібно 7–9 годин. Хронічний недосип менше 6 годин впливає на когнітивні функції, імунітет і метаболізм.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Регулярність важливіша за тривалість</b><br>Однаковий час підйому щодня — навіть у вихідні. Це стабілізує циркадний ритм краще ніж будь-що інше. «Відсипатись у вихідні» збиває ритм на 1–2 дні. Мозок не «накопичує» сон: накопичується лише борг сну.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Середовище для сну</b><br>Температура: 16–19°C — оптимальна для більшості людей. Темрява: щільні штори або маска. Тиша або білий шум (є безкоштовні додатки). Телефон: не в ліжку — синє світло зменшує продукцію мелатоніну мінімум на 30 хвилин після використання.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>За 1–2 години до сну</b><br>Уникай: екрани, кофеїн (кава, чай, кола), сильні фізичні навантаження, яскраве освітлення. Допомагає: тепла ванна/душ (парадоксально — знижує температуру тіла після), читання паперової книги, легке розтягування.</div></div><div class=\"final-note\">📌 Мелатонін: не снодійне — сигнал часу сну. Ефективний при зміні часових поясів або збитому ритмі (0.5–1 мг за 30 хв до сну — мінімальна ефективна доза). Якщо проблеми зі сном тривають понад 3 тижні — до лікаря: може бути апное або тривожний розлад.</div>"],[343,"Контроль питного режиму","<div class=\"rule-note\">💧 <b>Питний режим</b> — достатня гідрація впливає на концентрацію, енергію і фізичний стан. Зневоднення навіть на 1–2% від маси тіла знижує когнітивні функції і самопочуття.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Скільки пити</b><br>Загальна рекомендація: 30–35 мл на кг маси тіла на добу. При спеці, фізичній активності, хворобі — більше. Колір сечі: блідо-жовтий — норма, темно-жовтий — потрібно більше. «8 склянок» — популярний міф без наукового обґрунтування для всіх.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Коли і як пити</b><br>Не чекай спраги — це вже сигнал зневоднення. Вранці після підйому: 1–2 склянки (компенсує втрати за ніч). За 30 хв до їжі — не під час (не розбавляє травні ферменти суттєво за помірного пиття). Звичка: пляшка 0.5–1л на столі під час роботи.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Що рахується</b><br>Вода, несолодкий чай, кава (помірно — є невеликий діуретичний ефект але загалом гідратує), супи, фрукти і овочі. Що НЕ компенсує: солодкі напої, алкоголь — навпаки, збільшують потребу у воді. Мінеральна vs звичайна: немає суттєвої різниці для гідрації.</div></div><div class=\"final-note\">📌 Смарт-пляшки з відліком або нагадуванням: корисні але не обов'язкові — достатньо пляшки на очах. Тригер: кожна година за комп'ютером = ковток води.</div>"],[344,"Щоденна суглобова разминка","<div class=\"rule-note\">🤸 <b>Суглобова розминка</b> — рух суглобів через повний діапазон для підтримання рухливості і профілактики болю. 5–10 хвилин вранці або після тривалого сидіння.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Базова послідовність (5 хв)</b><br>Шия: кола, нахили (повільно). Плечі: кола вперед і назад. Лікті: згинання-розгинання, пронація-супінація. Зап'ястя: кола, згинання. Тазостегнові: кола, відведення. Коліна: кола стоячи або лежачи. Гомілки і стопи: кола, підйоми на носки. Кожен рух: 5–10 разів.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Розминка після сидіння (3 хв)</b><br>Для офісних працівників після 1–2 год роботи: вставай і рухайся. Нахили в сторони (хребет). Поворoti тулуба. Розгинання рук за голову (грудний відділ). Присідання 10 разів або хода 2 хвилини. Мета: не замінити спорт — розбити статичне навантаження.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Мобільність vs гнучкість</b><br>Гнучкість: пасивний діапазон (можу розтягнутись з допомогою). Мобільність: активний контроль (можу рухатись самостійно в повному діапазоні) — функціонально важливіша. Мобільність розвивається через активні рухи, а не лише пасивне розтягування.</div></div><div class=\"final-note\">📌 Ранкова суглобова розминка: 5 хвилин що суттєво зменшують ранкову скутість особливо після 35 років. YouTube: канали FitnessBlender, Tom Merrick (Bodyweight Warrior) — безкоштовні програми мобільності.</div>"],[345,"Перша домедична допомога","<div class=\"rule-note\">🚑 <b>Перша домедична допомога</b> — дії до приїзду медиків що можуть врятувати життя. Базові навички: зупинка кровотечі, СЛР, Heimlich — повинен знати кожен.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Зупинка кровотечі</b><br>Пряме натискання: щільна тканина або бинт, натискай без перерви мінімум 10 хвилин. Не знімай пов'язку — якщо просочилась, накладай нову зверху. Артеріальна кровотеча (яскраво-червона, пульсує): джгут вище рани — час накладання вказуй маркером на шкірі або записуй.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>СЛР (серцево-легенева реанімація)</b><br>Перевір свідомість → зови допомогу (103) → 30 натискань на грудину (глибина 5–6 см, частота 100–120/хв) → 2 вдихи → повтори. Якщо є дефібрилятор (AED) — увімкни і слідуй голосовим інструкціям. Не переставай поки не прибудуть медики або людина не прийде до тями. Пройди практичний курс СЛР — теорія не замінює практику.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Задуха (прийом Хеймліха)</b><br>Доросла людина: встань за спиною, охопи руками, кулак між пупком і грудиною, різкі поштовхи всередину і вгору. Немовля: 5 ударів по спині + 5 натискань на грудину. Непритомна людина: горизонтально, натискання на живіт.</div></div><div class=\"final-note\">📌 Курс першої домедичної допомоги: Червоний Хрест України, «Навчи інших» — шукай безкоштовні тренінги у своєму місті. Аптечка: джгут SWAT-T або ізраїльський бандаж — входить у сучасну аптечку. Знай де вона у тебе вдома, на роботі, в авто.</div>"],[346,"Збереження постави за столом","<div class=\"rule-note\">🪑 <b>Постава за столом</b> — тривале сидіння у неправильному положенні веде до болю в шиї, спині і головного болю. Правильне робоче місце + мікроперерви — ефективніша профілактика ніж масаж після.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Правильне положення сидячи</b><br>Ноги: стопи на підлозі, коліна під прямим кутом. Спина: підтримується спинкою крісла в поперековому відділі. Плечі: розслаблені, не підняті. Монітор: верхній край — на рівні очей або трохи нижче, 50–70 см від обличчя. Ліктi: під прямим кутом, зап'ястя — рівно.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Правило 20-20-20</b><br>Кожні 20 хвилин: погляд на об'єкт за 20 футів (~6 м) на 20 секунд — знімає напруження очей. Вставай кожну годину: 2–3 хвилини ходьби або розминки. Таймер або нагадування — поки не стане звичкою.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Укріплення для профілактики</b><br>Вправи для глибоких м'язів спини (plank, bird-dog) — підтримують хребет. Розтягування грудного відділу: «кішка-корова», відведення лопаток. Йога або пілатес: 2–3 рази на тиждень — системне рішення для постави.</div></div><div class=\"final-note\">📌 Вертикальна миша або ергономічна клавіатура: зменшують навантаження на зап'ястя. Якщо вже є хронічний біль — до фізіотерапевта: вправи краще таблеток для більшості проблем з хребтом.</div>"],[347,"Профілактика ГРВІ","<div class=\"rule-note\">🤧 <b>Профілактика ГРВІ</b> — зменшення ймовірності захворіти, а не стовідсоткова гарантія. Більшість популярних засобів (імуностимулятори, вітамін C у мегадозах) не мають доведеної ефективності.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Що справді працює</b><br>Миття рук: 20 секунд із милом — найефективніший метод. Часте торкання обличчя в громадських місцях — основний шлях передачі. Провітрювання приміщень: знижує концентрацію вірусів у повітрі. Вакцинація від грипу: щорічно — зменшує ймовірність і тяжкість.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Загальний стан організму</b><br>Сон 7–9 год: хронічний недосип суттєво знижує імунну відповідь. Регулярна помірна фізична активність: зміцнює імунітет. Збалансоване харчування: різноманітне, з достатньою кількістю вітамінів (особливо D — дефіцит поширений). Стрес: хронічний стрес пригнічує імунітет — не психосоматика, а фізіологія.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>При перших симптомах</b><br>Відпочинок вдома: не переносити «на ногах» — ускладнення і заражаєш інших. Рясне пиття. Парацетамол або ібупрофен: при температурі вище 38.5°C або при сильному дискомфорті. Антибіотики: не призначай сам — не діють на віруси. Показання — рішення лікаря.</div></div><div class=\"final-note\">📌 Вітамін D: 80% українців мають дефіцит (мало сонця). Доза і форма — після аналізу крові або за рекомендацією лікаря. Цинк: є дані про скорочення тривалості застуди при прийомі протягом 24 год після симптомів (лозенги, не таблетки). Осоккорт, арбідол: не мають доведеної ефективності у регуляторних дослідженнях.</div>"],[348,"Принцип здорової тарілки","<div class=\"rule-note\">🥗 <b>Здорова тарілка</b> (модель Гарвардської школи охорони здоров'я) — наочна модель збалансованого харчування без підрахунку калорій. Простіша і практичніша ніж піраміди харчування.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Пропорції здорової тарілки</b><br>½ тарілки — овочі і фрукти (більше овочів ніж фруктів). ¼ тарілки — цільнозернові (овес, бурий рис, цільнозерновий хліб, гречка). ¼ тарілки — білок (риба, птиця, бобові, яйця, горіхи). Плюс: здорові олії (оливкова, ріпакова). Вода, кава або чай без цукру.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Практичне застосування</b><br>Не потрібно виміряти — орієнтовно. Щоразу при приготуванні: «що буде у кожній чверті?» Заморожені овочі: рівноцінні свіжим у більшості випадків — зручно і дешево. Червоне м'ясо (яловичина, свинина): рідше ніж птиця і риба — за рекомендаціями ВООЗ.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Що не на тарілці</b><br>Газовані напої, пакетні соки: не частина здорової тарілки. Оброблені продукти (ковбаси, фастфуд): зрідка, а не щодня. «Дієти» з повним виключенням груп продуктів: більшість не підтримується доказовою базою для здорових людей.</div></div><div class=\"final-note\">📌 Не потрібне ідеальне харчування щодня — важливий загальний патерн за тиждень. Правило 80/20: 80% прийомів їжі відповідно до принципу здорової тарілки — більш ніж достатньо. Деталі: health.harvard.edu/healthy-eating-plate</div>"],[349,"Щорічний чек-ап здоров'я","<div class=\"rule-note\">🏥 <b>Щорічний чек-ап</b> — профілактичне обстеження для раннього виявлення проблем. Більшість серйозних захворювань лікуються значно ефективніше на ранній стадії.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Мінімальний перелік для дорослих</b><br>Загальний аналіз крові і сечі. Глюкоза натще. Ліпідний профіль (холестерин, тригліцериди). АТ (артеріальний тиск) і ЧСС. ЕКГ — після 40 років щорічно. Огляд стоматолога раз на рік. Огляд офтальмолога раз на 2 роки (при роботі за комп'ютером — частіше).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Гендерна специфіка</b><br>Жінки: УЗД молочних залоз/мамографія (після 40 — щорічно), цитологія (PAP-тест) раз на 3 роки, огляд гінеколога. Чоловіки: ПСА (простат-специфічний антиген) після 50 (або після 45 при сімейному анамнезі). Всі після 45: скринінг колоректального раку.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Як організувати в Україні</b><br>Декларація з сімейним лікарем (НСЗУ): базовий огляд + направлення на аналізи — безкоштовно за медичною реформою. Лабораторії: Synevo, CSD, Діла — порівняй ціни на конкретні аналізи. Документуй результати: папка або Гугл Диск з динамікою по роках.</div></div><div class=\"final-note\">📌 Не займайся самодіагностикою за результатами аналізів — контекст і норми залежать від лаборатрії і стану. Результати — до лікаря. Регулярність важливіша ніж ідеальний пакет — хоча б базові аналізи щороку.</div>"],[350,"Збереження зору при роботі з екраном","<div class=\"rule-note\">👁️ <b>Збереження зору</b> при роботі за екраном — правило 20-20-20 і правильне налаштування монітора суттєво знижують цифрову втому очей. Сучасні екрани не «псують» зір у класичному сенсі, але викликають втому.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Правило 20-20-20</b><br>Кожні 20 хвилин: дивись на об'єкт на відстані 20 футів (6 метрів) протягом 20 секунд. Це розслаблює циліарний м'яз ока. Застосунки-нагадування: Time Out (Mac), EyeLeo (Windows) — нагадують автоматично.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Налаштування монітора</b><br>Яскравість: відповідно до освітлення кімнати (не максимум). Розмір шрифту: комфортний для читання без напруження. Night mode / f.lux: зменшує синє світло після заходу сонця. Антивідблискове покриття або фільтр: зменшує пряме відбиття. Відстань 50–70 см від очей.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Зволоження і кліпання</b><br>Під час роботи за екраном: кліпаємо рідше ніж звичайно (у 2–3 рази) — звідси сухість очей. Свідомо кліпай частіше. Зволожувальні краплі (штучна сльоза): при відчутті сухості — безрецептурний засіб. Вологість у кімнаті 40–60% — зменшує висихання очей.</div></div><div class=\"final-note\">📌 Щорічний огляд офтальмолога: при роботі за комп'ютером більше 4 год на день — рекомендовано. Якщо відчуваєш нечіткість, різь або головний біль після роботи з екраном — до лікаря: може потрібна корекція зору.</div>"],[351,"Дихання для зняття стресу","<div class=\"rule-note\">🫁 <b>Дихальні техніки</b> для зниження стресу — найшвидший спосіб вплинути на нервову систему. Повільне глибоке дихання активує парасимпатичну систему і знижує рівень кортизолу.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Техніка 4-7-8 (доктор Вайл)</b><br>Вдих через ніс — 4 рахунки. Затримка дихання — 7 рахунків. Видих через рот зі звуком — 8 рахунків. 4 цикли. Використання: перед сном, в момент тривоги, перед важливою подією. Знижує ЧСС і знімає гостру тривогу.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Коробочне дихання (Box Breathing)</b><br>4 рахунки вдих → 4 затримка → 4 видих → 4 затримка → повтори. Використовується спецназом США для управління стресом в екстремальних ситуаціях. 4–5 хвилин достатньо для відчутного ефекту. Простіше ніж 4-7-8, підходить під час роботи.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Фізіологічне зітхання</b><br>Подвійний вдих через ніс (короткий + короткий) → довгий повільний видих через рот. 1–2 рази. Дослідження Стенфорду 2023: найшвидший метод зниження тривоги в реальному часі. Не вимагає часу і позиції — непомітно в будь-якій ситуації.</div></div><div class=\"final-note\">📌 Дихання — найдоступніший інструмент: завжди з собою, безкоштовне, миттєвий ефект. При хронічному стресі дихальні техніки — доповнення до інших методів (сон, рух, психотерапія), а не заміна. Додаток Breathwrk — тренер дихання з різними програмами.</div>"],[352,"Інтеграція ходьби в побут","<div class=\"rule-note\">🚶 <b>Ходьба</b> — найдоступніша фізична активність. ВООЗ рекомендує 150 хвилин помірної активності на тиждень: 20–25 хвилин пішохідних прогулянок щодня закриває цю норму. Не потрібен спортзал — потрібна система маршрутів.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Як вбудувати в розклад</b><br>Транспорт: виходь на зупинку раніше або йди пішки до наступної. Обід: прогулянка 15 хвилин замість телефону. Телефонні дзвінки: ходи під час розмови. Ліфт vs сходи: 2–4 поверхи — сходи. Парковка далі від входу — ціль не зручність.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Норма кроків і реальність</b><br>10 000 кроків/день — маркетингова цифра, не наукова. Дослідження 2019 (JAMA Internal Medicine): зниження смертності спостерігалось уже від 4000–7500 кроків/день. Більше — краще, але «ефект плато» після 7500. Реальна мета: більше ніж вчора, регулярно.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Трекінг і мотивація</b><br>Смартфон рахує кроки без додатків (Health App на iOS, Google Fit на Android). Пішохідна прогулянка ввечері — один із найкращих способів зниження кортизолу і підготовки до сну. Компанія: людина або собака — підвищує регулярність.</div></div><div class=\"final-note\">📌 Аудіокниги, подкасти під ходьбу — перетворюють «витрату часу» на навчання. Навушники + маршрут + регулярний час = звичка формується швидше.</div>"],[353,"Базовий догляд за шкірою та зубами","<div class=\"rule-note\">🧴 <b>Базовий догляд</b> — мінімальний ефективний рутин для шкіри і зубів. Більшість проблем вирішує регулярність простих дій, а не дорогі засоби.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Догляд за шкірою обличчя: основа</b><br>Три кроки: очищення → зволоження → захист від сонця (вдень). Очищення: двічі на день м'яким засобом (без агресивного мила). Зволоження: зволожуючий крем відповідно до типу шкіри. SPF 30+: щодня, навіть взимку — UV-промені проходять через хмари і скло.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Догляд за зубами</b><br>Чищення двічі на день мінімум 2 хвилини: електрична щітка ефективніша ніж мануальна. Флос або іригатор: щодня — основна причина карієсу між зубами. Зубна паста з фтором (1000–1500 ppm): доведена ефективність профілактики карієсу. Огляд стоматолога раз на рік — дешевше лікування.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Загальні принципи</b><br>Сонцезахисний крем на обличчя: SPF 50 — найефективніша антивікова інвестиція (доведено дерматологічно). Демакіяж перед сном — не пропускай. Очищення волосся: частота залежить від типу — не обов'язково щодня.</div></div><div class=\"final-note\">📌 Не потрібні десятки засобів: очищувач + зволожуючий крем + SPF — достатня основа. Дорогі «антивікові» серуми: більшість не мають доведеної ефективності порівнянної з базовим SPF. Зміни шкіри з кращим харчуванням і сном — ефективніші ніж більшість косметики.</div>"],[354,"Поступове загартовування","<div class=\"rule-note\">❄️ <b>Загартовування</b> — поступова адаптація організму до температурних впливів. Тренує терморегуляцію і підвищує стресостійкість судин. Принцип: поступовість і регулярність — різке охолодження без адаптації шкідливе.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Контрастний душ: початківцям</b><br>Початок: після звичайного теплого душу — 10–15 сек прохолодної води. Щотижня: зменшуй температуру і збільшуй тривалість прохолодного сектора. Мета через 4–6 тижнів: 30–60 сек холодної води. Не треба крижаної: 15–18°C вже значний стресор для судин.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Обливання холодною водою</b><br>Пізніший етап — після 2–3 місяців контрастного душу. Починай з ніг і рук, потім тіло. Вранці — активізує, ввечері — ні. Протипоказання: гострі запалення, серцево-судинні хвороби без дозволу лікаря, інфекція з температурою.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Доведені ефекти і реальність</b><br>Є докази: тренування судин, підвищення настрою (норепінефрин), підвищення концентрації короткочасно. Перебільшені твердження: «зміцнення імунітету» — ефект слабший ніж від сну і харчування. Не панацея, але корисна звичка при правильному підході.</div></div><div class=\"final-note\">📌 Регулярність важливіша ніж інтенсивність: 30 сек щодня > 5 хвилин раз на тиждень. Зупиняйся при болю або різкому дискомфорті — поступовість не обговорюється.</div>"],[355,"Розпізнавання сигналів втоми","<div class=\"rule-note\">😴 <b>Розпізнавання втоми</b> — вміння помітити перші сигнали виснаження до критичного стану. Ігнорування або «перемога над собою» веде до хвороби, травм і вигорання.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Фізичні сигнали</b><br>Ранні: відчуття важкості, сповільнення реакцій, підвищена спрага, порушення координації дрібних рухів. Пізні: біль у м'язах, головний біль від напруження, порушення сну попри втому, часті дрібні травми і помилки. Спортивна втома: зниження результатів, підвищений ЧСС в спокої.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Когнітивні і емоційні сигнали</b><br>«Туман у голові»: труднощі з концентрацією, рішеннями. Підвищена дратівливість або апатія — нетипова для звичайного стану. Втрата інтересу до звичних захоплень. Компульсивна прокрастинація (не лінь — захисна реакція психіки).</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Правило відновлення</b><br>Мікровідпочинок (5–10 хв): прогулянка без телефону, короткий сон (10–20 хв). Правило «стоп»: при перших сигналах — зупинись, не чекай критичного стану. Сон: єдине що усуває когнітивну втому — кава маскує, але не відновлює.</div></div><div class=\"final-note\">📌 Зупинитись і відновитись — не слабкість. Ефективніше: 45 хвилин роботи + 10 хвилин відпочинку, ніж 2 години через силу. Хронічна втома що не минає після сну — сигнал до лікаря (може бути анемія, щитовидна залоза, депресія).</div>"],[356,"Вечірній ритуал розслаблення","<div class=\"rule-note\">🌙 <b>Вечірній ритуал</b> — послідовність дій що сигналізує нервовій системі «день закінчено». Мозок адаптується до патернів: регулярний ритуал прискорює засипання і покращує якість сну.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>За 60–90 хвилин до сну</b><br>Зменш яскравість освітлення: тепле жовте замість яскравого білого. Відклади телефон або увімкни нічний режим (мінімізація синього світла). Завершуй незакриті задачі або записуй у список «завтра» — мозок «переварює» незавершене.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Ефективні практики розслаблення</b><br>Тепла ванна/душ за 1–2 год до сну: зниження температури тіла після — природний сигнал сну. Читання паперової книги (не екрану). Легке розтягування або йога: 5–10 хвилин. Запис у щоденник: 3 хороші речі за день — знижує тривогу перед сном.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Що НЕ робити перед сном</b><br>Новини і соцмережі: збуджують, підвищують тривогу. Важка їжа за 2–3 год до сну. Інтенсивні тренування після 20:00 (для більшості людей). Вирішення конфліктів або складних розмов — відклади на завтра.</div></div><div class=\"final-note\">📌 Мінімальний ритуал: 3 кроки що повторюються щовечора — наприклад, теплий душ → читання 20 хв → вимкнути телефон. Регулярність важливіша за тривалість. Перший тиждень незвично — на другий вже автоматично.</div>"],[357,"Вибір ортопедичного взуття","<div class=\"rule-note\">👟 <b>Ортопедичне взуття</b> — взуття з правильною підтримкою стопи для профілактики і корекції. Не обов'язково спеціальний магазин — звичайне взуття може бути ортопедічно правильним.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Критерії правильного взуття</b><br>Каблук: не вище 3–4 см для щоденного носіння. Носкова зона: широка, не стискає пальці. Супінатор (підтримка зведення): помірна — відчуваєш підтримку але не тиск. Гнучкість: підошва гнеться у передній третині, жорстка в середині. Задник: жорсткий, фіксує п'ятку.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Коли потрібні справді ортопедичні устілки</b><br>Плоскостопість: підтвердження і підбір — подолог або ортопед. Вальгусна деформація, пяткова шпора, діабетична стопа — спеціальне взуття або вкладиші за призначенням. Самостійно купити «ортопедичні устілки» в аптеці без огляду — може погіршити.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Практичні поради при купівлі</b><br>Купуй взуття ввечері: стопа набрякає протягом дня. Мірій обидві ноги — часто різного розміру. Перевір: пальці не торкаються кінця (1–1.5 см зазор). Нові туфлі болять — зазвичай поганий знак: «розносяться» — міф для твердих матеріалів.</div></div><div class=\"final-note\">📌 Кросівки відомих виробників (New Balance, Brooks, ASICS) з системою підтримки зведення — хороше щоденне взуття для активних. Відмова від каблуків: поступова — різке переключення на плоску підошву навантажує ахіллове сухожилля.</div>"],[358,"Зниження споживання цукру та кофеїну","<div class=\"rule-note\">☕ <b>Цукор і кофеїн</b> — два найпоширеніших стимулянти щоденного раціону. Надмірне вживання пов'язане з коливаннями енергії, порушенням сну і в довгостроковій перспективі — метаболічними наслідками.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Цукор: де ховається</b><br>Очевидні джерела: солодощі, газовані напої, соки. Приховані: йогурти (особливо з наповнювачем), соуси (кетчуп, теріякі), хліб, злакові сніданки, «здорові» батончики. Правило ВООЗ: не більше 25–50г вільних цукрів на день. Читай склад: все що закінчується на «-оза» — цукор.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Поступове зниження цукру</b><br>Не різке виключення — поступове зниження. Замін: несолодкий йогурт замість солодкого, вода замість соку, темний шоколад замість молочного. Солодка тяга: зазвичай пик через 2–3 тижні обмеження, потім знижується. Фрукти не вважаються «вільними цукрами» при помірному вживанні.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Кофеїн: скільки і коли</b><br>Норма: до 400 мг/день для здорових дорослих (3–4 кави). Час: кофеїн за 6 год до сну знижує якість сну — навіть якщо засинаєш нормально. Залежність: регулярний прийом дає фізичну залежність. Відміна: головний біль 1–3 дні. Поступове скорочення — комфортніший вихід.</div></div><div class=\"final-note\">📌 Кава з цукром: цукор у каві підвищує калорійність і глікемічний індекс напою суттєво. Альтернативи кофеїну вдень: зелений чай (нижчий кофеїн + L-теанін = спокійна концентрація). Вода: часто втома = дегідратація, а не брак кофеїну.</div>"],[359,"Контроль емоційного переїдання","<div class=\"rule-note\">🍕 <b>Емоційне переїдання</b> — вживання їжі у відповідь на емоції (стрес, нудьга, тривога, смуток), а не на фізичний голод. Поширений патерн — не слабкість характеру, а навчена реакція яку можна змінити.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Розпізнавання патерну</b><br>Питання до себе перед тим як їсти: я фізично голодний чи відчуваю емоцію? Фізичний голод: наростає поступово, будь-яка їжа влаштовує. Емоційний: виникає раптово, тягне до конкретного «заспокійливого» продукту. Ведення щоденника їжі + емоцій — виявляє тригери.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Розрив між імпульсом і дією</b><br>Правило паузи 10 хвилин: хочеться їсти — чекай 10 хвилин, потім вирішуй. За цей час: випий склянку води, виконай 5 глибоких вдихів, зміни локацію. Альтернативні дії: короткий вихід на вулицю, дзвінок другу, 5 хвилин ходьби.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Структура харчування</b><br>Регулярні прийоми їжі: пропуск прийомів підвищує емоційне переїдання через голод. Не тримай вдома продукти які їси тільки у стресі (доступність = спокуса). Дозволь собі: «заборонений плід» посилює потяг, а не зменшує.</div></div><div class=\"final-note\">📌 Якщо емоційне переїдання стале і ти не можеш зупинитись сам — психолог або психотерапевт з досвідом в харчовій поведінці. КПТ (когнітивно-поведінкова терапія) має доведену ефективність при компульсивному переїданні.</div>"],[360,"Відновлення м'язів після навантажень","<div class=\"rule-note\">💪 <b>Відновлення м'язів</b> — частина тренувального процесу, не менш важлива ніж саме тренування. Ріст і адаптація відбуваються під час відпочинку, а не під час навантаження.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Харчування після тренування</b><br>Протягом 30–60 хвилин після: білок + вуглеводи. Білок: 20–40г для синтезу м'язового протеїну (куряче, яйця, сир, протеїновий коктейль). Вуглеводи: поповнення глікогену (банан, рис, вівсянка). Вода: компенсація втрат. Не треба ідеального «вікна» — загальна денна норма білку важливіша.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Активне відновлення</b><br>Розтягування після тренування: 5–10 хв — зменшує м'язову скутість. Foam rolling (міофасціальний релізинг): допомагає при скутості, є деякі докази ефективності. Легка активність у дні відпочинку (прогулянка, плавання): покращує кровообіг і відновлення краще ніж повний спокій.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Сон і відновлення</b><br>Більшість синтезу м'язового протеїну: під час сну. 7–9 год сну — важливіший для відновлення ніж більшість добавок. Крепатура (DOMS): нормальна реакція, зменшується з часом. Тепло (ванна, лазня): може скоротити суб'єктивний дискомфорт від крепатури.</div></div><div class=\"final-note\">📌 Добавки з доведеною ефективністю для відновлення: креатин моногідрат (сила + відновлення), омега-3 (протизапальний ефект), вітамін D (якщо дефіцит). Більшість «відновлюючих» добавок: переоцінені. Базис: білок, вуглеводи, сон — достатньо для 90% людей.</div>"],[361,"Картка медичних даних (Emergency Card)","<div class=\"rule-note\">🆘 <b>Emergency Card</b> — карточка з ключовими медичними даними для екстрених ситуацій. При непритомності або нездатності говорити — рятівники знатимуть критичну інформацію.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Що включати</b><br>ПІБ, дата народження, група крові і резус-фактор. Алергії (особливо на ліки). Хронічні захворювання і постійні ліки (назва + доза). Контакт для екстреного зв'язку (ім'я та телефон). Лікуючий лікар (якщо є).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Де зберігати</b><br>Гаманець: ламінована картка. Телефон: медична картка в iOS (Здоров'я → Медкартка) або Google Emergency Info (Android — налаштування → Emergency info) — доступна з екрану блокування. Бальний браслет або медальйон (для людей з хронічними хворобами).</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Telegram / Дія</b><br>Дія: «Медичні дані» — є функція зберігання ключових медичних даних. Корисно в Україні де Дія широко поширена. Оновлюй після будь-яких змін: нових ліків, нових діагнозів, зміни контакту.</div></div><div class=\"final-note\">📌 Зробити зараз — 10 хвилин. Для членів родини — особливо дітей і людей похилого віку. Алергія на пеніцилін або аспірин на картці — може врятувати від лікарської помилки в реанімації.</div>"]]},{"n":"🧠 БЛОК 4: Емоції, стосунки та ментальне здоров'я","e":"","cards":[[362,"Заземлення при тривозі (Метод 5-4-3-2-1)","<div class=\"rule-note\">🧘 <b>Метод 5-4-3-2-1</b> — техніка заземлення для зниження гострої тривоги через повернення уваги до теперішнього моменту через органи чуттів. Переключає мозок з «режиму загрози» на «режим сприйняття».</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Алгоритм виконання</b><br>Знайди: 5 речей що БАЧИШ (будь-яких предметів поруч). 4 речі що ВІДЧУВАЄШ фізично (одяг на тілі, стілець під тобою). 3 речі що ЧУЄШ (будь-які звуки). 2 речі що ВІДЧУВАЄШ НА ЗАПАХ (або можеш уявити). 1 річ що ВІДЧУВАЄШ НА СМАК.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Коли і як використовувати</b><br>При панічній атаці: зупинись, дихай глибоко і повільно, починай перелік вголос або подумки. При тривожних думках що «зациклились». При флешбеках або дисоціації. Займає 2–5 хвилин — знижує ЧСС і суб'єктивну тривогу.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Доповнення до методу</b><br>Поєднуй з повільним диханням (видих довший за вдих). Тримай в руці щось текстурне: камінь, монету — фізичний якір. Метод не виліковує тривожний розлад — це інструмент управління симптомами в момент.</div></div><div class=\"final-note\">📌 Техніка ґрунтується на теорії поліваґального регулювання Стівена Поргеса і практиках ДБТ (Марша Лайнен). Регулярне застосування: мозок «вчиться» зупиняти сигнал загрози швидше. При хронічній тривозі — до психолога або психіатра.</div>"],[363,"Використання «Я-повідомлень»","<div class=\"rule-note\">💬 <b>Я-повідомлення</b> — спосіб вираження почуттів і потреб без звинувачення. Знижує захисну реакцію співрозмовника і підвищує шанс бути почутим.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Формула Я-повідомлення</b><br>«Коли [конкретна ситуація/дія] → я відчуваю [конкретне почуття] → тому що [твоя потреба/значення для тебе] → і мені потрібно [конкретне прохання/зміна».] Приклад: «Коли ти запізнюєшся без попередження, я відчуваю тривогу, тому що не знаю чи ти у безпеці. Мені важливо отримати повідомлення якщо затримуєшся.»</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Порівняння: Ти vs Я</b><br>Ти-повідомлення: «Ти завжди запізнюєшся!» — звинувачення → захисна реакція. Я-повідомлення: «Коли ти запізнюєшся, я хвилююсь...» — почуття → відкритість. Я-повідомлення не = слабкість. Це точність: описуєш що відбувається з тобою, а не оцінюєш іншого.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Практичні моменти</b><br>Не підмінюй «Ти» на «Я»: «Я відчуваю що ти маніпулюєш» — Ти-повідомлення у масці. Почуття мають бути реальними: «Я відчуваю що неправий» — це думка, не почуття. Реальні почуття: злість, тривога, образа, сумнів, радість. Час вибору: не в момент пику емоцій — коли трохи охолов.</div></div><div class=\"final-note\">📌 Розроблено Томасом Гордоном (Parent Effectiveness Training). Базова комунікаційна навичка в НВЧ (ненасильницьке спілкування, Маршал Розенберг). Практикуй спершу у безпечних ситуаціях — в конфлікті складніше.</div>"],[364,"Встановлення особистих кордонів","<div class=\"rule-note\">🚧 <b>Особисті кордони</b> — правила того як ти дозволяєш ставитись до себе. Не стіна навколо тебе — а чіткий сигнал про твої потреби і межі. Захищають від виснаження і маніпуляцій.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Як визначити свої кордони</b><br>Питання: після яких взаємодій я почуваюсь виснаженим/образженим/незручно? Що мені неприємно але я терплю «щоб не образити»? Де я говорю «так» але хочу сказати «ні»? Відповіді — зони де кордони потрібні.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Як комунікувати кордони</b><br>Чітко і без вибачень: «Я не обговорюю свою вагу/зарплату/стосунки». Без довгих пояснень: «Мені це незручно» — достатня причина. Перший раз: спокійно і прямо. При порушенні: нагадуй + наслідок («якщо це продовжиться, я [конкретна дія]»). Дотримуйся наслідку — інакше кордон ненастоящий.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Складні ситуації</b><br>Близькі і сім'я: найважче. Не треба їх переконувати що твій кордон «правильний» — треба лише дотримуватись. Вина за кордони: нормальна реакція для тих хто виріс у середовищі де кордони не поважались. Поступово стає легше.</div></div><div class=\"final-note\">📌 Кордони — не покарання іншого. Це турбота про себе. Людина яка поважає тебе — прийме кордон. Людина яка не поважає — порушуватиме. Це інформація про стосунки.</div>"],[365,"Етикет вибачення","<div class=\"rule-note\">🤝 <b>Щире вибачення</b> — не формальність, а процес що відновлює довіру. Неправильне вибачення («вибач якщо ти образився») може погіршити ситуацію.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Формула щирого вибачення</b><br>1. Визнай конкретну дію: «Я запізнився на 40 хвилин без попередження» (не «Вибач що так вийшло»). 2. Визнай вплив: «Розумію що ти хвилювався і витратив час на очікування». 3. Прийми відповідальність: «Це була моя помилка». 4. Запропонуй зміну: «Наступного разу попереджу». Порядок важливий.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Чого НЕ робити</b><br>«Вибач але...» — перекреслює вибачення. «Якщо ти образився» — перекладає відповідальність. Пояснення причин ДО визнання вини: виглядає як виправдання. Вимагати вибачення у відповідь — ціна за своє вибачення.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Коли вибачення недостатньо</b><br>При серйозних порушеннях: словами мало. Потрібні дії що демонструють зміну. Час: людині потрібен час прийняти вибачення — не тисни «ти вже вибачив мене?» відразу. Якщо не можеш щиро вибачитись — краще мовчати ніж брехати.</div></div><div class=\"final-note\">📌 Прийняти вибачення і пробачити — різні речі. Пробачення для себе (звільнення від образи) не означає відновлення стосунків і повної довіри. Це окремі рішення.</div>"],[366,"Конструктивне вирішення конфліктів","<div class=\"rule-note\">⚔️ <b>Конструктивний конфлікт</b> — розбіжність де обидві сторони шукають рішення, а не перемогу. Ціль: вирішити проблему, а не довести свою правоту.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Правила конструктивної розмови</b><br>Відокремлюй проблему від особи: «ця ситуація мене злить» а не «ти мене злиш». Слухай щоб зрозуміти, а не щоб відповісти. Питай: «Як ти це бачиш?», «Що для тебе важливо тут?». Не переходь на особистості, минулі образи, ставлення під сумнів.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Схема вирішення</b><br>Охолоньте: не вирішуй конфлікт на піку емоцій. Поясни проблему з позиції потреб (не претензій). Вислухай позицію іншого без перебивань. Знайдіть спільне: що важливо обом? Генеруйте варіанти разом. Погодьтесь на конкретне рішення і перевірку.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Коли конфлікт не вирішується</b><br>Медіатор або терапевт: для важливих стосунків де самостійно не виходить. Деякі конфлікти — несумісність цінностей, а не непорозуміння. Визнання цього теж результат. «Нерозв'язний конфлікт»: можна навчитись поводитись конструктивно навіть без вирішення (ДПП: діалог про розбіжності).</div></div><div class=\"final-note\">📌 Дослідження Gottman Institute: 69% конфліктів у парах — постійні, не вирішувані. Успішні пари не «вирішують» їх — вони управляють ними з повагою і гумором. Навичка: зупинитись і сказати «давай пізніше — зараз занадто гаряче».</div>"],[367,"Вміння казати «НІ»","<div class=\"rule-note\">🚫 <b>Казати «ні»</b> — базова навичка захисту свого часу, енергії і цінностей. Труднощі з відмовою зазвичай пов'язані з бажанням уникнути конфлікту або почуттям провини.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Пряме «ні» без вибачень</b><br>«Ні, я не можу» — достатньо. Не треба довгих пояснень: вони запрошують до переговорів. «Мені шкода, але ні» — ввічливо, але розмиває. «Ні, дякую» — чисто для пропозицій. Правило: пояснення одне, максимум. Більше — посилення тиску стає легшим.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Коли важко сказати «ні»</b><br>Прохання від авторитетних: «Дозволь подумати» — виграй час. Несподівані прохання: «Я маю перевірити свій розклад» — пауза замість автоматичного «так». На посаді: «Яке це має пріоритет відносно X?» — переносить рішення на керівника.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>«Ні» в практиці</b><br>Пропонуй альтернативу лише якщо хочеш: «Не можу сьогодні, але наступного тижня міг би». Не пояснюй однаковий привід двічі: виглядає невпевнено. Почуття провини після «ні»: нормальне якщо не звик. Проходить з практикою.</div></div><div class=\"final-note\">📌 Кожне «ні» чомусь — це «так» чомусь важливішому. Уміння казати «ні» — не егоїзм, а чесність з собою і іншими. Людина яка завжди погоджується стає ненадійним партнером: не знаєш чи вона справді хоче.</div>"],[368,"Емпатійна підтримка близких","<div class=\"rule-note\">💙 <b>Емпатійна підтримка</b> — присутність і розуміння без поради і вирішення. Більшість людей у складних ситуаціях потребують бути почутими — а не щоб їхню проблему вирішили.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Слухати щоб почути</b><br>Мовчазна присутність: «Я тут, слухаю». Перефразування: «Якщо я правильно розумію, ти відчуваєш...» — показує що чуєш. Не перебивай і не перемикай на себе («у мене теж таке було...»). Не квапся зі словами — мовчання після важких слів — теж підтримка.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Чого НЕ говорити</b><br>«Все буде добре» — знецінення. «Ти сильний, впораєшся» — тиск. «Принаймні...»: «Принаймні у тебе є...» — мінімізує біль. «Знаю як ти себе почуваєш» — не знаєш точно. Поради без запрошення: «А ти пробував...?» — переключає з почуттів на дії.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Запитати що потрібно</b><br>Пряме питання: «Тобі зараз потрібно виговоритись, порада чи просто компанія?» — знімає твою невпевненість і дає людині контроль. Це можна і варто питати — не слабкість.</div></div><div class=\"final-note\">📌 Емпатія ≠ злиття: ти можеш бути поруч не беручи на себе чужий біль. «Мені боляче що тобі боляче» — але це твоє відчуття, не те саме що відчуває людина. Якщо важко бути поруч із чужим болем — це теж нормально.</div>"],[369,"Подолання синдрому FOMO","<div class=\"rule-note\">📱 <b>FOMO (Fear Of Missing Out)</b> — страх пропустити щось важливе. Соцмережі підсилюють його, показуючи відібрані найкращі моменти інших людей. Може призводити до тривоги, виснаження від «всюдності» і знецінення власного досвіду.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Переосмислення FOMO</b><br>JOMO (Joy Of Missing Out): усвідомлений вибір того що важливо тобі, а не те що «треба» за соцмережами. Вибір = відмова від іншого. Якщо ти на вечірці — ти «пропускаєш» тихий вечір вдома. Обидва варіанти реальні. Питання: що важливіше для тебе зараз?</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Практичні кроки</b><br>Аудит стрічки: хто у тебе викликає FOMO? Відписуйся або приховуй. Це не означає «погана людина» — просто не твоя аудиторія зараз. Тайм-аут від соцмереж: 1 день на тиждень — помітиш що нічого не пропустив. Запис власних моментів: фокус на тому що маєш, а не чого немає.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Коренева причина</b><br>FOMO часто — не про події, а про страх бути «недостатнім». Питання: «Чого я насправді боюся пропустити?» — відповідь зазвичай глибша. Задоволення від теперішнього моменту — протиотрута від FOMO. Не «ще більше», а «достатньо».</div></div><div class=\"final-note\">📌 Дослідження показують: пасивне гортання стрічки (без публікацій і коментарів) найбільше пов'язане з FOMO і зниженим самопочуттям. Активна взаємодія — менший ефект. Перевір свій власний режим.</div>"],[370,"Вечірня рефлексія (3 питання)","<div class=\"rule-note\">📔 <b>Вечірня рефлексія</b> — коротка щоденна практика осмислення дня. 5–10 хвилин що формують навичку уважного ставлення до власного досвіду і прогресу.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>3 базових питання</b><br>1. Що сьогодні пройшло добре? (Мінімум одна річ — будь-яка.) 2. Що я міг зробити краще і як саме? (Конкретно, без самобичування.) 3. Що я вдячний за цей день? (Не обов'язково велике — може бути смачна кава чи гарна погода.) Запис: у щоденник, нотатки на телефоні або вголос.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Розширені питання (опційно)</b><br>Що я зробив для своїх довгострокових цілей? Як я поводився з людьми — так як хочу поводитись? Що я дізнався сьогодні? Що мене здивувало? Вибирай те що резонує — не обов'язково всі питання щодня.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Як зробити практикою</b><br>Прив'яжи до існуючої звички: після вечері, перед сном. Мінімум: 3 речі вдячності — 2 хвилини. Не пропускай більше 2 днів підряд — при довшій перерві важче відновити. Щотижня: переглянь записи — помічаєш патерни.</div></div><div class=\"final-note\">📌 Дослідження вдячності (Emmons, McCullough): регулярна практика вдячності пов'язана з підвищеним суб'єктивним добробутом. Не магія — просто переключення уваги з дефіциту на наявне.</div>"],[371,"Трансформація заздрості","<div class=\"rule-note\">💚 <b>Заздрість</b> — сигнал про те що для тебе важливо. Не негативна риса характеру — інформація про твої бажання і цінності. Можна використати конструктивно.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Заздрість як індикатор</b><br>Питання: «Кому я заздрю і в чому саме?» — відповідь вказує на те чого ти хочеш. Якщо заздриш чиїйсь подорожі — можливо тобі важливо більше свободи. Якщо заздриш визнанню — можливо тобі важливо, щоб твою роботу помічали. Це чесна і важлива інформація.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Трансформація у дію</b><br>Крок 1: визнай заздрість без осуду («Я зараз заздрю»). Крок 2: визнач що саме — не «все», а конкретно. Крок 3: запитай себе «Що я можу зробити щоб отримати це у своєму житті?» Крок 4: один маленький крок у цьому напрямку.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Порівняння з іншими</b><br>Соцмережі: порівняння з відібраними моментами чужого життя. Нечесне порівняння. Корисне порівняння: «з собою вчорашнім» — єдине що дає реальне відчуття прогресу. «Краще ніж вчора» — стійкіша мотивація ніж «краще ніж він».</div></div><div class=\"final-note\">📌 Злобна заздрість (хочу щоб у нього не було) і доброзичлива заздрість (хочу щоб у мене теж було) — різні. Перша — сигнал про власний дефіцит самооцінки, варто опрацювати з психологом.</div>"],[372,"Захист від токсичного спілкування","<div class=\"rule-note\">⚠️ <b>Токсичне спілкування</b> — взаємодія що регулярно виснажує, принижує або маніпулює. Не кожен складний діалог токсичний — токсичність у патерні, а не в окремому епізоді.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Ознаки токсичної взаємодії</b><br>Після спілкування: регулярно почуваєшся гіршим, менш здатним, виснаженим. Газлайтинг: тебе змушують сумніватись у власному сприйнятті реальності. Постійна критика без конструктиву. Маніпуляції: провина, жалість, погрози. Порушення кордонів після чіткого «ні».</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Захисні стратегії</b><br>Мінімізація контакту: якщо неможливо уникнути (сім'я, робота). Техніка «сірої скелі»: мінімальні, нейтральні відповіді — не даєш матеріалу для маніпуляцій. Не виправдовуйся і не пояснюй рішення тому хто не поважає твоїх кордонів. Є люди кому ти не зобов'язаний пояснювати.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Коли виходити</b><br>Стосунки де токсичність є системою, а не випадком — можуть бути несумісні з твоїм добробутом. Дозвіл: ти маєш право дистанціюватись або завершити стосунки що завдають шкоди. Терапія: допомагає вийти і відновитись після токсичних стосунків.</div></div><div class=\"final-note\">📌 Не всі складні люди токсичні. Складність може бути про власний біль людини. Межа: коли їхній біль стає твоєю регулярною шкодою — це токсичність незалежно від причини.</div>"],[373,"Підтримка дружби на відстані","<div class=\"rule-note\">🌍 <b>Дружба на відстані</b> — потребує свідомих зусиль, але може бути глибокою і тривалою. Ключ: регулярний контакт без очікування ідеального моменту.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Регулярний контакт без приводу</b><br>Не чекай «нічого нового» — відправляй мем, статтю, «згадав про тебе»: мікроконтакти підтримують зв'язок. Регулярний дзвінок або відеоколл: раз на 2–4 тижні — краще ніж «поспілкуємось як вийде». Встав у календар: звучить непоетично, але працює.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Якісні форми контакту</b><br>Голосові повідомлення: тепліші ніж текст, зручніші ніж дзвінок. Спільний перегляд або гра онлайн (Watch Party, ігри у браузері). Листи: несподівано і цінно. Спільне планування реальної зустрічі — зберігає «горизонт» дружби.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Коли дружба слабшає</b><br>Нормально: контакт змінюється на різних етапах життя. Не всі дружби підтримуються однаковим зусиллям. Перевірка: хто ініціює? Якщо завжди ти — варто поговорити або прийняти асиметрію. Деяким дружбам потрібна пауза — не обов'язково кінець.</div></div><div class=\"final-note\">📌 «Правило 5 хвилин»: написати або зателефонувати людині яку давно не чув — займає 5 хвилин і часто робить день кращим для обох. Відкладати «поки не буде часу» = відкладати назавжди.</div>"],[374,"Практика вдячності","<div class=\"rule-note\">🙏 <b>Практика вдячності</b> — свідоме фокусування на позитивних аспектах свого досвіду. Переключає увагу з дефіциту на наявне. Ефект доведений у дослідженнях: регулярна практика пов'язана з кращим суб'єктивним добробутом.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Формати практики</b><br>Щоденник вдячності: 3 речі щодня — конкретні, не шаблонні. «Дякую сім'ї» — шаблон. «Дякую що донька засміялась над моїм жартом увечері» — конкретно і живо. Вечірній ритуал: подумки або вголос — 2 хвилини. Лист вдячності: написати реальній людині — потужна форма.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Поглиблення практики</b><br>Вдячність за труднощі: «Що мене навчила ця складна ситуація?» — зміна кадру. Вдячність тілу: за те що воно дозволяє робити, а не за зовнішній вигляд. Мінуваль-медитація: 5 хвилин — уявляй що позбавлений чогось що маєш, потім повертай це.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Пастки практики</b><br>Токсичний позитивізм: «Завжди є за що бути вдячним» — знецінює реальний біль. Вдячність не заперечує труднощі — вона паралельна. Механічне виконання без уваги: швидко втрачає ефект. Якщо важко знайти — шукай мале: кружка кави, ранкове сонце.</div></div><div class=\"final-note\">📌 Дослідження Emmons і McCullough (2003): учасники що вели щоденник вдячності тижнево відчували себе краще, частіше займались спортом і рідше скаржились на фізичні симптоми ніж контрольна група.</div>"],[375,"Прийняття самотності","<div class=\"rule-note\">🌿 <b>Самотність</b> — два різних стани: самота (вимушена ізоляція, боляча) і усамітнення (обраний час наодинці з собою, відновлювальний). Навичка: перетворити самоту на усамітнення і цінувати час з собою.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Різниця між самотою і усамітненням</b><br>Самота: почуття ізольованості попри бажання зв'язку. Усамітнення: добровільний відпочинок від соціальних взаємодій. Та сама ситуація «один вдома» — може бути або болісна, або відновлювальна залежно від сприйняття і вибору.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Навичка бути з собою</b><br>Почни з малого: 30 хвилин без телефону і контенту — просто бути. Дискомфорт перші хвилини — нормальний. Розвивай внутрішній діалог: щоденник, малювання, прогулянка без навушників. Поступово час з собою стає ресурсом, а не покаранням.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Коли самота болюча</b><br>Хронічна самота: пов'язана з погіршенням здоров'я — варто активно будувати зв'язки. Перший крок: один регулярний соціальний контакт — клуб за інтересами, волонтерство, спортивна секція. Психолог: при депресії і глибокій ізоляції — не «саме пройде».</div></div><div class=\"final-note\">📌 Юнг: «Самотність це не відсутність інших людей — це відсутність себе». Час з собою — умова для знання себе. Інтроверти відновлюються в усамітненні, екстраверти — в спілкуванні. Обом потрібно і те і те.</div>"],[376,"Сприйняття зворотного зв'язку","<div class=\"rule-note\">📣 <b>Зворотний зв'язок</b> — інформація про твої дії з точки зору іншого. Вміння приймати його без захисної реакції і без знецінення — ключ до зростання.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Три типи відповіді на фідбек</b><br>Захисна реакція: заперечення, виправдання, контратака — природна, але блокує отримання інформації. Перекосне прийняття: «ти правий, я жахливий» — самокритика без аналізу. Конструктивне: «Дякую. Дозволь уточнити що ти мав на увазі» — пауза і питання.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Алгоритм прийняття фідбеку</b><br>1. Вислухай до кінця, не перебивай. 2. Уточни: «Правильно я розумію що...?» 3. Дякуй за зусилля поділитись. 4. Подумай окремо: що корисне в цьому фідбеку? 5. Вирішуй що робити з цим — твій вибір. Час: не відповідай «зараз в захисті» — повернись пізніше.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Нецінний фідбек</b><br>Не весь фідбек однаково корисний. Критерії корисного: конкретний, про поведінку (не особистість), від людини чия думка компетентна. «Мені не подобається твій стиль» без уточнення: не корисний. «У другому розділі аргумент непереконливий, бо...»: цінний.</div></div><div class=\"final-note\">📌 Правило: будь-який фідбек містить бодай щось корисне і бодай щось спірне. Задача: знайти корисне і не відкидати разом із поверхнею.</div>"],[377,"Подолання перфекціонізму","<div class=\"rule-note\">✅ <b>Перфекціонізм</b> — не прагнення до якості, а страх недосконалості. Відкладання через «ще не готово», надмірна самокритика, нездатність завершити — симптоми. Антидот: «достатньо добре» і практика «неповного».</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Розпізнати перфекціонізм у собі</b><br>Відкладаєш початок через «недостатньо підготовленість». Критикуєш себе різкіше ніж критикував би іншого за те саме. Результати або «ідеальні» або «повне провалля» — без середини. Не можеш завершити: постійно доопрацьовуєш.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Практичні протиотрути</b><br>Правило «80%»: хороша робота зроблена — краще ніж ідеальна що не відправлена. Done is better than perfect. Навмисна «незавершеність»: залиш незначну помилку — переконайся що нічого не обвалилось. Таймер: «Маю 30 хвилин — зроблю що зможу».</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Самоспівчуття замість самокритики</b><br>Запитай: «Як би я поставився до друга в такій ситуації?» — відповідь зазвичай м'якша ніж до себе. Помилки = навчання: конкретно — «що я дізнався», а не «який я невдаха». Брене Браун: «Вразливість — не слабкість, а сміливість».</div></div><div class=\"final-note\">📌 Перфекціонізм пов'язаний з тривогою і депресією більше ніж з реальними досягненнями. Дослідники перфекціонізму (Paul Hewitt, Gordon Flett) розрізняють «адаптивний» (прагнення до якості) і «неадаптивний» (страх невдачі). Другий блокує, перший допомагає.</div>"],[378,"Розпізнавання маніпуляцій","<div class=\"rule-note\">🎭 <b>Маніпуляція</b> — прихований вплив на поведінку або почуття для досягнення власних цілей за твій рахунок. Відрізняється від переконання: переконання відкрите, маніпуляція прихована.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Поширені техніки маніпуляції</b><br>Газлайтинг: «Тобі здалось», «ти занадто чутливий» — ставить під сумнів твоє сприйняття. Провина: «Якби ти мене любив би...», «Я так для тебе стараюсь, а ти...». Любов-бомбардування: надмірна увага і лестощі на початку — потім вимоги. Мовчазне покарання: ігнорування як інструмент тиску.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Ознаки що тебе маніпулюють</b><br>Після взаємодії: відчуваєш провину або сором без чіткої причини. Твоя «ні» перетворюється на «так» тиском. Почуваєшся відповідальним за почуття або рішення іншого. Факти «перекручуються» у розмові.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Захист</b><br>Пауза: «Дай мені подумати» — виграй час поза тиском. Уточнення: «Як саме?», «Що конкретно ти маєш на увазі?» — маніпулятор не любить конкретики. Відмова від провини: «Мені шкода що ти так почуваєшся, але своє рішення я не змінюю». Якщо не можеш захиститись сам — до психолога.</div></div><div class=\"final-note\">📌 Всі маніпулюють іноді — різниця в усвідомленості і систематичності. Хронічна маніпуляція в стосунках — ознака серйозної проблеми. Книга: «Не кажи так якщо хочеш сказати ні» (Manuel J. Smith) — про асертивну поведінку.</div>"],[379,"Створення сімейних ритуалів","<div class=\"rule-note\">👨‍👩‍👧 <b>Сімейні ритуали</b> — повторювані спільні дії що створюють відчуття стабільності, причетності і ідентичності. Дослідження підтверджують: сім'ї з чіткими ритуалами мають кращу згуртованість і менше конфліктів.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Типи ритуалів</b><br>Щоденні: спільний обід/вечеря, вечірні обійми, «як пройшов день». Щотижневі: кінонеділя, субота у природі, сімейна гра. Річні: святкування дня народження, підготовка до свят, сімейна відпустка. Перехідні: підготовка до школи, проводи і зустрічі, подяки.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Як створити новий ритуал</b><br>Визнач момент що повторюється: вечеря, вихідний, початок тижня. Додай простий регулярний елемент: питання «що було найкращим сьогодні», спільне приготування частини вечері. Регулярність важливіша за складність. Дозволь ритуалу розвиватись — не форсуй ідеальну форму.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Ритуали з дітьми</b><br>Дітям особливо важливі: передбачуваність знижує тривогу, ритуали — маркери безпеки. Вечірній ритуал укладання: книга + обійми + «три хороших речі» — 10 хвилин що мають великий ефект. Ритуали переходів: перший день школи, день народження — фіксують важливі моменти.</div></div><div class=\"final-note\">📌 Дослідження Marshall Duke (Emory University): діти які знають більше про сімейну історію («навхідний наратив») мають кращу стресостійкість. Ритуали — контейнер для передачі цієї історії.</div>"],[380,"Вихід із стану емоційного застою","<div class=\"rule-note\">💫 <b>Емоційний застій</b> — стан коли немає ні сил ні мотивації щось змінювати. Відрізняється від лені: лінь — вибір, застій — стан. Вихід: не через силу волі, а через мікрокроки і зміну середовища.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Мікрокроки замість «зберись»</b><br>Не «зміни своє життя» — а «відкрий вікно». «Вийди на вулицю на 5 хвилин». «Прийми душ». Дія будь-якого масштабу розриває інерцію — маленький крок реальніший ніж великий. Питання: «Яка найменша дія що я можу зробити прямо зараз?»</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Зміна середовища</b><br>Фізична зміна простору: переставити меблі, прибрати стіл, вийти з дому — мозок реагує на нові стимули. Нові люди або старі знайомі: зв'яжись з кимось кого давно не бачив. Нова активність: щось маленьке і нове — урок, похід, книга.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Коли потрібна допомога</b><br>Емоційний застій &gt; 2 тижнів + порушення сну + апатія до всього раніше приємного — може бути депресія. Не «поганий настрій» — стан що вимагає підтримки. Психолог або психіатр: не слабкість, а правильна відповідь на медичний стан.</div></div><div class=\"final-note\">📌 Правило «поганого дня»: один поганий день — норма. Три поспіль — може бути ситуація. Два тижні — зверни увагу. Не ігноруй власний стан з позиції «інші мають гірше».</div>"],[381,"Активне слухання","<div class=\"rule-note\">👂 <b>Активне слухання</b> — повна присутність у розмові: не чекаєш своєї черги говорити — справді чуєш. Найважливіша комунікаційна навичка що більшість людей не практикують свідомо.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Техніки активного слухання</b><br>Контакт очима: не постійний — але регулярний, показує увагу. Поза: злегка нахилений вперед, не схрещені руки. Мінімальні підтвердження: «Мм», «Розумію», кивок — сигналізуєш що чуєш. Не перебивай: навіть якщо хочеш доповнити.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Перефразування і уточнення</b><br>Перефразування: «Якщо я правильно розумію, ти маєш на увазі...» — показує що чув і дає можливість виправити. Уточнення: «Розкажи більше про...», «Що ти мав на увазі під...» — поглиблює розуміння. Питань більше ніж суджень — ознака хорошого слухача.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Що заважає слухати</b><br>Внутрішній монолог: планування відповіді поки інший говорить. Оцінка і суджання під час мовлення. Відволікання: телефон, середовище. Практика: один день — спробуй не перебивати жодну розмову і помітити скільки разів хотів.</div></div><div class=\"final-note\">📌 Дослідження показують: більшість людей запам'ятовують лише 25–50% почутого. Активне слухання подвоює цей показник і суттєво підвищує якість стосунків і вирішення проблем. Це навичка що тренується, не риса характеру.</div>"]]},{"n":"🚀 БЛОК 5: Життєвий тайм-менеджмент та саморозвиток у буденності","e":"","cards":[[382,"Суміщення рутини з навчанням","<div class=\"rule-note\">📚 <b>Навчання в рутині</b> — використання часу що «йде на автопілоті» для розвитку. Дорога, прибирання, тренування, приготування їжі — 1–2 год щодня де можна навчатись.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Аудіоформати під рутинні дії</b><br>Подкасти: широкий спектр від науки до бізнесу до мов. Аудіокниги: Audible, Storytel, Bookmate — одна книга за 2–4 тижні пасивного часу. YouTube в фоновому режимі (лекції, курси). Мови: Duolingo під час сніданку або в транспорті — 10–15 хвилин щодня дають результат за рік.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Мікронавчання (мікролернінг)</b><br>5–10 хвилин цілеспрямованого навчання: одна концепція, одне відео, один урок. Anki (спейсд репетишн): повторення флешкарток у транспорті — ефективне запам'ятовування. Перед сном: прочитати 10 сторінок — за рік це 3650 сторінок або ~10 книг.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Критичний підхід до «навчання»</b><br>Пасивне споживання контенту ≠ навчання. Навчання потребує: осмислення, практики, тестування пам'яті. Баланс: аудіо для знайомства з ідеями, активна практика для реальних навичок. Не замінюй глибоке навчання постійним аудіопотоком.</div></div><div class=\"final-note\">📌 Правило: після прослуханого — одна думка або питання. Запис у нотатки поки свіже. Це переводить пасивне слухання в активне.</div>"],[383,"Нашарування звичок (Habit Stacking)","<div class=\"rule-note\">🔗 <b>Habit Stacking</b> (нашарування звичок) — прив'язка нової звички до існуючої. Формула: «Після того як [існуюча звичка], я буду [нова звичка]». Використовує вже сформовані нейронні ланцюги.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Формула і приклади</b><br>«Після того як я наллю ранкову каву → зроблю 1 хвилину розтягування». «Після того як сяду в транспорт → відкрию Duolingo». «Після того як почищу зуби → запишу 3 речі вдячності». Якір: існуюча звичка що відбувається автоматично. Нова: мінімальна і конкретна.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Правила ефективного стекінгу</b><br>Нова звичка: мінімальна версія (2 хвилини максимум спочатку). Якір і нова звичка: мають бути логічно пов'язані або просторово близькі. Одна нова звичка на один якір: не перевантажуй. Якір має бути щоденним і стабільним.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Розширення стека</b><br>Як звичка стала автоматичною (4–6 тижнів) — можна розширити: «Після кави → 2 хвилини розтягування → 5 хвилин читання». Увага: занадто довгий стек при зриві одного елемента ламає весь. Гнучкість: мінімальна версія завжди краще ніж пропустити.</div></div><div class=\"final-note\">📌 Концепція Джеймса Кліра («Атомні звички»): ідентичність + маленькі зміни = великі результати. Нова звичка закріплюється не через мотивацію, а через повторення і контекст. Якір — цей контекст.</div>"],[384,"Цифровий вихідний (Digital Detox)","<div class=\"rule-note\">📵 <b>Цифровий детокс</b> — свідомий час без цифрових пристроїв. Не відмова від технологій назавжди — відновлення здатності присутності і уваги, яку алгоритми систематично підривають.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Мінімальний детокс: 1 день на тиждень</b><br>Вихідний без соцмереж (не без телефону взагалі). Увімкни режим «Не турбувати» або «Фокус» на весь день. Повідом близьких заздалегідь. Перший раз: незвично і навіть тривожно в перші години — це нормально і є доказом залежності.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Що робити замість</b><br>Не потрібен план «правильного» детоксу. Просто нудьгуй — мозок починає генерувати власні ідеї. Йди назустріч нудьзі замість підтримки від телефону. Це не порожній час — це час для власних думок. Фізична активність, природа, живе спілкування — сприймаються глибше.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Мікродетокс щодня</b><br>Телефон не в спальні: купи будильник. Перші 30 хвилин після підйому — без телефону. «Телефон лицем вниз» під час розмов і їжі. Нотифікації: вимкни всі крім важливих дзвінків — ти сам вирішуєш коли перевіряти.</div></div><div class=\"final-note\">📌 Стратегія «тертя»: видалення соцмереж зі смартфона (можна заходити з ноутбука) — суттєво знижує імпульсивний вхід без повного відключення. Незручність = менше автоматичного заходу.</div>"],[385,"Постановка особистих цілей (SMART)","<div class=\"rule-note\">🎯 <b>SMART-цілі</b> — Specific (конкретна), Measurable (вимірювана), Achievable (досяжна), Relevant (актуальна), Time-bound (обмежена часом). Перетворює розмиті бажання на конкретні плани.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>SMART на практиці</b><br>Не-ціль: «Хочу бути здоровішим». SMART-ціль: «Пробіжки тричі на тиждень по 20 хвилин протягом 8 тижнів». Не-ціль: «Навчитись іспанської». SMART: «Завершити рівень A1 на Duolingo до кінця листопада (30 уроків = 1 урок щодня)». Критерій: чи можу я однозначно сказати «досяг» або «не досяг»?</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Ієрархія цілей</b><br>Велика мета (1–3 роки) → середні цілі (квартал) → щотижневі дії. Щотижневі дії мають бути під твоїм прямим контролем (не залежати від інших і від удачі). Результат: бачиш прогрес щотижня, а не чекаєш «велику перемогу».</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Огляд і корекція</b><br>Щотижневий огляд: що зробив з запланованого? Що заважає? Щоквартальний: чи актуальна ціль? Дозволь собі змінювати: не «провал» — а нова інформація. Ціль що більше не актуальна — не треба доводити з принципу.</div></div><div class=\"final-note\">📌 Дослідження Гейл Метьюз (Dominican University): письмово сформульовані цілі досягаються частіше. Поділись ціллю з кимось хто підтримає і запитає — підвищує відповідальність. SMART — не єдина система: OKR, Wildly Important Goals — варіанти для команд і бізнесу.</div>"],[386,"Виділення часу на хобі","<div class=\"rule-note\">🎨 <b>Час на хобі</b> — не розкіш, а необхідна частина психологічного добробуту. Діяльність задля задоволення без зовнішньої оцінки відновлює і розвиває те що робота і побут не дають.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Захисний блок у розкладі</b><br>Плануй час на хобі як зустріч: конкретний час у календарі, а не «якщо залишиться». «Залишиться» майже ніколи. Мінімум: 1–2 год на тиждень — реалістичний старт. Захисти від вторгнення: «Я зайнятий» — достатня відповідь.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Коли «немає часу»</b><br>Перевір: скільки часу витрачаєш на пасивне гортання? Перестав просто «відпочивати» в соцмережах і замін на хобі — не витратиш більше часу. Мікрохобі: 20–30 хвилин — достатньо для кількох технік малювання, кількох рядків музики, кількох рядків тексту.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Як хобі впливає на загальний добробут</b><br>Flow стан (Міхай Чіксентмігаї): повне занурення без часового відліку — один з найсильніших джерел задоволення. Хобі з навичками що розвиваються: живуть довше і глибші, ніж пасивне споживання. Соціальне хобі (клуб, група, команда): додає зв'язки.</div></div><div class=\"final-note\">📌 Не кожне хобі має стати бізнесом або бути «продуктивним». Хобі задля задоволення — повноцінна і достатня причина. Монетизація хобі може вбити задоволення від нього — обміркуй перед тим як перетворити пристрасть на роботу.</div>"],[387,"Магія першої години (Morning Routine)","<div class=\"rule-note\">🌅 <b>Ранкова рутина</b> — перша година дня задає тон усьому іншому. Не магія — а використання найвищої когнітивної енергії до того як зовнішній світ почав вимагати твою увагу.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Базові елементи ранкової рутини</b><br>Уникай телефону першу годину: новини і повідомлення переключають мозок в реактивний режим. Вода: 1–2 склянки одразу після підйому. Рух: 5–15 хвилин — розтягування, прогулянка, йога — розбуджує тіло. Час без зовнішніх вимог: твій пріоритет, а не чужий.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Ключовий елемент: одна важлива задача</b><br>Перша година — для найскладнішої або найважливішої задачі дня (якщо ти «ранкова людина»). «Eating the frog» (Браян Трейсі): найважче вранці — день вільний від відкладеного. Альтернатива: час для власних проєктів або навчання — до того як робота заповнить все.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Реалістична рутина</b><br>Не копіюй рутину CEO з 5:00 підйому якщо ти не жайворонок. Адаптуй під хронотип. Мінімальна версія: будильник без «відкласти» + вода + 5 хв без телефону — достатньо. Ускладнюй поступово.</div></div><div class=\"final-note\">📌 Дослідження: рішення з ранку краще ніж з вечора (свіжа когнітивна ємність). Але «золота ранкова година» — не для всіх хронотипів. Сов не треба мучити: їх пік — після полудня, і це норма.</div>"],[388,"Ведення Bullet Journal","<div class=\"rule-note\">📓 <b>Bullet Journal</b> (BuJo) — система організації що поєднує щоденник, планер і нотатки в одному зошиті. Розроблена Райдером Керроллом. Мінімальна версія — ефективна за 15 хвилин денного ведення.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Базові елементи системи</b><br>Ключ (Key): позначки для записів — крапка (задача), коло (подія), тире (нотатка). Виконано: Х, відкладено: &gt;, видалено: закреслення. Щоденний журнал (Daily Log): швидкі записи у плині дня. Майбутній журнал (Future Log): заплановане на місяці вперед.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Щоденне і щомісячне ведення</b><br>Вечірній огляд (5 хв): перенеси незавершені задачі, видали неактуальні. Щомісячний огляд: скопіюй важливе на новий місяць, переглянь цілі. Міграція: якщо задача постійно переноситься — або зроби або видали. Звичка міграції виключає «зависання».</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Мінімальна версія</b><br>Не потрібен ідеальний дизайн і декорації (Instagram BuJo — додатковий витрат часу). Звичайний блокнот + ручка. Три сторінки: Index + Future Log + перший Daily Log. Решта додається за потребою. Мета: система що використовуєш, а не красива.</div></div><div class=\"final-note\">📌 Офіційний сайт: bulletjournal.com. Ключова ідея: «навмисне зниження»: кожен день вирішуєш що важливе сьогодні, а не тягнеш все з попереднього дня. Аналоговий формат — частина ефекту: немає нотифікацій і відволікань.</div>"],[389,"Корисний час у транспорті","<div class=\"rule-note\">🚌 <b>Час у транспорті</b> — 20–60 хвилин щодня що більшість витрачає на пасивне гортання. Перетворення цього часу на навчання або відновлення — один із найефективніших «безкоштовних» апгрейдів дня.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Навчання і розвиток</b><br>Аудіокниги: 1 книга за 2–4 тижні пасивного часу. Подкасти: теми від мов до науки до бізнесу. Мови: Duolingo або Pimsleur — щоденні 15 хвилин дають відчутний прогрес за 3 місяці. Лекції (YouTube, Coursera офлайн-завантаження): якщо сидиш і є екран.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Відновлення і усвідомленість</b><br>Медитація з гідом (Headspace, Insight Timer, Fabrika): 10 хвилин — знижує денний стрес. Спостереження за навколишнім: без навушників, просто дивись і помічаєш — рідкісний режим в сучасному житті. Коротка дрімота (10–20 хв): продуктивно при втомі.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Планування і огляд</b><br>Перегляд задач дня: ранкова поїздка — хороший час. Щотижневий огляд: список незавершеного. Запис ідей: голосові нотатки якщо не можеш писати. Відповіді на нескладні листи або повідомлення: не чекай офісу.</div></div><div class=\"final-note\">📌 Не заповнюй весь час транспорту контентом. Нудьга і «порожнє» мислення важливі для мозку: спонтанні ідеї і осмислення виникають саме в ці моменти. Баланс: 50/50 — контент і «порожній» час.</div>"],[390,"Практика Slow Living","<div class=\"rule-note\">🌸 <b>Slow Living</b> — свідоме уповільнення темпу на противагу культурі «завжди зайнятий». Не лінощі і не відмова від амбіцій — інтенційне присутнє проживання замість постійного «авторежиму».</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Принципи Slow Living</b><br>Якість над кількістю: менше справ, але повноцінніше. Присутність: одна справа за раз, без паралельного потоку стимулів. Навмисний вибір: «Чому я це роблю?» перед додаванням нового у своє життя. Регулярний мінімалізм у розкладі: не заповнювати кожну щілину.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Практичні прояви</b><br>Їжа без телефону: повноцінний прийом їжі — не «поки дивлюсь». Прогулянка без навушників: помічаєш середовище. Ранкова кава як ритуал: 10 хвилин без поспіху. Розмова без телефону на столі: повна присутність. Це не «продуктивність» — це якість проживання.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Як почати без радикальних змін</b><br>Один повільний ранок на тиждень. Одна «бездіяльність» на день: 10 хвилин без цілі і телефону. Вечеря без екрану: хоча б 2–3 рази на тиждень. Поступово — не переворот, а зсув фокусу.</div></div><div class=\"final-note\">📌 Slow Living не означає не мати цілей. Це означає не бути зайнятим заради зайнятості. Питання: «Яку частину свого дня я дійсно прожив — а яку перебіг на автопілоті?» — відповідь вказує де є простір.</div>"],[391,"Формування домашньої бібліотеки","<div class=\"rule-note\">📖 <b>Домашня бібліотека</b> — не збірка книг для демонстрації, а живий інструмент для розмислення, пошуку і повернення до важливого. Якість важливіша за кількість.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Принцип добору книг</b><br>Не все що читав — треба тримати. Лишай: книги до яких повертаєшся, що вплинули на мислення, референси і довідники. Відпускай: прочитані «на один раз», не актуальні, дублікати (залиш найкращий примірник). OLX, книгообмін: є куди передати.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Організація</b><br>За тематикою чи жанром — залежно від того як думаєш. Прочитане vs непрочитане (стек Nassim Taleb «антибібліотека» — непрочитане корисне: нагадує про незнане). Позначки в книгах: підкреслення і нотатки на полях — підвищують засвоєння і корисність при поверненні.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Цифрова бібліотека</b><br>Kindle, Pocketbook: компактна, зручна, дешевші книги. Недолік: менше запам'ятовуєш ніж з паперовою (дослідження підтверджують). Комбінація: художня і розважальна — електронна. Справочна, нон-фікшн, до якої повертаєшся — паперова.</div></div><div class=\"final-note\">📌 Правило: книгу що непрочитана більше 2 років — або прочитай цього місяця або продай/подаруй. Непрочитані книги можуть викликати «вину» — не мету бібліотеки. Вона для натхнення і використання, не для показу.</div>"],[392,"Щотижневий огляд (Weekly Review)","<div class=\"rule-note\">📋 <b>Weekly Review</b> — регулярна практика (David Allen, GTD) огляду минулого тижня і підготовки до наступного. 30–60 хвилин що дають відчуття контролю і знижують когнітивний навантаження.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Огляд минулого тижня</b><br>Що зробив з запланованого? Що не зробив і чому? Що несподіваного відбулось? Яке почуття від тижня в цілому? Зафіксуй прогрес: навіть маленькі перемоги — важливо бачити рух.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Підготовка до наступного тижня</b><br>Переглянь всі відкриті задачі: видали неактуальні, заплануй важливі. Визнач 3 пріоритети на тиждень. Переглянь календар: підготуйся до важливих зустрічей заздалегідь. Перевір прогрес довгострокових цілей.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Як зробити регулярним</b><br>Фіксований час: п'ятниця вечір або неділя вранці — стабільніше ніж «в зручний час». 30 хвилин — достатньо для мінімального огляду. Простий шаблон у нотатках або Notion — не треба складних систем.</div></div><div class=\"final-note\">📌 GTD (Getting Things Done) Девіда Алена: Weekly Review — ключовий елемент системи. Без регулярного огляду система розпадається. Щотижневий огляд не замінює щоденне планування — доповнює більш стратегічним поглядом.</div>"],[393,"Аудит власних бажань","<div class=\"rule-note\">🔎 <b>Аудит бажань</b> — відрізнення власних цілей і прагнень від нав'язаних (суспільством, сім'єю, соцмережами). Почуття «повинен» і «хочу» — різні. Плутанина між ними веде до вигорання і розчарування.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Питання для аудиту</b><br>«Я хочу X чи хочу щоб мене сприймали як людину що має X?» «Хочу цього для себе чи щоб виправдати чиїсь очікування?» «Якби ніхто не дізнався — я все одно прагнув би до цього?» «Якщо б цей шлях не мав статусу і грошей — я все одно вибрав би його?»</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Розпізнавання нав'язаних бажань</b><br>«Повинен» замість «хочу»: «Мені треба займатись бігом» — чому? Порівняння як мотив: хочу те що є у когось — бо хочу або бо «заздрю»? Соціальні мережі: бажання після гортання стрічки часто — порівняльна реакція, не справжнє прагнення.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Визначення справжніх пріоритетів</b><br>Питання: «Якщо мені залишилось 1 рік — що б я робив? 10 років?» Різниця у відповідях — інформативна. Смертне питання: «Коли оглядатимусь назад, чого мені не вистачатиме?» Не «що зробив» — а «ким я був».</div></div><div class=\"final-note\">📌 Аудит бажань — не одноразова процедура. Раз на рік: переглянути цілі і перевірити чи вони досі твої. Людина змінюється — цілі мають змінюватись разом з нею. Не відмова від амбіцій — а їх аутентичність.</div>"],[394,"Мікро-виходи з зони комфорту","<div class=\"rule-note\">🌱 <b>Вихід із зони комфорту</b> — не стрибок у прірву. Маленькі регулярні кроки в незвичне розширюють зону поступово і без паніки. Прогрес є і без драматичного «переломного моменту».</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Що таке мікровихід</b><br>Щось незначне але незвичне: заговорити з незнайомим, спробувати нову страву, піти новим маршрутом. Незручність: є, але мінімальна — не паніка. Регулярність: раз на день або кілька разів на тиждень. Ціль: «трохи незручно» а не «жахливо страшно».</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Приклади мікровиходів</b><br>Соціальні: привітатися першим, зробити комплімент незнайомому, виступити на зборах. Нові досвіди: новий жанр кіно, кафе де ніколи не бував, новий маршрут до роботи. Навички: почати вивчати щось незнайоме, зробити перший крок у проєкті що лякає. Відмова від звичного: не перевіряти телефон годину.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Як зони комфорту розширюються</b><br>Нейронаука: звикання через повторення знижує рівень тривоги від нових стимулів. Перший раз важко — третій вже легко — десятий — норма. Нова зона комфорту розширилась. Хибний міф: зона комфорту зменшується якщо не виходити. Насправді: стабільна, але вузька.</div></div><div class=\"final-note\">📌 Велике і радикальне — не завжди краще. Марафон після нуля фізактивності — травма. Прогулянки 20 хв щодня → 5км пробіжки → марафон — шлях. Мікрокроки накопичуються у великі зміни.</div>"],[395,"Якісне планування відпустки","<div class=\"rule-note\">🏖️ <b>Планування відпустки</b> — значна частина задоволення формується ще до від'їзду: під час очікування і підготовки (Nawijn et al., 2010). Не треба ідеального маршруту — достатньо балансу між планованим і спонтанним.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Що планувати заздалегідь</b><br>Квитки і житло: бронювання за 1–3 місяці для кращих цін і вибору. Документи: паспорт (термін дії), страховка подорожі, візи якщо потрібні. «Якорі» маршруту: 2–3 речі що точно хочеш побачити/зробити. Решта — спонтанно.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Баланс: план і гнучкість</b><br>Надмірне планування вбиває відпустку: щогодинний розклад = втома від «туристичної обов'язки». Правило: заплановано 50% часу, 50% — відкриті. Якщо щось сподобалось — залишайся довше. Кращі враження часто незаплановані.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Відновлення vs враження</b><br>Визнач мету відпустки: відновлення (потрібен повільний темп) або враження (нові місця, активність). Неправильний вибір типу = повернення більш втомленим ніж до. «Пляж і ресторани» і «10 країн за 14 днів» — різні відпустки для різних потреб.</div></div><div class=\"final-note\">📌 Офлайн-копії: квитки, бронювання, карти — на телефоні без інтернету. Завжди корисно. Відпустка без роботи: домовся про «вимкнений режим» заздалегідь — мозок не відновлюється якщо ти «в доступності». Це не розкіш — умова повноцінного відновлення.</div>"],[396,"Пошук натхнення в буденності","<div class=\"rule-note\">✨ <b>Натхнення в буденності</b> — здатність помічати цікаве і красиве в звичайному житті. Розвивається як навичка через увагу і практику спостереження.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Практика уважного спостереження</b><br>Прогулянка без телефону: один маршрут — але уважно. Що помічаєш що зазвичай проходиш мимо? Фотографія: знімай те що здається звичайним — потім переглянь. Запис деталей: щоденник спостережень — 2–3 помічені дрібниці дня.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Зміна кута зору</b><br>«А що якщо?»: додавання гіпотетики до звичного. Дитячий погляд: «Чому це так влаштовано?», «Як це зроблено?» — повертає цікавість. Змінюй маршрут, час кафе, кімнату для роботи — нове середовище активує сприйняття.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Натхнення від людей і розмов</b><br>Справжні розмови: не «як справи — добре» а «що тебе зараз цікавить/турбує/захоплює?». Читання біографій: бачиш як звичайні люди знаходили рішення у буденних обставинах. Запитуй: «Як ти до цього прийшов?» — за кожною людиною цікава історія.</div></div><div class=\"final-note\">📌 Натхнення не чекають — його помічають. Муза приходить під час роботи, а не замість неї. Регулярна практика творчості — у будь-якій формі — підтримує стан відкритості до натхнення.</div>"],[397,"Формулювання особистого кодексу","<div class=\"rule-note\">📜 <b>Особистий кодекс</b> — сформульовані цінності і принципи що визначають як ти хочеш жити і ким бути. Допомагає приймати рішення у складних ситуаціях і зберігати цілісність.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Як визначити свої цінності</b><br>Питання: Коли ти відчував найбільше задоволення і гордість собою — що ти робив? Що тебе злить у поведінці інших — протилежне твоїм цінностям. Коли відчував що «зрадив себе» — яку цінність порушив? Список: 5–10 ключових цінностей. Скорочення до 3–5 найважливіших.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Формулювання принципів</b><br>Не абстрактно — конкретно. Не «будь чесним» — а «якщо я не можу сказати правду, я мовчу, але не брешу». Принципи — правила поведінки що ти виконуєш коли нікого нема поруч. Формат: «Я...» або «Коли [ситуація], я [дія]».</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Як використовувати кодекс</b><br>Перед складним рішенням: «Яке з моїх принципів стосується цього?» Після дії що здалась неправильною: «Яку цінність я порушив?» Раз на рік: переглянь і оновлюй — людина змінюється. Не правила для показу — інструмент самопізнання.</div></div><div class=\"final-note\">📌 Кодекс і релігія/етика: не замінюють, а доповнюють. Марк Аврелій «Наодинці з собою» — один із найвидатніших особистих кодексів в історії. Написання кодексу — не на один вечір: формулюється через роки усвідомленого досвіду.</div>"],[398,"Чистка інформаційного простору","<div class=\"rule-note\">🧹 <b>Інформаційна гігієна</b> — свідомий вибір джерел і типів інформації що споживаєш. «Сміттєва» інформація виснажує увагу і когнітивні ресурси так само як фізичний безлад — простір.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Аудит джерел інформації</b><br>Перелічи всі джерела: новини, соцмережі, розсилки, подкасти, YouTube-канали. Питання до кожного: Регулярно читаю/дивлюсь? Дає реальну користь або задоволення? Або просто споживаю за звичкою? Залиш лише корисні і цікаві — без вини.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Відписка без вагань</b><br>Email-розсилки: «відписатись» одразу при першому відчутті що читаєш лише з звички. Правило inbox zero: кожен лист — дія, відповідь або архів. Соцмережі: «Unfollow» без «видалення зі списку друзів» — алгоритм не бачить тебе в їхній стрічці, ти не бачиш їх. Чисте середовище.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Новинна детоксикація</b><br>Перевіряй новини 1–2 рази на день у визначений час, а не постійно. Якщо щось важливе сталось — дізнаєшся від людей або при перевірці. Більшість «термінових» новин: не вимагають негайної реакції. Менше новин ≠ менш поінформований: більшість новин — шум.</div></div><div class=\"final-note\">📌 Правило: якщо ти почуваєшся гіршим після перегляду — це не інформація, це шум. Якісні джерела (The Economist, наукові журнали, книги, аналітика) ≠ «більше» — їх менше, але глибше.</div>"],[399,"Гнучкість у плануванні","<div class=\"rule-note\">🔄 <b>Гнучкість у плануванні</b> — здатність адаптувати плани без стресу і відчуття провали. Плани — прогноз, не обіцянка. Зміна плану ≠ невдача.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Планування з буфером</b><br>Не заповнюй день на 100%: 80% завантаження максимум. 20% — буфер для непередбачуваного (завжди є). «Overscheduling»: планування більше ніж реально виконати — гарантований стрес і відчуття провали. Кожна задача займає довше ніж здається (planning fallacy).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Перегляд і адаптація</b><br>Якщо щось не вийшло — переплануй (не відкладай в «колись»). Питання: «Що заважає? Це вирішувано?» «Це досі пріоритет?» Гнучкий перегляд — не відмова від цілей, а реалістична адаптація. Плани «на камені» без можливості зміни — ціль перфекціонізму, не ефективності.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Мінімальна версія задачі</b><br>Якщо не можеш виконати задачу повністю — зроби мінімальну версію. 10-хвилинне тренування замість запланованих 60 — краще ніж нічого. «Щось завжди краще ніж нічого» — зберігає звичку і імпульс навіть у складні дні.</div></div><div class=\"final-note\">📌 «Fail to plan — plan to fail»: планування важливе. «Якщо план не відповідає реальності — мінятись має план, не реальність». Обидві правди одночасно. Баланс: структура + гнучкість = стала продуктивність без вигорання.</div>"],[400,"Аналіз власного досвіду (Reflective Practice)","<div class=\"rule-note\">🔭 <b>Reflective Practice</b> — структурований аналіз свого досвіду для отримання уроків і покращення. Дональд Шон: «Навчання через дію» — найефективніший шлях розвитку навичок.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Цикл Колба (Experiential Learning)</b><br>Конкретний досвід → Рефлексивне спостереження («що сталось?»): → Абстрактна концептуалізація («що я зрозумів?»): → Активне експериментування («що спробую інакше?»). Можна застосовувати після будь-якої важливої ситуації: розмова, проєкт, рішення.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Прості питання для рефлексії</b><br>Що пройшло добре? Що б я зробив інакше? Що здивувало? Що я дізнався про себе або ситуацію? Що я застосую наступного разу? 10 хвилин відповідей письмово — один із найефективніших інструментів особистісного зростання.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Рефлексія в різних форматах</b><br>Щоденник: регулярна практика письмової рефлексії. Дебриф після проєкту: «що ми дізнались?» — важлива командна звичка. Менторська розмова: питання ментора допомагають побачити те що сам не помічаєш. Супервізія в допомагаючих професіях: обов'язкова рефлексія практики.</div></div><div class=\"final-note\">📌 Досвід без рефлексії = лише «стаж», а не розвиток. Можна робити одне й те саме 10 років і не вчитись — якщо не аналізуєш. Рефлексія перетворює досвід на знання і вміння.</div>"],[401,"Усвідомленість у моменті (Mindfulness)","<div class=\"rule-note\">🧘 <b>Mindfulness</b> — навмисна, безоцінна увага до теперішнього моменту. Не буддизм і не містика — психологічний інструмент з доведеною ефективністю для зниження стресу і підвищення концентрації.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Формальна практика: медитація</b><br>Початок: 5–10 хвилин щодня. Положення: сидячи з прямою спиною, не обов'язково лотос. Техніка: фокус на диханні. Думки з'являються — нормально. Помітив думку → повертаєш увагу до дихання — це і є практика (не «порожня голова»). Програми: Headspace, Calm, Insight Timer, Fabrika.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Неформальна практика: моменти уваги</b><br>Усвідомлене їдиніє: присутній, без телефону, відчуваєш смак і текстуру. Усвідомлена ходьба: відчуваєш стопи, помічаєш навколишнє. Усвідомлене слухання: повна присутність у розмові. Пауза між стимулом і реакцією — найпростіша форма мінімальної медитації.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Доведені ефекти</b><br>Програма MBSR (Mindfulness-Based Stress Reduction, Джон Кабат-Зінн): 8 тижнів, доведено знижує тривогу, болі, реактивність. Дослідження нейровізуалізації: регулярна практика змінює структуру мозку (збільшення сірої речовини у префронтальній корі). Концентрація, емоційна регуляція, стресостійкість — покращуються при регулярній практиці.</div></div><div class=\"final-note\">📌 Mindfulness не є панацеєю і не замінює терапію при серйозних станах. Дослідник Річард Девідсон (UW-Madison): «Мозок має нейропластичність — його можна тренувати». Мінімальна ефективна доза: 10 хвилин щодня протягом 8 тижнів дають відчутний ефект.</div>"]]},
    {
      n: "Блок 6: Батьківство та виховання дітей",
      e: "Parenting and Child Development",
      cards: [
        [2002,"Вікові кризи дитини: 1, 3, 7 та 13 років","<div class=\"rule-note\">Вікові кризи — нормальні переходи між стабільними стадіями розвитку (Л.С.&nbsp;Виготський). Дитина стає «важковиховуваною» — це ознака зростання, не проблема.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Криза 1 року</b> — перші кроки, перші слова. Дитина відкриває нову свободу пересування, але ще залежна. Прояви: примхи, протести, підвищена вередливість.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Криза 3 років</b> — «Я сам!» Прагнення до самостійності, впертість, негативізм. Завдання батьків — давати вибір у безпечних межах, не придушувати ініціативу.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Криза 7 років</b> — підготовка до школи. Дитина втрачає безпосередність, з'являється «симптом гіркої цукерки»: намагається приховати неприємні переживання. Потребує поваги, а не лише опіки.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Криза 13 років</b> — підліткове самоствердження. Пошук ідентичності, відторгнення дорослих цінностей, груповий вплив ровесників різко зростає.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Правило для батьків</b> — не боротися з кризою, а супроводжувати: зберігати стосунки, поступово давати більше самостійності, не карати за прояви кризи.</span></div><div class=\"final-note\">Криза — не катастрофа. Дитина, яку підтримали, виходить з неї з новими навичками і міцнішим зв'язком з батьками.</div>"],
        [2003,"Активне слухання у спілкуванні з дитиною","<div class=\"rule-note\">Активне слухання — техніка, описана психологом Юлією Гіппенрейтер: повне зосередження на дитині, відображення її почуттів без оцінок і порад. Допомагає дитині самій осмислити переживання.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Поверніться обличчям</b> — вимкніть телефон, відкладіть справи. Фізична присутність сигналізує: «ти важливий/важлива».</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Парафраз</b> — переказуйте своїми словами: «Ти говориш, що...». Дитина чує себе збоку і краще розуміє власні думки.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Відображення почуттів</b> — називайте емоцію: «Схоже, тебе це засмутило». Не «заспокойся» — а визнання реальності переживання.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Відкриті питання</b> — «Розкажи більше», «Що тебе найбільше зачепило?» — замість питань із відповіддю «так/ні».</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Пауза</b> — після відповіді дитини витримайте тишу. Часто саме після паузи вона говорить найважливіше.</span></div><div class=\"step c2\"><span class=\"step-num\">6</span><span class=\"step-text\"><b>Уникайте блокаторів</b> — поради, мінімізація («не переймайся»), порівняння з іншими дітьми переривають контакт і закривають розмову.</span></div><div class=\"final-note\">Дитина, яку чують, менше потребує кричати, щоб бути поміченою.</div>"],
        [2004,"Як говорити з дитиною про складні теми","<div class=\"rule-note\">Складні теми — смерть, секс, война, розлучення — викликають тривогу у батьків. Але замовчування народжує фантазії, часто страшніші за правду.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Не чекайте «правильного моменту»</b> — ініціюйте самі, просто й спокійно. Дитина відчуває, коли тема заборонена, і замовкає теж.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Мова відповідно до віку</b> — до 6&nbsp;р.: коротко й конкретно. 7–12&nbsp;р.: можна обговорювати причини і наслідки. Підліток: розмова як між рівними.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Перевірте, що дитина вже знає</b> — «Ти щось про це чув/ла?» Так не доведеться розповідати зайвого або виправляти стрес від неправдивої інформації.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Дозвольте запитання і мовчання</b> — «Ти можеш запитати мене про що завгодно». Якщо не знаєте відповіді — так і скажіть.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Не вимагайте реакції зразу</b> — дитина може повернутися з запитанням через день або тиждень. Це нормально і добре.</span></div><div class=\"final-note\">Відкритість батьків у складних темах формує довіру, яка знадобиться в підлітковому віці.</div>"],
        [2005,"Встановлення меж без крику та покарань","<div class=\"rule-note\">Межі — це не заборони заради заборон, а структура безпеки. Дитина з чіткими межами відчуває себе захищеною, а не пригніченою.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Формулюйте позитивно</b> — «Йдемо вмиватися» замість «Не бруднись». Дитячий мозок обробляє директиву, а не заперечення.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Одне правило — одна причина</b> — «Ми лягаємо спати о 21:00, бо мозок відновлюється вночі». Зрозуміла логіка краще сприймається, ніж «тому що я так сказав/ла».</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Наслідки, а не покарання</b> — наслідок пов'язаний з вчинком (не прибрав іграшки → грати з ними завтра). Покарання не пов'язане (накричав → позбавлений телевізора на тиждень).</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Послідовність</b> — правило, яке діє лише «коли батько в настрої» — не межа. Дитина тестує саме непослідовні правила.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Емпатія перед межею</b> — «Я бачу, що ти хочеш ще пограти. І все одно — час вечеряти». Визнання почуттів не скасовує межу.</span></div><div class=\"step c2\"><span class=\"step-num\">6</span><span class=\"step-text\"><b>Не кричіть</b> — крик сигналізує дитині, що дорослий втратив контроль. Тихий, твердий голос — більш авторитетний.</span></div><div class=\"final-note\">Межі — це не про владу над дитиною, а про передбачуваний світ, де вона може розвиватися.</div>"],
        [2006,"Похвала та критика: як не підірвати самооцінку","<div class=\"rule-note\">Те, як ми хвалимо й критикуємо, формує ставлення дитини до помилок. Дослідження Керол Двек (Стенфорд): похвала за здібності знижує готовність ризикувати; похвала за зусилля — підвищує стійкість.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Хваліть зусилля, а не здібності</b> — «Ти добре попрацював» замість «Ти такий розумний». Дитина вчиться не боятися нових завдань.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Будьте конкретні</b> — «Ти сам вирішив цей приклад, хоча спочатку він здавався важким» — цінніше, ніж «молодець».</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Не порівнюйте з іншими дітьми</b> — порівнюйте з попередньою версією самої дитини: «Минулого місяця ти зупинявся на першій помилці, а тепер — ні».</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Критикуйте дію, не особистість</b> — «Ти зробив боляче Михайлу» замість «Ти поганий». Дитина має розуміти: вчинок поганий, вона сама — ні.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Уникайте умовної любові</b> — «Я тебе люблю, коли ти...» — руйнівна формула. Любов — безумовна, вимоги — до поведінки.</span></div><div class=\"final-note\">Дитина з міцною самооцінкою не боїться помилятися — вона вчиться на помилках.</div>"],
        [2007,"Цифрова безпека дитини: правила для батьків","<div class=\"rule-note\">Діти в інтернеті стикаються з реальними ризиками: небажаний контент, кібербулінг, онлайн-маніпуляції. Завдання батьків — не заборонити, а навчити безпечній поведінці.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Відкрите спілкування</b> — дитина має знати: якщо щось онлайн наляканло або зніяковіло — вона може прийти до вас без страху покарання.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Правила використання</b> — спільно погоджені: де, коли, скільки. ВООЗ (2019): до 2&nbsp;р. — без екранів, 3–4&nbsp;р. — до 60&nbsp;хв/день. Для старших — важливіший тип контенту.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Персональні дані</b> — не називати онлайн ім'я, школу, адресу, не відправляти фото незнайомцям. Правило: незнайомець онлайн — незнайомець.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Правило «підводного плавця»</b> — якщо робиш щось онлайн, а батьки побачать — чи буде незручно? Якщо так — не роби.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Батьківський контроль</b> — налаштуйте фільтри (Google&nbsp;Family&nbsp;Link, iOS&nbsp;Screen&nbsp;Time) як допоміжний інструмент, але не замість довіри та розмови.</span></div><div class=\"step c2\"><span class=\"step-num\">6</span><span class=\"step-text\"><b>Сигнали тривоги</b> — дитина ховає екран, стає замкненою, нервує при повідомленнях — привід для спокійної розмови, а не обшуку телефону.</span></div><div class=\"final-note\">Цифрова грамотність дитини починається з довіри до батьків, а не з заборон.</div>"],
        [2008,"Шкільний булінг: як розпізнати та діяти","<div class=\"rule-note\">Булінг — систематичне, навмисне заподіяння шкоди з нерівністю сил між сторонами. Відрізняється від звичайного конфлікту повторюваністю та дисбалансом (МОН України).</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Ознаки того, що дитину булять</b> — небажання йти до школи, різкі зміни настрою, зникають або псуються речі, немає друзів, погіршення здоров'я без медичної причини.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Як говорити з дитиною</b> — спокійно, без допиту, без «сам/а винен/на». «Я на твоєму боці». Не казати «просто ігноруй» — це не працює і знецінює переживання.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Зверніться до школи</b> — до класного керівника або адміністрації письмово. Фіксуйте дати, факти, імена. Ведіть щоденник подій.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Не залучайте батьків кривдника без школи</b> — це може загострити ситуацію. Дійте через офіційні канали школи.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Підтримуйте самооцінку вдома</b> — позашкільні заняття, де дитина успішна, допомагають пережити шкільний стрес і зберегти відчуття власної цінності.</span></div><div class=\"step c2\"><span class=\"step-num\">6</span><span class=\"step-text\"><b>Серйозні прояви</b> — фізичне насильство, погрози — звертайтеся до поліції. Відповідно до ст.&nbsp;173-4 КУпАП, булінг є адміністративним правопорушенням.</span></div><div class=\"final-note\">Дитина, яку булять, не повинна справлятися з цим сама. Мовчання — не рішення.</div>"],
        [2009,"Вибір школи та позашкільних занять","<div class=\"rule-note\">Вибір школи та гуртків — одне з найважливіших рішень для дитини. Орієнтуйтеся на конкретну дитину, а не на загальні рейтинги.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Школа — за цінностями, а не за престижем</b> — відвідайте відкриті уроки, поговоріть з учителями. Як ставляться до дітей? Чи є психолог? Яка атмосфера в класі?</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Навчальний стиль дитини</b> — активній дитині важко в жорсткій академічній школі. Тривожній — потрібне передбачуване середовище. Знайте свою дитину.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Позашкільні заняття — за інтересами дитини</b> — запитайте: «Що тобі цікаво спробувати?», а не «Ти підеш у плавання». Не реалізуйте свої мрії через дитину.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Тест-драйв</b> — більшість секцій дають пробні заняття. Не платіть за рік наперед, поки дитина не визначилась після 2–3 занять.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Не перевантажуйте розклад</b> — дитині потрібен вільний час для гри і відпочинку. Зайнятість кожен день — джерело стресу, а не розвитку.</span></div><div class=\"final-note\">Найкраща школа — та, де дитина почувається в безпеці і хоче вчитися.</div>"],
        [2010,"Домашні завдання: як допомагати без надмірної опіки","<div class=\"rule-note\">Допомога з домашнім завданням стає проблемою, коли батько робить завдання замість дитини. Мета — розвиток самостійності, а не бездоганний зошит.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Визначте час і місце</b> — стала рутина знижує опір: щодня о тій самій годині, за столом, без телевізора і телефону.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Спочатку — самостійно</b> — нехай дитина спробує сама, навіть якщо зробить помилки. Помилки — частина навчання.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Запитуйте, а не підказуйте</b> — «Що ти вже розумієш у цій задачі?» замість «Дивись, треба так...»</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Допомагайте розібрати алгоритм</b> — «Яке правило тут застосовується?» допомагає більше, ніж «правильна відповідь».</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Не перевіряйте все</b> — щоденна перевірка кожного рядка — це ваша тривога, а не турбота. Дитина має відчувати відповідальність за своє навчання.</span></div><div class=\"step c2\"><span class=\"step-num\">6</span><span class=\"step-text\"><b>Якщо постійні сльози</b> — сигнал до вчителя, а не підвищення «доз» домашньої роботи. Можливо, є прогалини в розумінні матеріалу.</span></div><div class=\"final-note\">Дитина, яка навчилась робити уроки самостійно, легше справляється з труднощами в дорослому житті.</div>"],
        [2011,"Батьківське вигорання: симптоми та відновлення","<div class=\"rule-note\">Батьківське вигорання — окремий синдром, що виникає внаслідок хронічного батьківського стресу. Описаний Роскам&nbsp;і&nbsp;Міколайчак (Левенський університет, Бельгія). Не слабкість — стан, що потребує уваги.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Чотири ознаки вигорання</b> — виснаження у батьківській ролі; емоційне дистанціювання від дитини; відчуття, що «раніше я був/ла кращим батьком»; відчуття власної неефективності.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Відрізняйте від звичайної втоми</b> — втома проходить після відпочинку. Вигорання — ні. Якщо відпочили, а завтра знову «порожньо» — це сигнал.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Прийміть реальність стану</b> — думка «я просто недостатньо намагаюсь» підсилює вигорання, а не вирішує його. Це не про характер, а про вичерпані ресурси.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Перерозподіл навантаження</b> — чи є хтось, хто може взяти частину обов'язків? Партнер, родичі, навіть на кілька годин. Запросити допомогу — не слабкість.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Психологічна допомога</b> — вигорання добре піддається короткостроковій терапії (КПТ). Звернення до спеціаліста — ефективний інструмент, а не крайній захід.</span></div><div class=\"step c2\"><span class=\"step-num\">6</span><span class=\"step-text\"><b>Дбайте про себе паралельно</b> — не «після дітей», а поряд. Батько, у якого немає нічого свого, ресурсів не відновлює.</span></div><div class=\"final-note\">Ви не можете налити з порожньої склянки. Турбота про себе — це турбота про дитину.</div>"],
        [2012,"Комунікація з дитиною-підлітком","<div class=\"rule-note\">Підлітковий вік (приблизно 11–17&nbsp;р.) — час нейробіологічної перебудови мозку, зростання ролі ровесників і пошуку власної ідентичності. Стиль спілкування батьків потребує перегляду.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Менше запитань — більше присутності</b> — «Як справи?» в лоб викликає «нормально». Спільна діяльність (їзда в авто, приготування їжі) відкриває розмову природно.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Слухайте без негайного вирішення</b> — підліток не завжди хоче поради. Уточніть: «Ти хочеш, щоб я просто вислухав, чи шукаєш рішення?»</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Визнайте право на незгоду</b> — підліток формує власні погляди. Суперечка — це розвиток, а не атака. Не треба завжди «перемагати».</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Межі залишаються</b> — тепер вони обговорюються, а не лише оголошуються. «Чому я маю бути вдома о 22:00?» — законне запитання, заслуговує відповіді.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Залишайте двері відчиненими</b> — «Якщо тобі буде погано — я тут». Не тисніть, але дайте знати про свою доступність.</span></div><div class=\"step c2\"><span class=\"step-num\">6</span><span class=\"step-text\"><b>Тривожні сигнали</b> — різке погіршення оцінок, самоізоляція, зміни у харчуванні та сні, нові незнайомі дорослі в оточенні — привід для розмови зі шкільним психологом.</span></div><div class=\"final-note\">Підліток, який знає, що батьки поруч без осуду, рідше звертається за підтримкою до деструктивних джерел.</div>"],
        [2013,"Як говорити про гроші з дітьми різного віку","<div class=\"rule-note\">Фінансова грамотність формується в дитинстві. Відкриті розмови про гроші дають реалістичне розуміння цінності та обмежень — без тривоги і таємниць.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>3–5 р.: поняття обміну</b> — гроші — це інструмент обміну. Дайте монети, нехай «купить» в магазині. Три скарбнички: «витрачаю», «заощаджую», «ділюсь».</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>6–9 р.: кишенькові гроші і вибір</b> — невелика регулярна сума + право розпоряджатися без осуду. Не компенсуйте, якщо витратить одразу — досвід дефіциту теж корисний.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>10–13 р.: бюджет на конкретну мету</b> — «Хочеш нову гру — ось місячна сума, яку можеш відкладати». Навчіть рахувати: скільки тижнів до мети.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>14+: поняття доходу і витрат сім'ї</b> — прозорість знімає страхи і дає реалізм. Можна показати загальну структуру бюджету без деталей.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Не використовуйте гроші як нагороду чи покарання</b> — «отримаєш гроші за п'ятірку» змішує навчання і винагороду. Краще — кишенькові на фіксованій основі.</span></div><div class=\"final-note\">Дитина, яка вміє поводитися з грошима у 10 р., рідше потрапляє в боргову пастку у 25.</div>"],
        [2014,"Гаджети та час перед екраном: норми та обмеження","<div class=\"rule-note\">ВООЗ (2019) встановила рекомендації щодо екранного часу: до 1&nbsp;р. — без екранів; 1–2&nbsp;р. — уникати; 3–4&nbsp;р. — не більше 60&nbsp;хв/день. Для старших дітей жорстких норм немає — важливіший контекст використання.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>До 2 р.: уникайте екранів</b> — мозок розвивається через живе спілкування, дотик, дослідження. Відеодзвінки з рідними — виняток.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>3–4 р.: до 60 хв/день, тільки з батьками</b> — обирайте освітній контент і дивіться разом, обговорюйте побачене.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>6–12 р.: домовляйтесь про правила разом</b> — де (не в спальні), коли (не за годину до сну), що (не агресивний контент). Правила мають сенс для дитини.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Якість важливіша за кількість</b> — 30 хв пізнавального контенту краще за 2 год пасивних відео. Гаджет як інструмент, а не виховна пауза.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Сигнали надмірного використання</b> — агресія при вимкненні, нічне використання, відмова від їжі чи прогулянок — привід для розмови з психологом.</span></div><div class=\"step c2\"><span class=\"step-num\">6</span><span class=\"step-text\"><b>Будьте прикладом</b> — діти копіюють батьків. Телефон на вечері — сигнал, що це нормально.</span></div><div class=\"final-note\">Гаджет — інструмент. Завдання батьків — навчити ним користуватись, а не просто обмежити.</div>"],
        [2015,"Дитячі конфлікти: коли втручатися батькам","<div class=\"rule-note\">Не кожна суперечка між дітьми потребує втручання дорослого. Вміння вирішувати конфлікти — важлива соціальна навичка, яка розвивається лише на практиці.</span></div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Спершу спостерігайте</b> — якщо діти сперечаються словами і за рівних умов — дайте шанс вирішити самостійно. Одразу втручання навчає: «сам не вирішу — покличу дорослого».</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Коли втручатись обов'язково</b> — фізичне насильство, явна нерівність (один значно менший або слабший), або дитина в паніці — час зупинити.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Не ставайте суддею</b> — не шукайте «хто правий». Запитайте обох: «Що сталось? Що ти хотів/ла?» Нехай самі знайдуть компроміс.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Вчіть мовою</b> — «Скажи Оленці: мені не подобається, коли ти берёш мою іграшку без питання». Слова замість кулаків і крику.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Не порівнюйте дітей</b> — «Дивись, як Петрик ділиться» підсилює суперництво, а не вирішує конфлікт.</span></div><div class=\"final-note\">Дитина, яка навчилась домовлятися у пісочниці, легше вирішує конфлікти на роботі.</div>"],
        [2016,"Підготовка дитини до самостійності: покроково","<div class=\"rule-note\">Самостійність не виникає раптово у 18&nbsp;р. Вона розвивається поступово через дозволені помилки і зростаючу відповідальність.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Відповідно до віку</b> — 3&nbsp;р.: прибирає іграшки. 5&nbsp;р.: одягається сам. 7&nbsp;р.: готує бутерброд. 10&nbsp;р.: іде в магазин. 13&nbsp;р.: планує свій час. Не роби за дитину те, що вона вже може сама.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Право на помилку</b> — не кидайтесь виправляти одразу. Запитайте: «Як думаєш, що пішло не так?» Помилка — не катастрофа, а навчання.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Домашні обов'язки</b> — не допомога батькам, а внесок у спільне домашнє господарство. Дитина — повноправний член сім'ї, а не гість.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Навички виживання</b> — приготувати їжу, зробити запис до лікаря, написати офіційний лист — до 16&nbsp;р. дитина має знати основи.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Відпустіть контроль поступово</b> — гіперконтроль формує або залежність, або прихованість. Довіра — основа самостійності.</span></div><div class=\"final-note\">Ваша ціль як батька/матері — зробити себе непотрібним. Поступово.</div>"],
        [2017,"Як пояснити дитині смерть близького","<div class=\"rule-note\">Смерть — реальна частина життя. Уникання теми не захищає дитину від горя — воно позбавляє її слів і підтримки, щоб горе пережити.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Говоріть правду</b> — не «пішла у кращий світ», «заснула», «поїхала далеко». Маленька дитина буде шукати бабусю або боятися засинати. Використовуйте слова «помер», «смерть».</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Відповідно до розуміння дитини</b> — 3–5&nbsp;р.: смерть — постійна відсутність. 6–8&nbsp;р.: можна пояснити біологічну природу. Підліток: може обговорювати складні питання сенсу і горя.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Дозвольте всі емоції</b> — плач, злість, мовчання, навіть сміх — усе можливе. Не кажіть «не плач» або «будь сильним/ою».</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Збережіть рутину</b> — стала рутина дає відчуття безпеки в час хаосу горя.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Дозвольте проститися</b> — участь у похоронному ритуалі (якщо дитина хоче і готова) допомагає прийняти реальність втрати.</span></div><div class=\"step c2\"><span class=\"step-num\">6</span><span class=\"step-text\"><b>Затяжні симптоми</b> — горе, яке не минає через кілька місяців і заважає школі та спілкуванню — привід для допомоги дитячого психолога.</span></div><div class=\"final-note\">Відкрите горе, пережите разом, зміцнює сім'ю. Прихована втрата — ранить мовчки.</div>"],
        [2018,"Батьківська тривога: як не передати дитині","<div class=\"rule-note\">Батьківська тривога — природна. Проблема виникає, коли вона управляє поведінкою і непомітно передається дитині через надмірний контроль і застереження.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Розпізнайте свою тривогу</b> — «Я хвилююся за безпеку» — норма. «Я не дозволяю дитині нічого, бо щось може трапитись» — тривожне батьківство.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Дитина зчитує тіло</b> — напруженість, надмірні застереження («будь обережний!» двадцять разів) сигналізують дитині: «світ небезпечний».</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Дозвольте невеликий ризик</b> — падіння з гірки, суперечка з другом, невдача на контрольній — необхідні для розвитку стресостійкості.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Не транслюйте власні страхи</b> — несвідома передача фобій через коментарі та надмірну обережність у конкретних ситуаціях.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Розрізняйте реальну і уявну небезпеку</b> — реальна потребує дії. Уявна потребує роботи зі своєю тривогою, а не обмежень для дитини.</span></div><div class=\"step c2\"><span class=\"step-num\">6</span><span class=\"step-text\"><b>Звертайтесь за допомогою</b> — якщо тривога заважає вашому функціонуванню, короткострокова терапія (КПТ) ефективна і доступна.</span></div><div class=\"final-note\">Дитина засвоює ваше ставлення до світу — не лише ваші слова.</div>"],
        [2019,"Два батьки — різні підходи: узгодження стилів виховання","<div class=\"rule-note\">Різні стилі виховання у батьків — норма. Небезпека не в різниці, а в публічних суперечках і «грі» дитини на протиріччях між батьками.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Не спростовуйте рішення одне одного при дитині</b> — «Тато дозволив, а я кажу ні» — сигнал для дитини: можна маніпулювати. Незгоду — наодинці.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Знайдіть спільні цінності</b> — безпека, чесність, повага — на них будуйте єдину позицію. Деталі (кількість солодкого, час сну) можуть відрізнятись.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Обговорюйте без дитини</b> — незгоду вирішуйте наодинці. Дитина бачить узгоджений результат, а не процес сварки.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Нейтральний третій</b> — якщо не можете домовитися, сімейний психолог допомагає знайти спільну мову без звинувачень.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Права батька і матері рівні</b> — жодна позиція не є автоматично «правильнішою». Прагніть до діалогу, а не до перемоги.</span></div><div class=\"final-note\">Дитині не потрібні ідеальні батьки. Потрібні батьки, які поважають одне одного.</div>"],
        [2020,"Дитина і гроші: кишенькові витрати","<div class=\"rule-note\">Кишенькові гроші — практичний тренажер фінансової відповідальності. Правило просте: своя сума — повне право витрачати, без осуду і «доповнення».</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Коли починати</b> — з моменту, коли дитина розуміє поняття обміну (як правило, 5–6&nbsp;р.). Розмір — відповідно до реальних потреб і можливостей сім'ї.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Регулярність, а не «за попит»</b> — фіксована сума щотижня чи щомісяця. Не «заробіток», не «нагорода» — право члена сім'ї.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Не поповнюйте автоматично</b> — витратив усе в перший день? Обговоріть, але не давайте «аванс» одразу. Досвід дефіциту — необхідний урок.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Не коментуйте покупки</b> — «Навіщо ти це купив?» знецінює самостійність. Якщо вибір безпечний — це власне рішення дитини.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Три скарбнички</b> — витрачаю зараз / заощаджую на мету / даю/ділюсь — проста і перевірена структура для молодших дітей.</span></div><div class=\"final-note\">Гроші, якими керує сам, вчать більше, ніж будь-яка лекція про бюджет.</div>"],
        [2021,"Вибір секцій та гуртків: як не перевантажити","<div class=\"rule-note\">Позашкільні заняття корисні — вони розвивають навички, дають соціальне середовище і допомагають знайти покликання. Але надмірна зайнятість дає протилежний ефект.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Запитуйте дитину</b> — «Що тобі цікаво?» — не «Ти підеш у те, що я хотів/ла в дитинстві». Вимушене заняття стає обов'язком, а не розвитком.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Одне нове заняття за раз</b> — дайте час визначитись після 2–3 занять, перш ніж записуватись на наступне.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Вільний час — необхідний</b> — дитина без «вікон» між школою і гуртками не встигає відпочити, пограти і просто побути дитиною.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Сигнали перевантаження</b> — постійна втома, небажання йти на улюблене заняття, зниження оцінок, капризи — час переглянути розклад.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Право закинути</b> — якщо заняття не підходить після реального досвіду — дозвольте зупинитись після логічного завершення (кінець сезону, виступ).</span></div><div class=\"final-note\">Щасливе дитинство — це не максимум занять. Це баланс розвитку і відпочинку.</div>"],
        [2022,"Перехід до нової школи: підтримка дитини","<div class=\"rule-note\">Зміна школи — один з найбільших стресів для дитини: нове середовище, нові правила, нові люди. Адаптація займає час — зазвичай від кількох тижнів до кількох місяців.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Підготуйте заздалегідь</b> — якщо можливо, відвідайте нову школу до початку навчання. Знайомство з простором зменшує тривогу.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Визнайте, що це важко</b> — «Мені теж було б страшно на твоєму місці» краще, ніж «Ти швидко освоїшся» — це не мінімізує, а підтримує.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Допоможіть зі знайомством</b> — дізнайтеся, чи є позашкільні активності. Соціальні зв'язки формуються легше у спільних діяльностях поза класом.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Слідкуйте, але не тисніть</b> — щоденні питання «Як справи?» важливі. Але не вимагайте детального звіту кожного дня.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Дайте час</b> — перший місяць може бути важким. Це ще не провал.</span></div><div class=\"step c2\"><span class=\"step-num\">6</span><span class=\"step-text\"><b>Коли звертатись за допомогою</b> — якщо через 2–3 місяці дитина відмовляється йти до школи, немає жодного знайомого або є сильна тривога — до шкільного психолога.</span></div><div class=\"final-note\">Дитина, яку підтримали під час переходу, отримує досвід: зміни — переборні.</div>"],
        [2023,"Дитячий стрес: як помітити та допомогти","<div class=\"rule-note\">Діти переживають стрес так само, як дорослі — але не завжди мають слова для цього. Він виражається через поведінку та тіло.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Поведінкові ознаки стресу</b> — регрес (повернення до «дитячих» звичок після довгого периоду без них), агресія, замкненість, відмова від звичних занять.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Тілесні ознаки</b> — болі у животі або голові без медичної причини, порушення сну, відсутність апетиту або надмірне їдіння.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Не відмахуйтесь від скарг</b> — «Не придумуй» закриває канал. Навіть якщо причина вам здається незначною — для дитини вона реальна.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Знайдіть джерело</b> — школа, стосунки з ровесниками, сімейна ситуація? Запитайте прямо: «Що тебе зараз турбує найбільше?»</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Дайте природні інструменти</b> — фізична активність, малювання, гра — природні способи регуляції стресу для дитини.</span></div><div class=\"step c2\"><span class=\"step-num\">6</span><span class=\"step-text\"><b>Коли потрібен спеціаліст</b> — якщо симптоми тривають більше 2–3 тижнів і заважають школі або спілкуванню — направте до дитячого психолога.</span></div><div class=\"final-note\">Дитина, яку навчили розпізнавати стрес і давати йому раду, виростає стійкою людиною.</div>"],
        [2024,"Як підтримати дитину під час іспитів","<div class=\"rule-note\">Іспитова тривога — реальний психологічний феномен. Надмірний тиск з боку батьків посилює тривогу і знижує результат.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Відокремте цінність від оцінки</b> — «Ти важливий/важлива для мене незалежно від результату» — фундамент. Дитина, яка боїться розчарувати батьків, показує гірші результати через тривогу.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Організуйте підготовку</b> — разом складіть план: що і коли повторювати. Не замість дитини, а разом як підтримка.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Нормалізуйте тривогу</b> — «Хвилюватись перед важливим — нормально». Дитина не має відчувати себе слабкою через переживання.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Режим у дні перед іспитом</b> — повноцінний сон важливіший за нічне зубріння. Мозок закріплює знання під час сну.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>День іспиту</b> — повноцінний сніданок, без нових питань для перевірки, слова підтримки без тиску і без прогнозів щодо результату.</span></div><div class=\"step c2\"><span class=\"step-num\">6</span><span class=\"step-text\"><b>Після іспиту</b> — не аналізуйте помилки одразу. Спочатку — підтримка, потім — аналіз (якщо дитина хоче і готова).</span></div><div class=\"final-note\">Дитина запам'ятає не оцінку — вона запам'ятає, як ви поводились поруч із нею.</div>"],
        [2025,"Розмова з дитиною про особисту безпеку","<div class=\"rule-note\">Правила особистої безпеки — основа, яку дитина має знати до того, як опиниться у небезпечній ситуації. Розмова — спокійна і практична, без залякування.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Правило «Моє тіло — моє»</b> — ніхто не має права торкатися «купальникових зон» без дозволу, крім лікаря у присутності батьків. Дитина має право казати «ні» навіть дорослому.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Секрет vs сюрприз</b> — сюрприз розкривається і приносить радість. Секрет, який тримає дорослий з дитиною від батьків — небезпечний. Навчіть розрізняти.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Алгоритм при загрозі</b> — відійди, кричи, тікай. Не треба бути ввічливим з тим, хто намагається нашкодити.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Довірені дорослі</b> — разом складіть список: хто може забрати зі школи, до кого звернутись у разі небезпеки. Дитина має знати цей список напам'ять.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Онлайн-безпека</b> — незнайомець онлайн — незнайомець. Нікому не надсилати фото, адресу, номер школи.</span></div><div class=\"step c2\"><span class=\"step-num\">6</span><span class=\"step-text\"><b>«Якщо щось сталось — ти не винен/на»</b> — дитина має знати: розповісти батькам — правильно, навіть якщо «обіцяла не казати».</span></div><div class=\"final-note\">Дитина, яка знає правила, відчуває себе захищеною і менше боїться говорити про небезпечні ситуації.</div>"],
        [2026,"Баланс між опікою та свободою дитини","<div class=\"rule-note\">Гіперопіка і бездіяльність — дві крайності, які обидві шкодять розвитку. Завдання батьків — поступово розширювати свободу разом зі зростанням дитини.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Свобода, що відповідає віку</b> — 5&nbsp;р.: вибирає одяг. 8&nbsp;р.: іде до друга самостійно. 12&nbsp;р.: планує свій вихідний. 16&nbsp;р.: вибирає позашкільну активність. Переглядайте «дозволи» щороку.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Ризик — частина розвитку</b> — дитина без права помилятися не вчиться оцінювати наслідки. Дрібні ризики під контрольованими умовами — нормальна частина дитинства.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Ознаки гіперопіки</b> — ви завжди вирішуєте за дитину, боїтесь будь-якого ризику, дитина не знає, як діяти без вашої підказки. Це сигнал розширити автономію.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Гіпоопіка — протилежна небезпека</b> — дитина без орієнтирів шукає їх у вулиці або однолітках. Присутність батька/матері потрібна навіть підлітку.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Довіра — основа балансу</b> — «Я вірю, що ти впораєшся» + «Я тут, якщо щось піде не так» — правильна батьківська позиція.</span></div><div class=\"final-note\">Ваша ціль — не тримати дитину в безпеці завжди. Ваша ціль — навчити її бути безпечною без вас.</div>"]
      ]
    },
    {
      n: "Блок 7: Особисті інвестиції та фінансова незалежність",
      e: "Personal Investments and Financial Independence",
      cards: [
        [2047,"Фінансова незалежність: концепція та шлях до неї","<div class=\"rule-note\">Фінансова незалежність — стан, коли пасивний дохід від накопичених активів покриває витрати на життя без необхідності працювати. Рух FIRE (Financial Independence, Retire Early) популяризує цю ідею з 1990-х рр.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Суть ідеї</b> — ви досягаєте фінансової незалежності, коли ваш капітал генерує достатній прибуток для покриття всіх витрат. Це не обов'язково означає «нічого не робити» — це означає свободу вибору.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Правило 4%</b> — емпіричне правило (Bengen, 1994): портфель витримує вилучення ~4% на рік протягом 30+ років. Звідси: потрібний капітал ≈ ваші річні витрати × 25.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Три ключові важелі</b> — норма заощаджень (скільки зберігаєте від доходу), прибутковість інвестицій, тривалість накопичення. Висока норма заощаджень — найбільш керований важіль.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Різновиди FIRE</b> — Lean FIRE (мінімальний бюджет), Fat FIRE (комфортний рівень), Barista FIRE (частковий дохід зберігається). Обирайте відповідно до стилю життя.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Перший крок</b> — підрахуйте місячні витрати → помножте на 300 (25 × 12) → отримаєте орієнтовну цілеву суму капіталу. Це лише відправна точка для планування.</span></div><div class=\"final-note\">Фінансова незалежність — не мрія для багатих. Це математика: дохід, заощадження, час і дисципліна.</div>"],
        [2048,"Бюджетування: правило 50/30/20 та особистий бюджет","<div class=\"rule-note\">Бюджетування — свідомий розподіл доходів за категоріями витрат. Допомагає контролювати гроші замість того, щоб вони контролювали вас. Правило 50/30/20 — популярна відправна точка.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Правило 50/30/20</b> (Елізабет Воррен, «All Your Worth», 2005) — 50% доходу на потреби (житло, їжа, транспорт), 30% на бажання (розваги, кафе), 20% на заощадження і виплату боргів.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Як адаптувати</b> — правило є орієнтиром, не догмою. У містах з високою орендою частка «потреб» може бути більшою. Головне — заощадження понад 0% і розуміння своїх витрат.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Як вести бюджет</b> — фіксуйте всі витрати (додатки: MonoBank, Sense, YNAB, таблиця Google Sheets). Аналізуйте щомісяця: де перевитрата? Що можна скоротити без втрати якості життя?</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Платіть собі першими</b> — одразу після отримання доходу переводьте заощадження на окремий рахунок. Це не залишок, а пріоритет. Автоматизуйте перерахування.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Огляд підписок</b> — щоквартально переглядайте всі регулярні платежі (стрімінги, програми, доставки). Часто знаходять 500–1500&nbsp;грн/міс непотрібних витрат.</span></div><div class=\"final-note\">Бюджет — це не обмеження свободи. Це інструмент, який дає свободу витрачати без вини на те, що важливо.</div>"],
        [2049,"Подушка безпеки: скільки і де зберігати","<div class=\"rule-note\">Подушка безпеки — резервний фонд для покриття непередбачуваних витрат (втрата роботи, хвороба, поломка). Захищає від необхідності брати кредит у кризовий момент.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Рекомендований розмір</b> — зазвичай 3–6 місячних витрат. Якщо нестабільний дохід або є утриманці — ближче до 6–12 місяців. Якщо стабільна зайнятість — 3 місяці достатньо як мінімум.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Де зберігати</b> — в ліквідних інструментах: накопичувальний рахунок із щоденним нарахуванням відсотків, короткостроковий депозит «до запитання». НЕ в акціях — ринок може впасти саме коли гроші потрібні.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Окремий рахунок</b> — подушка має бути фізично відокремлена від поточного рахунку. Це психологічний бар'єр проти імпульсивних витрат. Доступ — лише у справжній надзвичайній ситуації.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Як накопичити</b> — якщо подушки немає: почніть із малого (1000–2000 грн/міс). Ціль — 1 місяць витрат як перший рубіж. Потім 3, потім 6. Не інвестуйте, доки немає хоча б базової подушки.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Після використання</b> — якщо довелося залучити резерв, відновлення подушки стає наступним фінансовим пріоритетом. Поверніть до попереднього рівня перед іншими цілями.</span></div><div class=\"final-note\">Подушка безпеки — не «заморожені гроші». Це страховий поліс, який ви видаєте самі собі.</div>"],
        [2050,"Інфляція: як вона впливає на заощадження","<div class=\"rule-note\">Інфляція — зростання загального рівня цін, що знижує купівельну спроможність грошей. Гроші «під матрацом» щороку коштують менше — навіть якщо їх кількість не змінюється.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Як рахувати вплив</b> — якщо інфляція 10% на рік, то 100 000 грн сьогодні через рік матимуть купівельну спроможність приблизно 90 909 грн. Через 7 років за правилом 70 (70÷10=7) — реальна вартість приблизно вдвічі менша.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Правило 70</b> — приблизна кількість років, за які купівельна спроможність вдвічі знизиться: 70 ÷ рівень інфляції (%). При 7% інфляції — ~10 років.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Реальна прибутковість</b> — прибутковість депозиту мінус інфляція. Якщо депозит 15% і інфляція 12% — реальна прибутковість лише ~3%. Завжди оцінюйте «реальний», а не номінальний дохід.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Захист від інфляції</b> — інструменти: акції (як правило, зростають разом з економікою), нерухомість, ОВДП з прив'язкою до інфляції, золото (як довгострокове сховище вартості, але не без ризику).</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Гривня і валюта</b> — диверсифікація у стабільні валюти (USD, EUR) — поширена практика в Україні для захисту від девальвації. Зберігайте в декількох валютах відповідно до горизонту і цілей.</span></div><div class=\"final-note\">Інфляція — невидимий податок на бездіяльність. Гроші, що не працюють, щороку стають меншими.</div>"],
        [2051,"Банківський депозит: переваги, обмеження, варіанти","<div class=\"rule-note\">Банківський депозит — розміщення коштів у банку під відсоток на визначений строк. Найпростіший і найбезпечніший спосіб отримати дохід, що перевищує інфляцію (не завжди).</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Гарантія вкладів</b> — в Україні Фонд гарантування вкладів (ФГВ) відшкодовує до 600 000 грн на одного вкладника в одному банку. Суми понад ліміт — ризик вкладника.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Строковий vs до запитання</b> — строковий депозит вищий відсоток, але гроші заблоковані. Депозит «до запитання» або накопичувальний рахунок — нижчий відсоток, але миттєвий доступ. Для подушки безпеки — другий варіант.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Капіталізація відсотків</b> — відсотки нараховуються і додаються до суми вкладу, наступний відсоток рахується від збільшеної суми. Депозит із щомісячною капіталізацією вигідніший за депозит «відсотки наприкінці строку» при тій самій ставці.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>ОВДП як альтернатива</b> — облігації внутрішньої державної позики України. Як правило, дохідніші за депозити, гарантовані державою. Купуються через банки-брокери або через Дія (для фізичних осіб).</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Оподаткування</b> — дохід від депозитів в Україні оподатковується: ПДФО 18% + військовий збір 1,5% (5% з 2024). Банк утримує податок автоматично як податковий агент.</span></div><div class=\"final-note\">Депозит — інструмент збереження, а не примноження. Для захисту від інфляції зазвичай потрібні інші інструменти.</div>"],
        [2052,"Акції: що купує інвестор і як формується дохід","<div class=\"rule-note\">Акція — цінний папір, що засвідчує частку власності у компанії. Купуючи акцію, ви стаєте співвласником бізнесу — зі всіма правами і ризиками.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Два джерела доходу</b> — зростання курсу (капітальний приріст): купили дешевше, продали дорожче; дивіденди: частина прибутку, яку компанія виплачує акціонерам (не всі компанії платять дивіденди).</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Ринкова ціна</b> — формується попитом і пропозицією на фондовій біржі. Відображає очікування інвесторів щодо майбутніх прибутків компанії, не лише поточний стан.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Ризики</b> — ціна акції може впасти до нуля (банкрутство компанії). Акції — волатильний інструмент: коливання 20–50% за рік — норма для окремих компаній. Не підходять для короткострокового заощадження.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Як купити</b> — через брокера (ліцензована компанія-посередник). В Україні: Фрідом Фінанс, Dragon Capital, тощо. За кордоном: Interactive Brokers — популярний вибір серед українських інвесторів.</span></div><div class=\"step c5\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Горизонт інвестування</b> — акції показують кращі результати на довгому горизонті (від 5–10 років). Короткостроково ринок непередбачуваний. Не вкладайте в акції гроші, які знадобляться протягом 1–3 років.</span></div><div class=\"final-note\">Купити акцію — означає стати партнером у бізнесі. Вивчіть бізнес або інвестуйте через індексні фонди.</div>"],
        [2053,"Облігації: боргові інструменти для консервативних інвесторів","<div class=\"rule-note\">Облігація — борговий цінний папір: емітент (держава, компанія) позичає у вас гроші і зобов'язується повернути їх з відсотками (купоном) у визначений строк.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Як працює</b> — ви купуєте облігацію номіналом 1000 грн на 2 роки з купоном 15%. Раз на рік (або раз на квартал) отримуєте 150 грн. Наприкінці строку — повернення 1000 грн.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Державні (ОВДП)</b> — найнижчий ризик серед облігацій в Україні. Гарантовані урядом. Дохідність, як правило, вища за банківські депозити. Мінімальна сума залежить від брокера.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Корпоративні облігації</b> — вищий купон, але вищий ризик — залежить від фінансового стану компанії. Перед покупкою — вивчіть кредитний рейтинг емітента.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Ціна і дохідність</b> — мають зворотну залежність: якщо ринкові ставки зростають, ціна вже випущених облігацій падає. Якщо тримаєте до погашення — ринкова ціна не важлива.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Роль у портфелі</b> — облігації стабілізують портфель. Класичне розподілення: «вік у відсотках в облігаціях» (наприклад, 30 років → 30% облігацій). Захист від волатильності акцій.</span></div><div class=\"final-note\">Облігація — позика бізнесу або державі. Менший ризик, менша дохідність. Баланс у портфелі.</div>"],
        [2054,"Диверсифікація: як розподілити інвестиційний ризик","<div class=\"rule-note\">Диверсифікація — розподіл капіталу між різними активами, щоб збиток від одного не знищив весь портфель. «Не кладіть усі яйця в один кошик» — фундаментальний принцип управління ризиком.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>По класах активів</b> — акції, облігації, нерухомість, готівка/депозити. Різні класи активів, як правило, рухаються не синхронно: коли акції падають, облігації можуть рости.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>По географії</b> — не лише українські активи, але й міжнародні. Якщо економіка однієї країни у кризі, інші можуть зростати. Глобальні ETF дають доступ до акцій усього світу.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>По секторах</b> — у межах акцій: технологічний сектор, охорона здоров'я, споживчі товари, фінанси. Різні сектори реагують на економічні цикли по-різному.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>По валютах</b> — зберігання частини активів у USD, EUR знижує ризик девальвації національної валюти. Особливо актуально для країн із нестабільним курсом.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Межа диверсифікації</b> — надмірна диверсифікація (сотні різних активів) ускладнює управління й знижує потенційну прибутковість. Для приватного інвестора 3–7 різних інструментів — зазвичай достатньо.</span></div><div class=\"final-note\">Диверсифікація не максимізує прибуток. Вона мінімізує ймовірність катастрофічних втрат.</div>"],
        [2055,"ETF та індексні фонди: пасивне інвестування","<div class=\"rule-note\">ETF (Exchange Traded Fund) — біржовий інвестиційний фонд, що відстежує індекс (наприклад, S&P 500) і торгується на біржі як звичайна акція. Дає доступ до сотень компаній в одній покупці.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Що таке індекс</b> — кошик акцій за певним критерієм: S&P 500 — 500 найбільших компаній США; MSCI World — ~1500 компаній з розвинених ринків. Індекс зростає, коли зростає вартість компаній у ньому.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Переваги ETF</b> — миттєва диверсифікація (одна покупка = сотні компаній); низькі комісії (0.03–0.5% на рік проти 1–3% у активних фондах); простота; ліквідність (можна продати в будь-який момент).</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Пасивне vs активне управління</b> — більшість активно керованих фондів не перевершують індекс на довгому горизонті після врахування комісій (дані SPIVA S&P Global). ETF копіює індекс, не намагаючись його перевершити.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Популярні ETF</b> — VOO, IVV, SPY — відстежують S&P 500; VTI — весь ринок США; VWRA — глобальний ринок. Доступні через міжнародних брокерів.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Стратегія DCA</b> — Dollar Cost Averaging: регулярні покупки ETF на фіксовану суму незалежно від ціни. Знижує вплив ринкових коливань і знімає необхідність «вгадувати» вдалий момент.</span></div><div class=\"final-note\">ETF — рекомендований інструмент для початківців: широка диверсифікація, мінімальні комісії, простота.</div>"],
        [2056,"Складний відсоток: як час множить капітал","<div class=\"rule-note\">Складний відсоток — нарахування відсотків не лише на основну суму, але й на вже нараховані відсотки. Альберт Ейнштейн (хоча достовірність цитати оспорюється) нібито назвав його «восьмим дивом світу».</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Як працює</b> — 100 000 грн під 10% на рік: після 1-го року → 110 000, після 2-го → 121 000 (не 120 000!), після 10-го → ~259 000. Без реінвестування — лише 200 000.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Правило 72</b> — кількість років, за які капітал подвоїться: 72 ÷ річна прибутковість (%). При 8% — ~9 років. При 10% — ~7 років. Зручне наближення для швидкої оцінки.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Значення часу</b> — інвестиція 10 000 грн у 25 років при 8% річних дає ~100 000 грн у 55 років. Та сама інвестиція у 35 років дає ~46 000 грн у 55 років. 10 років різниці — майже втричі менший результат.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Реінвестування дивідендів</b> — ключ до складного відсотка в акціях: дивіденди слід реінвестувати (купувати додаткові акції), а не витрачати. Багато ETF роблять це автоматично (accumulating ETF).</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Комісії — антискладний відсоток</b> — комісія 2% на рік замість 0.1% за 30 років знищує значну частину прибутку. Вибирайте низькокомісійні інструменти для довгострокового інвестування.</span></div><div class=\"final-note\">Час — найцінніший ресурс інвестора. Почати рано важливіше, ніж почати «правильно».</div>"],
        [2057,"Ризик і прибутковість: золоте правило інвестицій","<div class=\"rule-note\">Вища очікувана прибутковість завжди супроводжується вищим ризиком. Це фундаментальне правило фінансів: «безризикової»高прибутковості не існує — це ознака шахрайства.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Шкала ризику</b> — від нижчого до вищого: готівка → державні облігації → корпоративні облігації → нерухомість → акції великих компаній → акції малих компаній → криптовалюта. Прибутковість, як правило, зростає в тому ж напрямку.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Волатильність як міра ризику</b> — стандартне відхилення прибутковості. Акції S&P 500 впадали більш ніж на 50% (2008–2009) і відновлювалися. Якщо ви не можете витримати такий спад психологічно — знизьте частку акцій.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Ризик-профіль інвестора</b> — залежить від: горизонту (чим довший — тим більше акцій), терпимості до коливань, наявності подушки безпеки, конкретних цілей. Молодший інвестор зазвичай може дозволити більший ризик.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>«Гарантована» висока прибутковість — шахрайство</b> — якщо хтось пропонує 50–100% на рік без ризику — це ознака фінансової піраміди або шахрайства. Ринкова прибутковість акцій у середньому ~7–10% реально за тривалий горизонт.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Диверсифікація знижує несистемний ризик</b> — ризик окремої компанії можна усунути диверсифікацією. Системний ризик (ринок загалом падає) усунути не можна — лише прийняти і зменшити через облігації.</span></div><div class=\"final-note\">Ризик не варто уникати — ним треба управляти. Розуміння ризику відрізняє інвестора від гравця.</div>"],
        [2058,"Нерухомість як інвестиція: переваги та обмеження","<div class=\"rule-note\">Нерухомість — один із традиційних інвестиційних активів. В Україні традиційно вважається надійним вкладенням, але має суттєві обмеження порівняно з фінансовими інструментами.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Переваги</b> — фізичний актив (психологічна надійність); захист від інфляції у довгостроковій перспективі; орендний дохід як пасивний грошовий потік; кредитне плече (іпотека) збільшує потенційну прибутковість.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Недоліки</b> — низька ліквідність (продаж займає місяці); висока точка входу; операційні витрати (ремонт, комунальні, податки, простій); потребує управління (або оплати керуючого).</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Дохідність оренди</b> — валова орендна дохідність: (орендна плата за рік) ÷ (вартість нерухомості) × 100%. В Україні, як правило, 5–10% валової дохідності. Чиста — після витрат — помітно нижча.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Іпотека: кредитне плече</b> — купуєте квартиру за 1 млн грн (200 тис. своїх + 800 тис. кредит). Якщо вартість зросла на 10% → 100 тис. грн приросту на вкладені 200 тис. = 50% прибутку. Але і ризик збитків збільшується.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Альтернатива — REIT</b> — Real Estate Investment Trust: фонди, що інвестують у нерухомість і торгуються на біржі. Дають доступ до ринку нерухомості без необхідності купувати об'єкт. В Україні поки не розвинені, доступні через міжнародних брокерів.</span></div><div class=\"final-note\">Нерухомість — хороший актив при правильній ціні і горизонті. Не панацея і не єдиний спосіб вкласти гроші.</div>"],
        [2059,"Пенсійні накопичення: чому починати рано","<div class=\"rule-note\">Державна пенсія в Україні, як правило, забезпечує лише мінімальний рівень доходу. Самостійні пенсійні накопичення — необхідність для збереження звичного рівня життя у похилому віці.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Демографічна проблема</b> — система солідарності (нинішні працівники платять нинішнім пенсіонерам) стає дедалі напруженішою через старіння населення. Покладатися лише на державну пенсію — ризик.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Сила раннього старту</b> — 25-річний, що відкладає 2000 грн/міс під 8% річних до 65 років, накопичить набагато більше, ніж 35-річний із тією самою сумою та ставкою. 10 зайвих років дають кратну перевагу завдяки складному відсотку.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Недержавні пенсійні фонди (НПФ)</b> — в Україні існують НПФ: добровільні внески, пільгове оподаткування. Перед вибором НПФ — перевіряйте ліцензію НКЦПФР, стаж роботи, дохідність і комісії фонду.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Самостійне інвестування</b> — альтернатива НПФ: регулярні інвестиції в диверсифікований портфель ETF через брокера. Більший контроль, потребує фінансової грамотності.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Скільки відкладати</b> — загальна рекомендація — 10–15% доходу на пенсійні цілі. Якщо починаєте пізно — більше. Навіть невелика регулярна сума краща за нуль.</span></div><div class=\"final-note\">Найкращий час почати пенсійні накопичення — 20 років тому. Другий найкращий — сьогодні.</div>"],
        [2060,"Фінансові пастки: кредитні картки, лізинг, МФО","<div class=\"rule-note\">Деякі фінансові продукти розроблені з урахуванням психологічних слабкостей споживача. Знання механізмів — захист від переплат і боргових пасток.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Кредитна картка</b> — зручна за дисципліни, руйнівна без неї. Пільговий період (grace period) — зазвичай 30–62 дні без відсотків. Після — відсоткова ставка, як правило, 30–60% річних. Мінімальний платіж розтягує борг на роки.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Лізинг авто</b> — ви платите за користування, а не за власність. Часто здається дешевшим за кредит через нижчий щомісячний платіж, але в сумі переплата може бути більшою. Порівнюйте повну вартість, а не місячний платіж.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>МФО (мікрофінансові організації)</b> — «позика до зарплати» з річною ставкою, що може становити 300–700% і більше. Навіть невеликий борг швидко стає неподъемним. Уникайте за будь-якої можливості.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>BNPL (Buy Now Pay Later)</b> — «купи зараз, плати потім»: розстрочка на покупки. Може бути безвідсотковою при дотриманні умов. Провокує імпульсивні покупки і заборгованість, якщо не контролювати.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Правило для кредитів</b> — беріть кредит лише на актив, що зростає в ціні (нерухомість) або підвищує дохід (освіта, бізнес). Споживчий кредит на телевізор чи телефон — дорогий спосіб прожити не за коштами.</span></div><div class=\"final-note\">Борг — це витрати майбутнього доходу сьогодні. Іноді виправданий, часто — пастка.</div>"],
        [2061,"Перші кроки інвестора: покроковий старт","<div class=\"rule-note\">Почати інвестувати здається складним через надлишок інформації. Насправді перші кроки — прості й доступні. Головне — почати з фундаменту, а не з «гарячих акцій».</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Крок 1: Закрийте дорогі борги</b> — перш ніж інвестувати, погасіть борги зі ставкою вище ~10–12% (кредитні картки, МФО). Гарантована «прибутковість» від закриття боргу вища за очікувану від інвестицій.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Крок 2: Сформуйте подушку безпеки</b> — 3–6 місяців витрат на накопичувальному рахунку. Лише після цього починайте довгострокове інвестування.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Крок 3: Визначте мету і горизонт</b> — на що інвестуєте (пенсія, квартира, освіта дитини)? Через скільки років потрібні кошти? Від цього залежить вибір інструментів і допустимий ризик.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Крок 4: Відкрийте рахунок у брокера</b> — для старту не потрібні великі суми. Оберіть ліцензованого брокера, вивчіть умови (комісії, мінімальна сума). Почніть із малих регулярних інвестицій у диверсифікований ETF.</span></div><div class=\"step c5\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Крок 5: Навчайтеся поступово</b> — базові книги: «Розумний інвестор» (Бенджамін Грем), «Маленька книга здорового глузду в інвестуванні» (Джон Богл). Не купуйте «гарячі поради» без розуміння.</span></div><div class=\"final-note\">Інвестування — це марафон, не спринт. Регулярність і дисципліна важливіші за вибір «правильного» моменту.</div>"]
      ]
    },
    {
      n: "Блок 8: Автомобільна грамотність",
      e: "Automotive Literacy",
      cards: [
        [2062,"Вибір автомобіля: на що звертати увагу","<div class=\"rule-note\">Вибір автомобіля — одне з найбільших фінансових рішень після нерухомості. Правильний підхід: потреби → бюджет (повний, не лише ціна) → перевірка конкретного автомобіля.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Визначте реальні потреби</b> — місто чи траса? Скільки пасажирів? Паркінг? Дорожні умови? Частота поїздок? Відповіді формують тип кузова і привід. Не купуйте позашляховик для міста «на всяк випадок».</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Повний бюджет</b> — до ціни авто додайте: страховка (ОСЦПВ + КАСКО за бажанням), техобслуговування, паливо, парковка, дорожній збір, можливий кредит з відсотками. Нерідко ТО і паливо за рік перевищують 20% вартості авто.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Новий vs уживаний</b> — новий: гарантія, відома історія, вища ціна, швидше знецінення (перші 1–3 роки — найбільший спад). Уживаний: нижча ціна, потребує перевірки. Оптимальний вік уживаного — як правило 3–5 років.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Перевірка уживаного</b> — VIN-перевірка (Carfax, AutoRia, mvsu.gov.ua): ДТП, пробіг, заставу, угон. Незалежна діагностика на СТО за вашим вибором (не продавця). Перевірка документів (свідоцтво, сервісна книжка).</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Знецінення (депресіація)</b> — нове авто втрачає приблизно 15–25% вартості у перший рік, ще 10–15% щороку далі (залежно від марки). Купити авто 2–3 роки — отримати більшу частину втрат знецінення за рахунок першого власника.</span></div><div class=\"final-note\">Найдорожчий автомобіль — той, що не підходить під ваші потреби або вимагає дорогого обслуговування.</div>"],
        [2063,"Технічне обслуговування: що і коли","<div class=\"rule-note\">Регулярне ТО — профілактика дорогих поломок. Більшість серйозних несправностей починаються як дрібні проблеми, що ігнорувалися. Сервісна книжка і регламент виробника — ваш орієнтир.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Мастило (моторне масло)</b> — найважливіший витратний матеріал. Регламент заміни: за рекомендацією виробника (як правило 10–15 тис. км або 1 рік). Перевіряйте рівень щомісяця: щуп між мітками MIN і MAX. Колір: темний — нормально, з блиском металу — тривога.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Технічні рідини</b> — гальмівна рідина: заміна кожні 2 роки (вбирає вологу, знижує температуру кипіння). Охолоджувальна рідина (антифриз): заміна за регламентом виробника. Рідина ГПК (гідропідсилювач керма): перевіряйте рівень. Омивач — використовуйте незамерзайку зимою.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Гальма</b> — гальмівні колодки: залишок накладки менше 3 мм — заміна. Ознаки зношення: скрип, вібрація при гальмуванні, збільшений гальмівний шлях. Гальмівні диски: перевіряйте товщину, за наявності борозен — заміна або проточка.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Шини і колеса</b> — протектор: мінімум 1.6 мм (законна норма), рекомендовано 3+ мм. Тиск: перевіряйте раз на місяць і при зміні температури (кожні 10°С — зміна тиску ~0.1 бар). Балансування і розвал-сходження — після заміни шин і за ознаками нерівного зносу.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Акумулятор і електрика</b> — акумулятор: середній строк служби 3–5 років. Ознаки: повільний запуск, просідання напруги. Перевірка: мультиметр або на СТО. Запалення і свічки: заміна за регламентом. Паси (ГРМ, генератора): критично важливо замінювати вчасно — обрив ГРМ може знищити двигун.</span></div><div class=\"final-note\">ТО за регламентом коштує у 5–10 разів менше, ніж ремонт через ігнорування регламенту.</div>"],
        [2064,"Шини: вибір, зберігання, сезонна заміна","<div class=\"rule-note\">Шини — єдина точка контакту автомобіля з дорогою. Їхній стан напряму впливає на безпеку. Правильний вибір і своєчасна заміна — не економія, а захист.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Маркування шин</b> — приклад: 205/55 R16 91H. 205 — ширина профілю (мм), 55 — відношення висоти до ширини (%), R16 — діаметр диска (дюйми), 91 — індекс навантаження (615 кг), H — індекс швидкості (до 210 км/год).</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Сезонна заміна</b> — зимові шини: при стабільній температурі нижче +7°С (гума твердне, зчеплення падає). Орієнтир для України: жовтень–листопад і березень–квітень. Всесезонні — компроміс, не замінюють спеціалізовані шини в екстремальних умовах.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Перевірка зносу</b> — індикатори зносу: виступи на дні канавок протектора (1.6 мм). Монета-тест: монета 1 грн в канавку — якщо тризуб повністю видно, залишок протектора критичний. Нерівний знос — ознака проблем з тиском або підвіскою.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Зберігання шин</b> — без дисків: вертикально (кожні місяць-два перевертати). З дисками: горизонтально стопкою або підвішено. Прохолодне, темне, сухе місце. Не поруч з хімікатами і джерелами тепла/озону.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Вік шин</b> — незалежно від зносу: шини старше 6–10 років (навіть з гарним протектором) рекомендується замінювати — гума деградує. Дату виробництва: 4 цифри в колі на боковині (тиждень і рік, наприклад 2423 = 24-й тиждень 2023 р.).</span></div><div class=\"final-note\">Гарні шини — найдешевша страховка від аварії. Не економте на безпеці в точках контакту.</div>"],
        [2065,"Як читати попереджувальні індикатори на панелі приладів","<div class=\"rule-note\">Сучасний автомобіль має десятки контрольних ламп. Знання ключових — різниця між «заїхати на СТО» і «зупинитись негайно».</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Критичні (червоні) — зупинитись</b> — масло (масляничка): тиск масла критичний, зупиніться і заглушіть двигун. Температура двигуна (термометр): перегрів, негайна зупинка. Акумулятор: немає зарядки, їдьте на найближчу СТО. Гальма (BRAKE): перевірте рівень гальмівної рідини.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Попереджувальні (жовті/помаранчеві) — заплануйте СТО</b> — Check Engine (двигун з ключем): несправність системи двигуна — потрібна діагностика. Тиск у шинах (TPMS): один або кілька шин потребують перевірки тиску. ABS: несправність антиблокувальної системи — гальма працюють, ABS — ні.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Airbag, ESP, рівень пального</b> — подушки безпеки: несправність системи — потенційно небезпечно. ESP/VSC: нестабільність системи курсової стійкості. Пальне: резерв ~50 км ходу (залежить від авто і стилю їзди).</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Як дізнатись що означає невідома лампа</b> — мануал (посібник користувача) — основне джерело. OBD2-сканер і додаток (Torque, Car Scanner): зчитує коди помилок. Пошук за маркою і символом у Google. Деякі автосалони і магазини запчастин роблять безкоштовне зчитування кодів.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Правило для червоних ламп</b> — ніколи не ігноруйте. Продовження їзди з критичним попередженням може перетворити дрібну проблему на капітальний ремонт або аварію.</span></div><div class=\"final-note\">Прочитайте розділ контрольних ламп у посібнику свого авто. 20 хвилин читання можуть заощадити тисячі гривень.</div>"],
        [2066,"Поведінка у разі поломки на дорозі","<div class=\"rule-note\">Поломка або ДТП на дорозі — стресова ситуація. Правильний алгоритм дій, виконаний заздалегідь відпрацьований, мінімізує ризики і прискорює вирішення.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Перший крок — безпека</b> — увімкніть аварійні вогні негайно. Відведіть авто з проїжджої частини (якщо можливо). Виставте аварійний трикутник: у населеному пункті — 20 м позаду, поза — 40 м мінімум (Правила дорожнього руху України).</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Прокол шини на ходу</b> — утримуйте кермо двома руками, не гальмуйте різко. Плавно знижуйте швидкість, відпустивши газ. Перестрайтеся в крайній правий ряд, зупиніться на узбіччі. Не виходьте на дорогу — лише за відбійник або якнайдалі від проїзної частини.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Перегрів двигуна</b> — відразу вимкніть кондиціонер і увімкніть обігрів (він допомагає відводити тепло). Зупиніться, заглушіть двигун, дайте охолонути 15–20 хвилин. Не відкривайте кришку радіатора гарячого — ризик ошпаритись. Дочекайтесь охолодження, перевірте рівень антифризу.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Розряджений акумулятор</b> — «прикурювання» від іншого авто: червоний провід до + розрядженого, потім до + донора; чорний провід до - донора, потім до заземлення (-) або кузова розрядженого (не до -). Запустіть донора, через 5 хвилин — ваше авто.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Мінімальний набір у авто</b> — аварійний трикутник (обов'язково за ПДД), вогнегасник порошковий (1 кг мінімум), аптечка, жилет сигнальний, буксировочний трос, кабелі для прикурювання, насос або компресор, запасне колесо або рідкий герметик.</span></div><div class=\"final-note\">Відпрацюйте алгоритм заздалегідь. У стресі люди роблять те, що відпрацьовано — не те, що логічно.</div>"],
        [2067,"Зимове водіння: безпека в складних умовах","<div class=\"rule-note\">Зимові умови (сніг, лід, туман) збільшують гальмівний шлях у 2–10 разів порівняно з сухим асфальтом. Безпечна зимова їзда — це інший стиль, не лише інші шини.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Гальмівний шлях на льоду</b> — при 50 км/год на сухому асфальті — близько 14 м. На мокрому — 20 м. На льоду — 60–80 м і більше. Збільшуйте дистанцію відповідно: зимою вона має бути втричі більша, ніж влітку.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Технічна підготовка до зими</b> — встановіть зимові шини до перших морозів. Перевірте акумулятор (холод знижує ємність). Замініть омивач на незамерзайку. Перевірте рівень антифризу і його робочу температуру. Щітки склоочисника — зимові або замініть гумки.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Занос і що робити</b> — занос задньої осі: повертайте кермо у бік заносу, газ не відпускайте різко. Занос передньої осі (збереження курсу): послабте газ, не збільшуйте кут повороту. З ABS: гальмуйте натиском (система сама дозує). Без ABS: переривчасте гальмування.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Рух по снігу та льоду</b> — рушайте плавно, без пробуксовки. Гальмуйте завчасно — поступово. Знижуйте швидкість перед поворотами, а не в них. Тримайте колеса прямо при гальмуванні на слизькій поверхні (ABS допомагає рулювати під час гальмування).</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Аварійний набір взимку</b> — лопата складна, мотузка для буксирування, теплий плед, ліхтарик, пляшка з піском або кошик для зчеплення, скребок і щітка для снігу. Телефон завжди заряджений.</span></div><div class=\"final-note\">Зимова їзда вимагає не лише кращих шин, а й іншої психології: більше часу, менша швидкість, більша дистанція.</div>"],
        [2068,"Паливо та паливна система: базові знання","<div class=\"rule-note\">Правильне паливо і розуміння паливної системи зберігають двигун і заощаджують кошти. Більшість проблем виникає через використання неправильного палива або забрудненої системи.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Марки бензину</b> — октанове число (А-92, А-95, А-98) — стійкість до детонації. Використовуйте марку, що вказана у мануалі авто. Нижчий октан може спричинити детонацію (стукіт пальців), вищий — зайвий витрата грошей без вигоди (якщо двигун не розрахований).</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Дизель vs бензин vs газ (ГБО)</b> — дизель: кращий на трасі, вищий крутний момент, складніший ремонт. Бензин: універсальний, простіший у обслуговуванні. ГБО (пропан-бутан або метан): дешевше паливо, витрати на установку, зниження потужності ~5–10%, потребує технічного огляду.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Як зменшити витрату пального</b> — рівномірний стиль їзди (без різких газу і гальмування). Підтримуйте правильний тиск у шинах (недокачані шини збільшують опір кочення). Плановий ТО (забитий повітряний фільтр — +10–15% витрати). Не прогрівайте авто довго на холостих — сучасним двигунам достатньо 30–60 сек.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Паливні фільтри</b> — забруднений паливний фільтр знижує тиск у паливній системі → падіння потужності, нестабільна робота. Заміна: за регламентом виробника (як правило 20–40 тис. км для бензину, частіше для дизелю).</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Якість пального і заправки</b> — заправляйтесь на перевірених мережевих АЗС. Погане паливо — забруднення форсунок, детонація, засмічення фільтра. При підозрі на паливо: зверніться до СТО або використайте присадки-детергенти (обережно — лише перевірені).</span></div><div class=\"final-note\">Розрахунок витрати: літри заправленого ÷ пройдені км × 100 = л/100 км. Відстежуйте динаміку — зростання витрати без причин сигналізує про несправність.</div>"],
        [2069,"Страхування автомобіля: ОСЦПВ, КАСКО та їх відмінності","<div class=\"rule-note\">Автострахування в Україні: ОСЦПВ — обов'язкове (відповідальність перед іншими), КАСКО — добровільне (захист власного авто). Розуміння різниці — захист від несподіваних витрат.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>ОСЦПВ (обов'язкове)</b> — покриває збитки, завдані іншим учасникам ДТП з вашої вини: майно до 160 000 грн (ліміти встановлюються законодавством і можуть змінюватися), здоров'я до 320 000 грн на момент написання. Не відшкодовує ваші власні збитки.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>КАСКО (добровільне)</b> — захищає ваш автомобіль: ДТП з вашої вини, крадіжка, пожежа, стихійні лиха, пошкодження паркінгу. Вартість: як правило 2–10% вартості авто на рік залежно від умов, стажу водія, типу авто.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Коли КАСКО виправдане</b> — нова або дорога машина; авто у кредиті (банки зазвичай вимагають). Для старого або дешевого авто — витрати на КАСКО можуть перевищувати потенційний збиток, краще самострахування.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Дії після ДТП</b> — зупиніться, увімкніть аварійні вогні. Виклично поліцію (102) — потрібен протокол для страхової. Обміняйтесь даними: страховий поліс, ПІБ, контакти. Європротокол: можна без поліції при взаємній згоді і відсутності поранених, збитки до законодавчого ліміту.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Як знизити вартість страховки</b> — порівнюйте пропозиції (агрегатори: Polis.ua, Insurans.ua). Вищий франшиз знижує премію. Встановлення трекера (телематика). Безаварійний стаж — знижки від страховиків.</span></div><div class=\"final-note\">Перевіряйте актуальні ліміти ОСЦПВ в законодавстві — вони змінювались і можуть змінитися. КАСКО — порівнюйте умови, а не лише ціну.</div>"],
        [2070,"Права водія та ПДД: ключові ситуації","<div class=\"rule-note\">Знання Правил дорожнього руху і своїх прав — основа безпечного і законного водіння. Незнання закону не звільняє від відповідальності.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Пріоритет на перехресті</b> — головна vs другорядна: перевага у того, хто на головній. Перешкода праворуч: за відсутності знаків — поступіться тому, хто праворуч (правило «правої руки»). Кругова: в Україні з 2019 р. — ті, що на кільці, мають перевагу (якщо немає протилежного знаку).</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Перевищення швидкості: штрафи</b> — перевищення на 1–20 км/год: попередження або штраф. На 20–50 км/год: штраф, позбавлення прав. На 50+ км/год: позбавлення прав до 1 року. Перевіряйте актуальні розміри штрафів у КУпАП — вони змінюються.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Алкоголь і водіння</b> — в Україні: допустимий рівень алкоголю 0.2 проміле у крові (або 0.1 мг/л у повітрі). Перевищення — позбавлення прав і штраф. Повторне — кримінальна відповідальність. Навіть «одна пляшка пива» може призвести до перевищення залежно від ваги та обміну речовин.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Права водія при перевірці ДАІ/поліції</b> — маєте право: знати підставу зупинки, вимагати посвідчення службовця, не виходити з авто без законних підстав, фіксувати взаємодію на відео. Зобов'язані: надати документи (ВУ, свідоцтво, поліс ОСЦПВ).</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Мобільний телефон за кермом</b> — заборонено тримати телефон під час руху. Дозволено: лише з гарнітурою hands-free або вбудованою системою авто. Штраф і прецеденти — один з найчастіших порушень, ризик ДТП зростає в 4 рази.</span></div><div class=\"final-note\">ПДД — не набір правил «для поліції». Це система, яка рятує життя тоді, коли всі її дотримуються.</div>"],
        [2071,"Еко-водіння: як зменшити витрату пального","<div class=\"rule-note\">Еко-водіння (Eco-driving) — стиль їзди, що мінімізує витрату пального і знос авто без втрати часу в дорозі. За даними Євро-6 і досліджень, може знизити витрату на 15–25%.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Прискорення і гальмування</b> — різкий старт і різке гальмування — головні «пожирачі» пального. Плавне прискорення: двигун утримуйте в зоні ефективного крутного моменту. Завчасне відпускання газу перед зупинкою — режим рекуперації (мотор-гальмо без витрати палива).</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Передача і оберти</b> — переходьте на вищу передачу раніше. Оптимальні оберти: як правило 1500–2500 об/хв для бензину (для дизелю трохи нижче). Висока передача на низьких обертах ефективніша, ніж низька передача на середніх.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Крейсерська швидкість</b> — оптимальна для більшості авто — 80–100 км/год. При 120 км/год аеродинамічний опір зростає в ~2.3 рази порівняно з 80 км/год. Круїз-контроль на трасі економить паливо і знижує стрес.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Технічний стан і навантаження</b> — правильний тиск в шинах: кожні 0.3 бар нижче норми → +1–2% витрати. Знімайте багажник і велосипедний тримач коли не потрібні — аеродинамічний опір. Кондиціонер: +5–15% витрати. Вимикайте у місті при можливості.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Планування маршруту</b> — уникайте годин-пік (стоп-старт у пробці — найбільша витрата). Об'єднуйте поїздки. Навігатор з даними трафіку — Waze, Google Maps. Їзда «з попутним вітром» на трасі — різниця в витраті помітна.</span></div><div class=\"final-note\">Еко-водіння — не «їхати повільно». Це їхати розумно: плавно, завчасно, ефективно.</div>"],
        [2072,"Паркування: правила, типи і маневрування","<div class=\"rule-note\">Паркування — частина міської їзди, що викликає найбільше труднощів у початківців і непорозумінь щодо ПДД. Знання правил і техніки маневрування знижують стрес і штрафи.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Де заборонено паркуватись</b> — зупинки громадського транспорту (15 м до і після). Пішохідні переходи і 10 м до них. Виїзди з дворів і гаражів. Тротуар (крім місць, де є знак 5.38). Перехрестя і поблизу (10–20 м залежно від типу). Місця для людей з інвалідністю без відповідного знаку.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Паркування задом (паралельне)</b> — підготовка: стати поруч з авто попереду (60 см збоку). Задній хід: повернути кермо вправо до 45° → виїхати 1–2 метри → кермо вліво → вирівнятись. Відстань між бамперами: 20–30 см — норма.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Паркування у бокс (перпендикулярне)</b> — підготовка: зрівнятись із стовпом або краєм місця, відступити на довжину авто. Задній хід з поворотом. Правило: кут заїзду визначається заздалегідь. Використовуйте всі дзеркала + камеру заднього виду.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Паркомати і платні парковки</b> — переконайтесь у зоні дії і часі. Паркомат: введіть номер авто, зону, час. Паркувальні застосунки (EasyPark, Parkly, міські додатки) — зручніше і нагадують про закінчення часу.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Евакуатор і штрафи</b> — авто евакуюють за порушення паркування. Забрати: зателефонувати до комунальних служб міста → оплатити штраф і послуги евакуатора → отримати авто. Штраф за порушення + вартість евакуації — суттєва сума.</span></div><div class=\"final-note\">Навчіться паркуватись задом — це базова навичка, яка не залежить від досвіду. Лише практика.</div>"],
        [2073,"Перша допомога при ДТП","<div class=\"rule-note\">Перші хвилини після ДТП критичні. Правильні дії свідків і учасників можуть врятувати життя. Знання базових дій — громадянський обов'язок водія.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Перший крок — безпека місця</b> — увімкніть аварійні вогні. Виставте трикутник (20 м у місті, 40 м поза). Не підходьте до авто, що може загорітись або впасти. Виклично 103 (медична), 101 (пожежна), 102 (поліція).</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Перевірка потерпілого</b> — перевірте свідомість: «Як вас звати? Мене чуєте?». Дихання: нахиліться, послухайте і подивіться на грудну клітку (10 сек). Якщо без свідомості і не дихає — починайте СЛР. Якщо дихає — стабільне бокове положення.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Серцево-легенева реанімація (СЛР)</b> — 30 натискань на грудину (частота ~100–120 за хвилину, глибина ~5 см) + 2 вдихи «рот в рот» (або лише компресії — теж ефективно). Продовжуйте до приїзду медиків або відновлення дихання.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Кровотеча</b> — сильна артеріальна: накладіть джгут вище рани (є в аптечці), запишіть час накладення. Венозна: тисніть чистою тканиною, не відпускайте. Не виймайте предмети, що застрягли у рані.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Коли НЕ рухати потерпілого</b> — підозра на травму хребта (ДТП, падіння з висоти): не рухайте без потреби. Виняток: загроза пожежі або відсутність дихання — тоді рух виправданий.</span></div><div class=\"final-note\">Пройдіть курс першої допомоги (Червоний Хрест, місцеві організації). 4 години навчання — навичка на все життя.</div>"],
        [2074,"Купівля та продаж автомобіля: юридичні аспекти","<div class=\"rule-note\">Оформлення купівлі-продажу автомобіля — юридично значима дія. Помилки тут коштують часу, грошей або навіть автомобіля. Знайте процедуру або залучіть фахівця.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Перевірка перед покупкою</b> — VIN-код перевірте на порталі mvsu.gov.ua (угон, обмеження), на AutoRia або Carvertical (зарубіжна історія). Перевірте власника: чи збігається ПІБ у документах. Несплачені штрафи і податки — реєстрацію можуть заблокувати.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Договір купівлі-продажу</b> — укладається у формі нотаріально посвідченого договору або у формі дозволеного спрощеного порядку (ТСЦ МВС). Перевірте всі дані: VIN, номер кузова, реєстраційний номер, ПІБ сторін, ціна.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Перереєстрація (постановка на облік)</b> — покупець зобов'язаний перереєструвати авто на своє ім'я протягом 10 діб після укладання договору. Звернення до сервісного центру МВС. Необхідні документи: договір, паспорт, ІПН, страховий поліс ОСЦПВ.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Оподаткування</b> — продавець при продажу авто сплачує ПДФО 5% і військовий збір 1.5% (5% з 2024) від суми договору, якщо авто у власності менш ніж рік або це другий продаж за рік. Перший продаж на рік за авто у власності понад рік — звільняється (уточнюйте актуальний закон).</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Генеральна довіреність — ризик</b> — продаж «за дорвіреністю» без переоформлення: юридично продавець залишається власником, платить транспортний збір, несе відповідальність за ДТП власника. Уникайте цієї схеми як покупець.</span></div><div class=\"final-note\">Перевіряйте авто до грошей. Перевіряйте документи до підпису. Переоформлюйте відразу.</div>"],
        [2075,"Електромобілі та гібриди: базові знання","<div class=\"rule-note\">Електромобілі (EV) і гібриди (HEV/PHEV) стають дедалі поширенішими. Розуміння їхніх особливостей допомагає у виборі і правильній експлуатації.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Типи</b> — BEV (повністю електричний): лише акумулятор + електромотор (Tesla, Nissan Leaf). HEV (повний гібрид): двигун + акумулятор, заряджається під час руху (Toyota Prius). PHEV (підключний гібрид): ДВЗ + акумулятор, що заряджається від мережі. MHEV (м'який гібрид): допомагає ДВЗ, не їде самостійно.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Запас ходу EV</b> — реальний запас як правило 20–30% менший за офіційний WLTP: холод (акумулятор гірше працює), висока швидкість, кондиціонер/обігрів споживають значну частину ємності. Плануйте маршрути заздалегідь з урахуванням зарядок.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Зарядка</b> — рівень 1 (220В): повільна, 8–20 год. Рівень 2 (спеціальна зарядна станція): 2–8 год. DC Fast Charging: 20–60 хв до 80%. Оптимально заряджати акумулятор у межах 20–80% для продовження строку служби (рекомендація більшості виробників).</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Обслуговування EV</b> — двигун: практично не потребує ТО (немає масла, свічок, ременів). Менше теплових навантажень на гальма (рекуперативне гальмування). Акумулятор: як правило гарантія 8 років або 160 000 км. Шини зношуються швидше через більшу вагу.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Переваги та обмеження</b> — переваги: нижчі витрати на паливо і ТО, екологічність. Обмеження: вища початкова ціна, залежність від зарядної інфраструктури, менший запас ходу взимку. Для міських поїздок до 50–80 км/день — EV може бути практичним і економічним.</span></div><div class=\"final-note\">EV і гібриди — не «майбутнє», а «сьогодення» для багатьох водіїв. Оцінюйте під конкретний стиль використання.</div>"],
        [2076,"Базові навички самостійного обслуговування авто","<div class=\"rule-note\">Деякі операції з ТО автомобіля нескладно виконати самостійно. Це заощаджує час і гроші, а також дає розуміння стану авто. Але без знань і досвіду — краще до СТО.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Перевірка рівнів рідин</b> — моторне масло (щуп між MIN і MAX), охолоджуюча рідина (мітки на бачку), гальмівна рідина (мітки на бачку), рідина ГПК, омивач. Перевіряйте на холодному двигуні (крім омивача). Щомісяця або перед довгою поїздкою.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Заміна повітряного фільтра</b> — повітряний фільтр двигуна: зазвичай у пластиковому корпусі під капотом, кріплення — затискачі або болти. Виймається, оглядається (брудний або порваний — замінити), встановлюється новий. Вартість фільтра — 100–400 грн, заміна займає 5–15 хв.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Заміна щіток склоочисника</b> — існують різні типи кріплення (гачок, штифт тощо) — перевірте посібник або відео для вашої моделі. Зазвичай: підняти важіль, натиснути кнопку фіксатора, зняти стару щітку, встановити нову до клацання. Перевірте правильність встановлення — щітка не має впасти на скло.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Підкачати шини</b> — рекомендований тиск — на наклейці в дверному прорізі водія або в мануалі. Вимірювання — холодні шини (не відразу після їзди). Компресор або АЗС з манометром. Тиск передніх і задніх шин може відрізнятись.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Коли НЕ робити самостійно</b> — гальмова система (колодки, диски, циліндри), підвіска (важелі, кульові опори), електропроводка, паливна система, кермовий механізм. Помилка в цих системах → небезпека для вас і оточуючих. Довіряйте лише перевіреним СТО.</span></div><div class=\"final-note\">Навчіться читати мануал свого авто — там є все для базового самообслуговування. Це інвестиція у розуміння свого транспортного засобу.</div>"]
      ]
    },
    {
      n: "Блок 9: Екологія та сталий розвиток у побуті",
      e: "Ecology & Sustainability",
      cards: [
        [2109,"Сортування відходів: що і куди","<div class=\"rule-note\">Роздільний збір відходів — основа побутової екології. В Україні інфраструктура переробки розвинена нерівномірно: перш ніж сортувати, варто знати, що приймають у твоєму місті.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Основні фракції</b> — Папір/картон: суха упаковка, газети, книги (без ламінату); Пластик: пляшки ПЕТ (#1), тверда упаковка (дивись маркування ♻ і цифру); Скло: пляшки, банки (без кришок і металевих частин); Метал: бляшані консерви, алюмінієві банки. Органіка: їжа, рослини — у компост або баки органіки.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Що НЕ йде у звичайний контейнер</b> — Небезпечні відходи: батарейки, акумулятори, люмінесцентні лампи, ліки, хімікати — здавай у спеціальні пункти прийому (є у гіпермаркетах, аптеках, сервісних центрах). Змішана і брудна упаковка — зазвичай не переробляється.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Як дізнатись про пункти прийому</b> — сайт Zero Waste Lviv (є загальний довідник), ecomap.com.ua, сторінки місцевих ОСББ і міськради. Телефонуй до ЖЕКу або КП з питань благоустрою — вони зобов’язані надати інформацію.</div></div><div class=\"final-note\">Перш ніж викинути — помий і висуши. Брудна упаковка часто відправляється на звалище навіть з контейнера для переробки. Мінімальна підготовка подвоює шанс реальної переробки.</div>"],
        [2110,"Енергоефективність вдома: прості кроки","<div class=\"rule-note\">Скорочення енергоспоживання вдома — і фінансова, і екологічна вигода. Більшість простих заходів не потребує інвестицій.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Освітлення</b> — LED-лампи споживають приблизно в 7–10 разів менше за лампи розжарювання і служать значно довше. Вимикай світло, виходячи з кімнати. Використовуй природне освітлення максимально — переставляй меблі від вікон.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Побутова техніка</b> — режим очікування (standby) споживає електрику постійно. Вимикай зарядні пристрої і техніку з розетки, коли не використовуєш. Прання при 30–40°C замість 60°C дає суттєву економію без втрати якості для більшості речей.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Опалення і охолодження</b> — ущільнення вікон і дверей (ущільнювач, утеплення відкосів) знижує тепловтрати взимку. Термостат на 1°C нижче — помітна економія за сезон. Не перекривай батареї меблями і шторами — тепло не розподіляється рівномірно.</div></div><div class=\"final-note\">Лічильники на воду, газ, тепло — необхідні для реального контролю споживання. Без лічильника платиш за норматив, який часто вищий за реальне споживання.</div>"],
        [2111,"Водозбереження у побуті","<div class=\"rule-note\">Прісна вода — обмежений ресурс. Більшість домашніх заходів зі збереження води не потребують зусиль і помітно знижують рахунки.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Щоденні звички</b> — Душ замість ванни витрачає менше води (якщо душ не довший за 5–7 хвилин). Закривай кран під час чищення зубів і нанесення мила. Повне завантаження посудомийки і пральної машини — ефективніше за часткове навіть з режимом «економ».</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Технічні заходи</b> — Аератори на кранах (насадки, що змішують воду з повітрям) скорочують витрату без відчутного зниження напору. Двокнопковий зливний бачок. Перевірка кранів і бачків на протікання — постійна крапель може витрачати значні обсяги за місяць.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Збір і повторне використання</b> — вода після промивки круп, відварювання яєць (остигла) — для поливу рослин. Збір дощової води для городу — де є таке використання. Лід з морозильника, що тане — теж до рослин.</div></div><div class=\"final-note\">Виявлення і усунення витоків — найвища пріоритетність. Навіть невеликий витік з бачка або крану за місяць може скласти значні обсяги води.</div>"],
        [2112,"Свідоме споживання і мінімалізм","<div class=\"rule-note\">Свідоме споживання — не відмова від покупок, а обдумане рішення щодо кожної. «Купуй менше, але краще» — принцип, що зменшує і витрати, і відходи.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Правило 30 днів</b> — відклади нову покупку на місяць. Якщо бажання залишилось — купуй. Більшість імпульсних покупок відпадають самостійно. Особливо ефективно для одягу, гаджетів, домашнього декору.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Альтернативи новому</b> — ремонт замість заміни (ремонт взуття, техніки); купівля вживаного (OLX, Шафа, тематичні групи у соцмережах); оренда замість купівлі (рідко потрібні інструменти, святкові речі, спортінвентар); обмін з сусідами і знайомими.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Зменшення упаковки</b> — торгові ринки і магазини з ваговим товаром без упаковки; власний пакет і авоська; відмова від одноразового пластику там, де є альтернатива (багаторазова пляшка, термокружка, контейнери для їжі).</div></div><div class=\"final-note\">Свідоме споживання — не аскетизм. Це критичне мислення перед кожною трансакцією: «Чи справді це потрібно? Чи є кращий спосіб?» Практика поступово стає автоматичною.</div>"],
        [2113,"Компостування харчових відходів","<div class=\"rule-note\">Органічні відходи (їжа, рослинні рештки) складають значну частину побутового сміття. Компостування перетворює їх на добриво замість метанового газу на звалищі.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Що можна компостувати</b> — Так: овочеві і фруктові рештки, яєчна шкаралупа, кавова гуща і фільтри, чайне листя, скошена трава, листя, тирса (без лакофарбових покриттів). Ні: м’ясо, риба, жирна їжа (приваблює гризунів), хвора рослинність, цитрусові у великій кількості.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Компостування в квартирі</b> — вермикомпостер (черв’ячна ферма): контейнер з каліфорнійськими хробаками, компактний, майже без запаху, дає рідке добриво і гумус. Bokashi: японська система анаеробного бродіння в закритому контейнері, підходить навіть для м’яса.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Компостування на ділянці</b> — відкритий або закритий компостер (пластиковий або дерев’яний ящик). Шари: «зелені» (свіжі відходи, азот) + «коричневі» (сухе листя, картон, тирса — вуглець). Баланс 1:3. Перемішування раз на 2–4 тижні прискорює процес. Готовий компост — за 3–12 місяців.</div></div><div class=\"final-note\">Компост — повноцінне органічне добриво для городу і кімнатних рослин. Навіть без ділянки вермикомпостер у квартирі скорочує органічні відходи і дає «чорне золото» для квітів.</div>"],
        [2114,"Екологічний транспорт і пересування","<div class=\"rule-note\">Транспорт — одне з найбільших джерел CO₂ у побуті. Вибір способу пересування має реальний вплив на особистий вуглецевий слід.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Пріоритет вибору транспорту</b> (від більш до менш екологічного): пішки → велосипед → е-транспорт → громадський транспорт → карпулінг → особисте авто. Це орієнтовна ієрархія — залежить від відстані і завантаження.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Велосипед і мікромобільність</b> — для відстаней до 5–10 км часто швидше ніж авто (у пробці) і без витрат на пальне і паркінг. Електросамокат і е-велосипед розширюють радіус без фізичних зусиль. Вартість утримання — суттєво нижча за авто.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Авіаперельоти</b> — один трансатлантичний перельот додає значний обсяг CO₂ до особистого вуглецевого сліду. Якщо потрібно летіти — прямі рейси мають менший питомий слід, ніж з пересадками. Компенсаційні програми (carbon offset) — існують, їх ефективність дискутується у науковій спільноті.</div></div><div class=\"final-note\">Перехід на е-транспорт знижує викиди лише якщо джерело електрики «чисте». В Україні е-авто все одно зазвичай вигідніші за ДВЗ, але розрив менший, ніж в країнах з переважно відновлюваною генерацією.</div>"],
        [2115,"Екологічні покупки: як читати маркування","<div class=\"rule-note\">Маркування на продуктах може бути реальним, а може — «зеленим вошингом» (greenwashing). Вміння розрізняти — корисна навичка свідомого споживача.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Визнані сертифікати</b> — FSC (лісова продукція: деревина, папір): перевіряє відповідальне лісогосподарювання; EU Ecolabel (євролисточок): офіційна екомарка ЄС; Fairtrade: справедлива торгівля (кава, чай, какао); Blue Angel (Blauer Engel): найстарша екомарка, Німеччина; EU Organic: органічне виробництво.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Червоні прапорці (greenwashing)</b> — розмиті слова без пояснення: «екологічний», «зелений», «натуральний», «біо» без сертифіката; зображення природи без підтвердження; заяви типу «100% перероблено» без вказівки матеріалу; «CFC-free» — це вже стандарт за законом, не досягнення.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Практична перевірка</b> — Good On You (одяг і мода) — додаток для перевірки практик компаній. EWG Skin Deep (косметика) — база даних безпеки інгредієнтів. Офіційні реєстри сертифікацій: наприклад, fsc.org/en/check-your-source.</div></div><div class=\"final-note\">Відсутність сертифіката не означає поганий продукт — сертифікація коштує грошей і недоступна малому бізнесу. Питай виробника напряму і дивись на склад, а не тільки на упаковку.</div>"],
        [2116,"Зелені насадження вдома і у місті","<div class=\"rule-note\">Рослини — не тільки естетика. Вони покращують мікроклімат, знижують стрес і прикрашають помешкання. Їх вплив на якість повітря у квартирі — реальний, але обмежений.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Кімнатні рослини і якість повітря</b> — дослідження NASA (1989) виявило здатність деяких рослин поглинати летючі органічні сполуки. Однак, за пізнішими дослідженнями, у реальних умовах квартири ефект скромний без великої кількості рослин. Основна цінність — мікроклімат, зволоження і психологічний ефект.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Невибагливі рослини для початківців</b> — Сансевієрія: витримує тінь і нечасте поливання; Потос: росте в будь-яких умовах; Алое: мінімум поливу, практичне застосування; Монстера, філодендрон: невибагливі; Суккуленти і кактуси: мінімум уваги.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Участь у міському озелененні</b> — долучайся до прибирань і висадок дерев через місцеві ОСББ, громадські організації. Перевіряй наявність міських програм озеленення у своєму місті.</div></div><div class=\"final-note\">Не купуй рослини з вирубаних природних місць проживання (кактуси і орхідеї можуть продаватись нелегально). Перевіряй джерело або купуй у розплідниках з документами.</div>"],
        [2117,"Енергетичні субсидії і пільги в Україні","<div class=\"rule-note\">Держава надає субсидії на оплату житлово-комунальних послуг. Знання умов дозволяє отримати реальну фінансову підтримку.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Хто має право на субсидію</b> — громадяни України, які фактично проживають і зареєстровані за адресою, де оплачуються ЖКП. Умови змінюються — актуальна інформація на сайті Мінсоцполітики (msp.gov.ua). Як правило, враховується наявність дорогого майна і депозитів понад встановлений ліміт.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Як оформити</b> — через кабінет на порталі Дія або особисто у ЦНАП. Потрібно: паспорт, ідентифікаційний код, документи на право власності або проживання, відомості про доходи домогосподарства. Субсидія призначається на 6 або 12 місяців, потім потрібне переоформлення.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>«Монетизація» субсидії</b> — з 2019 р. невикористані субсидійні кошти можна отримати готівкою або на картку. Умова: споживати менше за встановлену норму (дотримуватись ощадного режиму). Це стимул реально економити ресурси.</div></div><div class=\"final-note\">Пільги на ЖКП — окрема категорія для ветеранів, осіб з інвалідністю, чорнобильців та ін. Перелік і умови — на сайті msp.gov.ua. ВПО мають право на окремі виплати і допомогу — також через Дію або ЦНАП.</div>"],
        [2118,"Участь у громадському екологічному житті","<div class=\"rule-note\">Індивідуальні дії мають обмежений масштаб. Колективна дія — місцеві ініціативи, петиції, громадські слухання — змінює системи.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Місцеві ініціативи</b> — прибирання території (Clean Up Ukraine та ін.); висадка дерев через ОСББ або з міською програмою; роздільний збір у своєму будинку (ініціатива перед ОСББ або ЖЕКом); клопотання до органів місцевого самоврядування щодо встановлення контейнерів для сортування.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Правові інструменти</b> — громадські слухання (обов’язкові перед будь-яким великим будівництвом або змінами генплану): ти маєш право бути почутим; екологічна петиція на місцевій раді або президентській платформі; звернення до Держекоінспекції при виявленні порушень (наприклад, незаконне звалище).</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Моніторинг повітря і даних</b> — savEcoBot (Telegram): якість повітря за даними датчиків; AirVisual / IQAir: глобальна карта якості повітря; участь у citizen science проєктах (GlobalForestWatch, iNaturalist).</div></div><div class=\"final-note\">Навіть одна людина, яка регулярно повідомляє про порушення або бере участь у слуханнях, впливає на локальне середовище. Колективний вплив громади — найефективніший інструмент місцевих змін.</div>"]
      ]
    }]};
if(window.__catLoaded)window.__catLoaded(4,CAT_4);